pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space zone: small unusable gaps (1..=9) are heavily penalized,
    // scaled by how far into the dead zone we land.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 30.0;
    }

    // Moderate waste (10..=20) mild penalty: space likely still reusable
    // for small items but wasteful relative to a tighter fit.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing
    // bins when many are open; makes new-bin candidate less attractive.
    score += open_bins_count as f64 * 3.0;

    // New-bin candidate handling: empty bin has large post_residual naturally;
    // adjust so it wins only when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score -= 150.0;
        // Prefer new bin if the next item is large and current item is large too
        // (avoids fragmenting existing bins with big items).
        if next_item_size > 50 && item_size > 50 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 120.0;
    }
    // If next item fits into post_residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would NOT fit into post_residual, penalize leaving that gap.
    else if next_item_size > 0 && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins tighter than average residual (better fill).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: minimize post residual, with non-linear shaping
    let mut score = r + 12.0 * rn * rn * cap;

    // Smooth progress coupling: later in stream, weight residual more strongly
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Penalize dead space relative to capacity non-linearly
    score += 20.0 * rn * rn * rn * cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly unless post residual is very tight
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).powi(3);
        score = 60.0 * (1.0 - tightness) + 40.0 * progress;
    }

    // Lookahead: reward bins whose post residual fits next item smoothly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * fit_quality * fit_quality;
    }

    // Penalize bins with residual far above mean (fragmentation avoidance)
    let dev = (r - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in the "small residue" band
    // (1..=10) is nearly unusable for items in [1,100] with typical sizes >=10,
    // so penalize it hard.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 25.0;
    } else if pr > 10 && pr <= 20 {
        score += 8.0;
    }

    // Integer-division thresholds on post_residual: classify residual into
    // capacity-fraction buckets; mid-size residuals are the most valuable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > half {
        score -= 6.0; // still roomy, good
    } else if pr > quarter {
        score -= 2.0;
    }

    // Modulo arithmetic: residuals congruent to small values mod 10 pair well
    // with typical item granularities.
    let m = pr % 10;
    if m == 0 {
        score -= 4.0; // clean multiple of 10, reusable
    } else if m >= 8 {
        score += 3.0; // awkward leftover
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 12.0;
        } else {
            score -= (10.0 - slack as f64 / 10.0).max(0.0);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize more if residual is tiny anyway
        if pr <= 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 10 {
            score += 20.0; // but a nearly-dead bin is not worth it
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer using it only when open bins are few or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.3;
    }

    // Mild pressure to consolidate: fewer open bins -> favor existing bins.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += (open_bins_count as f64) * 1.5;

    // If the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits in post_residual, mild reward; if not, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Baseline moderate score; last-chance open bins should beat it.
        score = 45.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild deviation penalty relative to mean residual (balance-aware).
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    // Progression: later in the stream, slightly favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tight_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space: small residuals that likely become unusable.
    if post_residual < item_size {
        score += 8.0 * (item_size as f64 - post_residual as f64);
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins can fit the item, penalize picking this one slightly
    // (prefer concentrating items / leaving flexibility).
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor low score for empty bins); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive later.
        score -= 10.0 * (1.0 - progress);
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress; // favor reusing open bins late
    }

    // Global residual state: if mean residual is high, prefer filling bins
    // with large slack; if low, tight fits matter more.
    if mean_residual > post_residual as f64 {
        score += 0.5 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.3 * (post_residual as f64 - mean_residual);
    }

    // Slight penalty for bin sprawl when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (2-step perfect match)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap.min(40.0);
        if gap == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits overall (small post residual relative to mean residual)
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if item is large or residuals are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0
