pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual usable by lookahead: reward proportional to reusability
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // dead space penalty grows with how far below next item it falls
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalty for spreading across many open bins
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: neutral baseline, slightly discouraged unless current bin would be wasted
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count == 1 {
            // opening a fresh bin is fine here
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 800.0; // chain of two perfect fits
        } else {
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space more strongly
        // when leftover is small (unusable) relative to item size range.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 150.0; // tiny unusable sliver
        } else {
            score += 0.5 * dead;
        }
    }

    // Prefer bins with residuals below the mean (tighter bins first),
    // penalize placing into loose bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) * -1.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: default mild penalty; only wins if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 50.0;
        // Early in the stream, allow opening bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 100.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 120.0;
        }
    }

    // Late in the stream, prefer closing out bins (avoid spreading).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual > 0 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item fills bin, next item fills remainder.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect chain: this bin becomes ideal for the next item
        } else if post_residual > next_item_size {
            // leftover after next item would still fit; mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
