            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Penalize leaving unusably small residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Favor tighter fits relative to mean residual across open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or item huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 150.0 * pressure; // costly when open bins still have room
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 120.0; // pair the next two items in a fresh bin
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_u = bin_capacity;
    let cap = cap_u as f64;
    let post_u = post_residual;
    let post = post_u as f64;
    let next_u = next_item_size;
    let next = next_u as f64;

    let mean = mean_residual.clamp(0.0, cap);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic partition: 8 capacity classes.
    let unit_u = (cap_u / 8).max(1);
    let unit = unit_u as f64;
    let post_class = (post_u / unit_u) as f64;
    let next_class = if next_u == 0 { 0.0 } else { (next_u / unit_u) as f64 };
    let item_class = (item_size / unit_u) as f64;

    let mut score = post;

    // Exact closure is dominant.
    if post_u == 0 {
        score -= 1.60 * cap;
    }

    // Two-item harmonic lookahead.
    if next_u > 0 {
        if post_u >= next_u {
            let after_u = post_u - next_u;
            let after = after_u as f64;

            // Approximate the residual remaining after placing the lookahead item.
            score -= next;

            if after_u == 0 {
                score -= 0.75 * cap;
            }

            // Reward residuals that remain in a class able to repeat the next item.
            let after_class = (after_u / unit_u) as f64;
            if after_class >= next_class {
                score -= 0.05 * unit;
            } else {
                score += 0.08 * (next - after).min(unit);
            }

            // Mild preference for leftovers near harmonic boundaries.
            let mod_after = after_u % unit_u;
            let boundary_dist = mod_after.min(unit_u - mod_after) as f64;
            score -= 0.02 * (unit - boundary_dist);
        } else {
            let gap_u = next_u - post_u;
            let gap = gap_u as f64;
            let class_gap = next_class - post_class;

            // A residual just below the next item's class is especially wasteful.
            let near_miss = if gap_u <= unit_u || class_gap <= 1.0 {
                1.25
            } else {
                1.0
            };

            // If mean residual suggests another open bin can take the next item,
            // reduce the estimated cost of opening a future bin.
            let alt_hint = if mean >= next {
                0.55
            } else if mean >= 0.50 * next {
                0.78
            } else {
                1.0
            };

            let extra_bin_cost = (cap - next).max(0.0) * alt_hint;
            score += near_miss * (0.45 * gap + 0.70 * extra_bin_cost);
        }
    }

    if is_new_bin {
        let mut new_penalty = if fitting_bins_count == 0 {
            0.03 * cap
        } else if fitting_bins_count == 1 {
            0.20 * cap + 0.18 * cap * progress
        } else {
            0.40 * cap
                + 0.22 * cap * progress
                + 0.015 * cap * (open_bins_count as f64).min(8.0)
        };

        // Existing bins are nearly full: opening another bin is less harmful.
        if mean < 0.20 * cap {
            new_penalty *= 0.85;
        }

        // Harmonic item-class adjustment.
        if item_class <= 1.0 {
            new_penalty += 0.03 * cap;
        } else if item_class >= 4.0 {
            new_penalty -= 0.02 * cap;
        }

        // High mean residual means existing capacity is plentiful; avoid fragmentation.
        if mean > 0.50 * cap {
            new_penalty += 0.04 * (mean - 0.50 * cap);
        }

        if fitting_bins_count > 0 {
            new_penalty = new_penalty.max(0.12 * cap);
        }

        score += new_penalty.max(0.0);
    } else if fitting_bins_count == 1 {
        // Last-chance open bin: reward using it before opening a new bin.
        score -= 0.08 * cap;
        score += 0.02 * (post - mean).clamp(-cap, cap);
    } else {
        // Mild compactness preference relative to the current open-bin field.
        score += 0.02 * (post - mean).clamp(-cap, cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residuals are "dead space".
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Penalize gaps that are too small to be useful for typical future items.
        let dead_threshold = 35.0;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * 2.5; // harsh penalty for tiny gaps
        } else {
            score -= (pr - dead_threshold) * 0.3; // mild reward for large usable gaps
        }
    } else {
        // Perfect fill is excellent.
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't use this gap: penalize proportionally to wasted potential.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if open bins are already loose, prefer tight fits here.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += (mean_residual / bin_capacity as f64) * 20.0 * (1.0 - tightness);

    // New-bin candidate: only attractive when current bin would leave nasty dead space
    // or no bin fits well. Base new-bin score should be moderately high.
    if bin_residual == bin_capacity {
        score = 70.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 1 {
            // An existing last-chance bin beats opening a new one.
            score += 40.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0; // big item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to hold even the smallest plausible item.
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // likely dead space for most items
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it still fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 {
            score += 10.0; // blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer opening a bin only under pressure or for large items.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        score += 30.0 - 35.0 * pressure;
        if item_size > 70 {
            score -= 20.0; // big items pair well in fresh bins
        }
    }

    // Open-bin pressure: mild reward for consolidating into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Prefer filling tighter bins (small residual relative to capacity).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Slight preference for bins below the mean residual (keeps residuals balanced).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

