}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, prefer tight fits more aggressively.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * it * (0.5 + 2.0 * progress) * 2.0;

    // Penalize large dead space super-linearly, scaled by progress.
    score += (pr / cap) * (pr / cap) * (20.0 + 40.0 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
