pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 800.0; // chain of two perfect fits
        } else {
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space more strongly
        // when leftover is small (unusable) relative to item size range.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 150.0; // tiny unusable sliver
        } else {
            score += 0.5 * dead;
        }
    }

    // Prefer bins with residuals below the mean (tighter bins first),
    // penalize placing into loose bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) * -1.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: default mild penalty; only wins if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 50.0;
        // Early in the stream, allow opening bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 100.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 120.0;
        }
    }

    // Late in the stream, prefer closing out bins (avoid spreading).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual > 0 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;  // marginal space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize leaving large gaps slightly
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, be more tolerant of new bins (waste matters less)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 30.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // opening a new bin is more attractive if open bins are fragmented
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global fragmentation signal: if mean residual is high, prefer bins
    // below the mean (consume the "fattest" residual less aggressively),
    // pushing toward balanced usage
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild preference for bins whose residual is close to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm)
        - 2.0 * progress * (1.0 - pr_norm) * (1.0 - pr_norm) * cap * 0.05;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 0.3 * (1.0 - progress) * (pr - ni).min(20.0);
        }
    }

    // Last-chance fitting bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Mild pull toward bins with residuals near the mean (balance)
    score += 0.02 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalized mildly so good fits win
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are highly reusable; large residues waste space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual <= 10 -> near-perfect fit, big reward.
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 25 {
        score -= 25.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    }

    // Modulo-10 harmonic band: residues that are multiples of 10 align with
    // the 10-multiple item grid typical of these streams.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    // (perfect chaining), penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= 20.0 - (npr as f64).min(20.0);
            if npr <= 5 {
                score -= 15.0;
            }
        } else {
            // next item cannot fit here: residue becomes dead space unless small
            score += (pr / cap) * 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are
    // all poor fits (handled by the above rewards). Scale with stream progress.
    if bin_residual == bin_capacity {
        score += 45.0 + 25.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to consolidate: prefer fuller bins when many bins are open.
    score -= (1.0 - pr / cap) * (open_bins_count as f64).min(20.0);

    // Small tie-breaker toward bins below mean residual (tighter packs).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // An exact fit is a perfect placement -> heavy reward.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead space: residual too small to ever hold the smallest item (1..100 range).
        // Treat residuals below a "useful threshold" as wasted capacity.
        let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.10);
        if (post_residual as f64) < dead_threshold {
            // Penalize proportionally to how close we are to a full waste.
            score += 200.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
        // Gaps that cannot fit the known next item are less valuable.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0;
        }
        // Gaps that exactly fit the next item are gold: chain the fit.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 250.0;
        }
    }

    // Open-bins pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or when open bins are nearly full on average (poor fits everywhere).
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score += 150.0 - 100.0 * tightness;
        if item_size >= bin_capacity / 2 {
            score -= 80.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Reserve fresh bins for pairing large items.
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is closest to the item (tight packing signal).
    let tightness_gap = (bin_residual as f64 - item_size as f64).abs();
    score += tightness_gap * 0.5;

    // Slight preference for filling bins that deviate below the mean residual
    // (they are the emptiest candidates for becoming dead space).
    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Next item fits into the post residual (soft lookahead reward)
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (post_residual - next_item_size) as f64;
        score -= 10.0;
    }
    // Next item won't fit: post residual becomes dead space until more items arrive
    else if next_item_size > 0 {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable leftovers relative to mean residual
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 5.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discard tiny residuals below the minimum item size (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Prefer filling already-open bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 10.0; // near-dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (slack_after_next as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin unless fit is terrible
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: empty bins compete; make them attractive only when
    // global residuals are high (fragmented state) or fit is poor
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // discourage new bins early / when mean residual low; encourage when fragmented
        score += 20.0 + 40.0 * (1.0 - fragmentation) - 25.0 * fragmentation * progress;
        // if current item is large, a fresh bin is natural
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing fuller bins
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * residual_gap;

    // Slight preference to keep bins balanced as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its non-linear shaping
    let r = post / cap;                       // in [0,1]
    let r2 = r * r;
    let r3 = r2 * r;

    // Base: post residual, with convex penalty on large leftovers (dead space)
    let mut score = post as f64 * (1.0 + 2.0 * r2 + 1.5 * r3);

    // Tight-fit reward: strong when item fills most of the bin
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - r);

    // Stream progress coupling: as stream advances, tolerate larger residuals less
    // (early on, keep flexibility; late, consolidate aggressively)
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score *= progress_coupling;

    // Interaction: progress x post-residual polynomial term
    score += 20.0 * progress * r2 * cap * 0.01;

    // Mean residual deviation: prefer bins close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: penalize if next item fits poorly in resulting residual
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            cap // next item won't fit: treat as worst case
        };
        let g = gap / cap;
        score += 12.0 * g * g;
        // Reward exact-chain fit (next item perfectly consumes remainder)
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate shaping: make empty bin attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let mean_r = mean_residual / cap;
        let desperation = mean_r * mean_r + (1.0 - progress) * (1.0 - progress) * 0.5;
        score = cap as f64 * (1.2 - 0.7 * desperation);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible by
    // common small item sizes (10,20,25,50) are more reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { bonus += 2.0; }
        if pr % 20 == 0 { bonus += 1.5; }
        if pr % 25 == 0 { bonus += 1.0; }
        if pr % 50 == 0 { bonus += 2.0; }
    } else {
        // perfect fill is best
        bonus += 12.0;
    }
    score -= bonus;

    // Penalize tiny unusable dead space (residual < 10 cannot fit anything)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual match a harmonic class of next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // exact / modular compatibility with the next item
            if pr % next_item_size == 0 {
                score -= 4.0;
            }
            // next item leaves a "nice" residual too
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 { score -= 1.5; }
        } else {
            // next item cannot use this bin's leftover anyway
            score += 1.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize so we only open when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
        // but if the item is large and mean residual is small, new bin is fine
        score -= (item_size as f64 / 100.0) * 10.0;
    }

    // Tight-packing reward: residual close to item size means good fit
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 3.0;

    // Slight drift with stream progression: pack tighter early, stay flexible late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 1.0;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..=10) are unusable dead space -> heavy penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Marginal zone: only usable by small future items.
        score += 8.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins with below-average residual (fill the emptiest-ish bins
    // that still fit, keeping tight bins for tight items).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement (creates a perfect follow-up).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit (post_residual of this candidate is bin_capacity - item_size).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing bins with reasonable fit win.
        score += 18.0;
        // But if the new bin would leave a small dead space too, penalize more;
        // if it leaves a large usable residual, soften the penalty.
        if post_residual <= 10 {
            score += 40.0;
        } else if post_residual >= 40 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to fill residuals); late in the stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
