pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // creates dead space relative to lookahead
        }
        // Perfect pairing: item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly so we
    // only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * (open_bins_count as f64);
        // But if no open bin fits, opening is fine (fitting_bins_count excludes new bin).
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer using bins with larger residuals when global residuals are high.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Mild time-decay pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early in stream: tolerate larger residuals slightly less (explore),
    // late in stream: strongly penalize wasted space.
    let progress_coupling = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += progress * (pr * pr) / (cap * cap) * 30.0;
    score -= progress_coupling * 10.0 * (1.0 - progress);

    // Reward bins whose residual matches the next item size smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap) * 15.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight preference for bins below mean residual (tighter than average)
    score -= (mean_residual - pr) * 0.05;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify leftover space by integer division
    // into buckets of 10. Small buckets are "dead space" classes -> penalize.
    let residual_class = post_residual / 10;
    let dead_penalty: f64 = match residual_class {
        0 => 60.0,               // 0-9: nearly full, but zero utility for future items (min size 1)
        1 => 25.0,               // 10-19: fits only tiny items
        2 => 12.0,               // 20-29
        3 => 6.0,                // 30-39
        4 => 3.0,                // 40-49
        5 => 1.0,                // 50-59
        _ => 0.0,                // large residual, fine
    };
    score += dead_penalty;

    // Harmonic reward: residual divisible by common item sizes is reusable.
    // gcd-style harmony check on post_residual with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: strong reward proportional to snugness
            let snug = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 20.0 + 15.0 * snug;
        } else {
            // next item won't fit: penalize, worse if this bin becomes a 1-item dead bin
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, prefer consolidation.
        let new_bin_bias = 8.0 + 25.0 * progress;
        score += new_bin_bias;
        if mean_residual < 30.0 && open_bins_count > 0 {
            score -= 15.0; // all bins nearly full -> fresh bin is good
        }
    }

    // Modulo harmony: residuals that are multiples of 10 align with the size grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score += (item_size as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold the minimum item (1..=9)
    // are unusable dead space; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 2.0 * (item_size as f64) / (bin_residual as f64 + 1.0);

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive if current fit would leave bad dead space
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if placing here would create dead space in an existing bin, new bin looks better.
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0;
        }
        // Lookahead: if next item could combine with the post_residual, favor staying.
        if next_item_size > 0 && next_item_size <= post_residual && post_residual >= 10 {
            score += 15.0;
        }
    } else {
        // Lookahead synergy: if next item exactly fills the post-residual, reward strongly.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit the leftover; leftover likely becomes dead space.
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64).abs();
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    // Slight preference for compacting bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += 0.1 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) with a nonlinear bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving a sliver the next item cannot use.
            score += 8.0;
        }
    } else {
        // End of stream: just minimize waste.
        score += post_residual as f64;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 10.0 * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early on, be more willing to open new bins (less penalty);
    // later, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // mean residual across open bins is still large.
        score += 25.0 * progress + 0.3 * mean_residual.max(0.0);
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0; // fresh bin fits next item comfortably
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for bins far below mean residual (avoids fragmenting).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let tight = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward tight fits more strongly as the stream advances (smooth, non-linear)
    score -= tight * tight * (30.0 + 70.0 * progress * (1.0 - progress + progress * progress));

    // Penalize dead space that cannot fit a typical future item (smooth threshold)
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += dead * dead * 120.0;

    // Last-chance bonus (smooth ramp, not hard switch)
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 40.0 * last_chance * last_chance;

    // Slight preference for bins deviating from the mean residual (variance shaping)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 20.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 25.0 * (-gap / cap);
        }
    }

    // New-bin candidate: mildly penalize early, allow late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 4 quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=3

    // Penalize residuals in awkward harmonic classes (dead space zones).
    match class {
        0 => score += 8.0,               // tiny sliver, nearly unusable
        1 => score -= 2.0,               // quarter-sized slot: useful
        2 => score -= 4.0,               // half-sized slot: very useful
        _ => {}                          // large residual, fine
    }

    // Modulo-10 harmony: residuals divisible by 10 pair well with common sizes.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.2;
        if post_residual == next_item_size {
            score -= 6.0; // perfect chaining
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin now but not after us -> mild penalty for stealing space.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: baseline anchored around mean residual + lookahead margin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = mean_residual + 14.0 - 6.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            new_bin_score -= 5.0;
        }
        // Many open bins with slack -> avoid opening yet another.
        new_bin_score += open_bins_count as f64 * 1.5;
        // Perfect fit into an open bin should always beat a new bin.
        if post_residual == 0 {
            new_bin_score += 100.0;
        }
        score = new_bin_score;
    }

    // Tight fits are excellent regardless of class.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small, unusable leftover gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny dead space: worst possible outcome.
            score += 120.0;
        } else if post_residual <= 20 {
            score += 45.0;
        } else if post_residual <= 35 {
            score += 12.0;
        } else {
            // Larger leftovers remain potentially usable; mild reward.
            score -= 8.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 200.0;
    }

    // Reward tight fits relative to the item size (relative waste matters).
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 30.0 * waste_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins;
    // opening a new bin (residual == capacity) becomes progressively less attractive.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 60.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is smaller than next item: dead space for the lookahead.
        score += 25.0;
    }

    // Mild phase term: early in the stream, be slightly more willing to open bins;
    // later, favor tightening existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Slight preference for bins with below-average residual (consolidate emptier bins less).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits snugly into post residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to how tight the 2-step fit is.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus if residual after the second item would be tiny (<= 10).
        if post_residual - next_item_size <= 10 {
            score -= 40.0;
        }
    }
    // Next item does NOT fit in post residual: penalize dead space,
    // worse when post_residual is small (unusable gap).
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += 25.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Penalize leaving residual far from the mean (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when no open bin gives a
    // good 2-step fit; otherwise keep it slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If next item is large relative to capacity, a fresh bin is safer.
        if next_item_size > 60 {
            score -= 45.0;
        }
        // Late in the stream, avoid accumulating many near-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 40.0;
        }
        // Many open bins already: discourage more sprawl.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild global pressure to fill bins tightly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space gets progressively cheaper).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating small, hard-to-use residuals (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - lookahead_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large gap unusable for next item.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: only the residual matters; reward consuming the bin fully.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state coupling: when many bins are open with large mean residual,
    // prefer filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        let gap_vs_mean = mean_residual - bin_residual as f64;
        // Prefer bins tighter than the mean (small residual relative to average).
        score += 0.15 * gap_vs_mean;
        // Encourage consolidation more strongly later in the stream.
        score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize opening new bins when existing mean residual
        // is large and we already have several open bins; allow it for big items
        // that would leave existing bins fragmented.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 18.0
            + 2.0 * open_bins_count as f64
            + 0.25 * mean_residual
            - 30.0 * item_frac * item_frac
            - 15.0 * progress;
    }

    // Slight preference for bins whose residual is an even multiple pattern
    // (heuristic coupling to common item sizes).
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.9 * t * t + 0.5 * t * t * t;
    let mut score = post * poly;

    // Penalize residuals that are too small to be useful (dead space), smoothly.
    let dead = ((norm_post - 0.2).max(0.0)) * 0.0; // placeholder kept zero
    let _ = dead;
    let tightness = (cap - post) / cap;
    score += 8.0 * (1.0 - tightness) * (1.0 - tightness);

    // Reward tight fits (low post residual) especially when bin is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * (1.0 - norm_post);
    }

    // Lookahead: favor bins whose post residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty when this bin is far above mean residual (fragmenting large gaps).
    score += 0.5 * (post - mean_residual).abs() / cap;

    // Encourage using existing bins as stream progresses (avoid excessive bin opening).
    score += 3.0 * t * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bins slightly less attractive unless item is large.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals in [1,10] are prime dead-space territory; multiples of common
    // item sizes (10,20,25,50) are reusable slots.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else if pr <= 10 {
        score += 12.0; // tiny dead space, nearly unusable
    } else {
        // reward residuals that are harmonic multiples of small denominators
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                bonus += 6.0;
            }
        }
        if pr % 5 == 0 {
            bonus += 2.0;
        }
        score -= bonus;
        // fractional fill: prefer bins that are harmonic fractions of capacity
        let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
        // integer division threshold: leftover in [11,25] is semi-usable
        if pr <= 25 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for wasting a tight slot
            if pr <= 10 {
                score += 5.0;
            }
        }
    }

    // Prefer tightest fit among many candidates via residual variance signal.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 2.0;
    }

    // Early stream: encourage opening bins to build diverse residual classes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress; // new bin cost grows as stream matures
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are wasted forever.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Open-bin pressure: encourage filling existing bins when many are open.
    score -= 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New empty bin candidate: only attractive when current fit is bad
    // or no open bin is a good home. Penalize opening new bins mildly,
    // more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * (1.0 - progress);
        // If item is large relative to capacity and fits poorly anywhere,
        // new bin becomes acceptable.
        if item_size as f64 > 0.5 * bin_capacity as f64 && post_residual >= bin_capacity - item_size {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual,
    // it is a "junk" bin; using it consolidates waste.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to post_residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item can't use leftover space: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.3;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist and fit is reasonable,
    // but allow it for large items that would leave awkward residuals elsewhere.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && item_size <= 50 {
            score += 120.0;
        }
        // new-bin bonus for big items (keeps large items isolated)
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // Slight stream-progression pressure: later in stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: near-perfect fits get strongly favored (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight * tight;

    // Penalize creating small, hard-to-fill dead space (1..=15 residual).
    if post_residual > 0 && post_residual < 16 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead item.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If mean residual is large, opening new bins is wasteful.
        score += 0.4 * mean_residual;
        // If the next item is large, a fresh bin is more defensible.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Global balance: prefer bins below mean residual when many bins are open.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * dev;
    }

    // Mild time decay: early on, be more exploratory with new space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial in post_residual with progress coupling
    let base = pr_norm - 1.7 * pr_norm.powi(2) + 0.9 * pr_norm.powi(3);

    // Progress interaction: later in stream, penalize large residuals more (waste matters more)
    let progress_coupling = progress * (0.6 * pr_norm.powi(2) - 0.3 * pr_norm);

    // Tight-fit reward: smooth function of post_residual relative to next item
    let next_fit = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        -0.9 * (-gap * 12.0).exp()
    } else {
        0.0
    };

    // Last-chance bonus: smooth, stronger early when bins are scarce
    let scarcity = open_bins_count as f64 / (1.0 + fitting_bins_count as f64);
    let last_chance = -0.4 * scarcity * (1.0 - pr_norm);

    // Mean residual deviation: prefer bins whose residual deviates from the pack mean
    let dev = (pr - mean_residual) / cap;
    let dev_term = 0.15 * dev * dev - 0.05 * dev;

    let score = base * 10.0 + progress_coupling * 10.0 + next_fit + last_chance + dev_term;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: classify by integer division into
    // capacity fractions (dead-space bands). Small unusable tails are bad.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1 fraction of capacity left

    // Dead-space band: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if frac < 0.35 {
        score += 8.0;
    }

    // Reward residuals that belong to "useful" harmonic classes:
    // multiples / near-multiples of common item sizes via modulo classes.
    let r = post_residual;
    if r >= 10 {
        let mut useful = 0u32;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80].iter() {
            if r % m == 0 { useful += 1; }
            if r >= *m && r - *m < 10 { useful += 1; }
        }
        score -= 6.0 * useful as f64;
    }

    // Lookahead coupling: if the next item cannot fit in post_residual,
    // this bin becomes dead space for the next step -> penalize by gap size.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits too: reward tight two-item packing.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding effect: many open bins -> prefer consolidating into existing
    // bins rather than opening more.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: residual == capacity. Give it a mid-range score so
    // it beats only genuinely bad fits (large post_residual / dead space),
    // but loses to any reasonable existing-bin placement.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight bonus for a fresh bin when the stream is early/mid.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 5.0 * (1.0 - progress);
        }
        return score;
    }

    // Mild tie-break: prefer bins whose residual is close to the mean
    // (keeps a balanced pool of residuals for future items).
    score += 0.15 * (post_f - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space zone: small unusable gaps (1..=9) are heavily penalized,
    // scaled by how far into the dead zone we land.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 30.0;
    }

    // Moderate waste (10..=20) mild penalty: space likely still reusable
    // for small items but wasteful relative to a tighter fit.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing
    // bins when many are open; makes new-bin candidate less attractive.
    score += open_bins_count as f64 * 3.0;

    // New-bin candidate handling: empty bin has large post_residual naturally;
    // adjust so it wins only when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score -= 150.0;
        // Prefer new bin if the next item is large and current item is large too
        // (avoids fragmenting existing bins with big items).
        if next_item_size > 50 && item_size > 50 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 120.0;
    }
    // If next item fits into post_residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would NOT fit into post_residual, penalize leaving that gap.
    else if next_item_size > 0 && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins tighter than average residual (better fill).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong bonus
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Graded penalty for mismatch, scaled by next item size
            score += diff * (0.4 + next_item_size as f64 / 200.0);
            // If next item cannot fit at all in post_residual, penalize dead space
            if (post_residual as u64) < (next_item_size as u64) {
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize bins far from mean residual (avoid fragmenting typical bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in stream: prefer closing bins tightly, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 10.0 + 40.0 * progress;
        // But if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Many open bins: discourage spreading, favor filling existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling: residual value decays in importance as stream progresses,
    // with a non-linear quadratic interaction term.
    let progress_coupling = 1.0 - 0.35 * t + 0.15 * t * t;
    score *= progress_coupling;

    // Dead-space penalty: post-residual that is small but nonzero is partly unusable.
    // Smoothly penalize residuals below the typical next-item scale.
    let dead_frac = 1.0 - (pr / cap).min(1.0);
    score += 12.0 * dead_frac * dead_frac * dead_frac;

    // Lookahead reward: if the next item fits into post_residual, strongly reward (subtract).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - (pr - nx) / cap; // tighter lookahead fit -> bigger bonus
            score -= 10.0 * fit_quality * (1.0 + 0.5 * (1.0 - t));
        } else {
            // Next item won't fit here: penalize proportionally to how much it misses.
            let miss = (nx - pr) / cap;
            score += 6.0 * miss * (0.5 + t);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + 0.5 * t);
    }

    // New-bin candidate shaping: an empty bin's score is adjusted so it is chosen
    // only when all open bins would create severe dead space.
    if bin_residual == bin_capacity {
        // Slight inherent bias against opening new bins, easing off late in the stream.
        score += 5.0 * (1.0 - t) * (1.0 - t);
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 4.0 * (item_size as f64 / cap);
    }

    // Mild attraction toward bins whose residual is near the mean (balanced packing).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills (post_residual % 10 == 0) are prized.
    let post = post_residual as u32;
    if post == 0 {
        score -= 60.0; // exact fit — ideal
    } else if post % 10 == 0 {
        score -= 25.0; // decadal residual is reusable by many item sizes
    } else {
        // penalize awkward residues; small residues (< 10) are dead space
        if post < 10 {
            score += 15.0 + (10 - post) as f64;
        }
        // residue classes: 5 and its multiples are semi-usable
        if post % 5 == 0 {
            score -= 8.0;
        }
    }

    // Harmonic coupling with the lookahead item: reward residuals that can host next_item_size.
    if next_item_size > 0 {
        if post >= next_item_size {
            let slack = (post - next_item_size) as f64;
            // prefer post_residual being an exact multiple-class match for next item
            if post == next_item_size {
                score -= 30.0;
            } else if (post - next_item_size) % 10 == 0 {
                score -= 18.0;
            }
            score -= slack.min(20.0) * 0.4;
        } else {
            // next item won't fit here; dead-end penalty grows with how close it is
            score += 6.0 + (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is bad (large post_residual
    // relative to capacity) or this is early in the stream where slack is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // a fresh bin is worth it if placing here would waste a lot
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score -= 30.0 * waste_ratio;
        }
        score += 12.0 * progress; // late in stream, prefer consolidating into open bins
        score += (open_bins_count as f64) * 0.5; // many open bins -> discourage more
    }

    // Mild pressure to keep mean residual low (tight packing across fleet).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Integer-division threshold: post_residual >= cap/2 is still broadly useful.
    if post_residual as f64 >= cap / 2.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the
    // smallest plausible item (<= 12) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0; // likely-dead zone
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If this bin can also fit the next item, reward (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If placing the item here kills the ability to fit the next item
    // while another bin could have handled it, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: when average residual is large, prefer
    // consuming bins with above-average residual less eagerly.
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced to open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is golden.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        if diff < 0.5 {
            // Perfect two-step match: strongly reward.
            score -= 200.0;
        } else {
            // Penalize proportional mismatch; dead space that cannot host next item.
            let rel = diff / nxt.max(1.0);
            score += rel * 40.0;

            // If post_residual can't fit next item at all, treat as dead space.
            if post < nxt {
                score += (nxt - post) * 1.5;
            } else {
                // Next item fits with slack left over; mild reward scaled by leftover utility.
                score -= ((post - nxt) / bin_capacity as f64) * 10.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual than the fleet average is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual <= 10 {
            // Nearly perfect fill, extra reward.
            score -= 20.0;
        }
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 20.0);
        score += 15.0 + pressure * 5.0;
        // But if no open bin fits and lookahead matches a fresh bin well, soften.
        if fitting_bins_count == 0 && next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= (30.0 - diff.min(30.0));
        }
    }

    // Slight preference for tightening bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tight_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space: small residuals that likely become unusable.
    if post_residual < item_size {
        score += 8.0 * (item_size as f64 - post_residual as f64);
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins can fit the item, penalize picking this one slightly
    // (prefer concentrating items / leaving flexibility).
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor low score for empty bins); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive later.
        score -= 10.0 * (1.0 - progress);
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress; // favor reusing open bins late
    }

    // Global residual state: if mean residual is high, prefer filling bins
    // with large slack; if low, tight fits matter more.
    if mean_residual > post_residual as f64 {
        score += 0.5 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.3 * (post_residual as f64 - mean_residual);
    }

    // Slight penalty for bin sprawl when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 20.0 * norm_pr * norm_pr * (0.5 + progress)
        - 15.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space more as the stream advances (fewer chances to fill gaps)
    score += 25.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits, especially for last-chance bins
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * (if fitting_bins_count == 1 { 2.0 } else { 1.0 });

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Slight penalty for spreading across many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;

    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" residue classes (multiples of 10) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit: best possible outcome
    } else {
        let class = pr % 10;
        // dead-space penalty grows for awkward residues
        score += (class as f64) * 0.35;
        // small leftovers (< 10) are nearly unusable: strong penalty
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
        // harmonic tier: leftovers in [10,20) are prime targets for
        // typical small items; reward them
        if pr >= 10 && pr < 20 {
            score -= 6.0;
        } else if pr >= 20 && pr < 30 {
            score -= 3.0;
        } else if pr > 50 {
            // large leftover is fine but wastes bin choice slightly less
            score -= 1.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so it
    // is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // if item is large, a fresh bin is more attractive
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Prefer bins below the mean residual (tighter bins) mildly.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Prefer using already-open bins when many are open.
    score -= (open_bins_count.min(20) as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the smallest plausible item threshold) are heavily penalized,
    // but a perfect (or near-perfect) fill is rewarded.
    let min_gap = 1.0;
    let dead_zone = 25.0; // gaps < ~25 are unlikely to host typical items
    if post > min_gap && post < dead_zone {
        // Quadratic penalty growing as the gap shrinks into the dead zone
        let depth = (dead_zone - post) / dead_zone;
        score += 40.0 * depth * depth;
    }
    if post == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward leaving room for the lookahead item if it fits exactly
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        if slack < dead_zone {
            let depth = (dead_zone - slack) / dead_zone;
            score -= 15.0 * (1.0 - depth);
        }
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        // Lookahead cannot use this bin's remainder: mild penalty
        score += 6.0;
    }

    // Open-bin pressure: prefer compacting into existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for tighter-than-average bins
    score += (post - mean_residual) * 0.3;

    // Mild late-stream tightening
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // both items fill the bin perfectly
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits too, but leaves a third residual
        let third = post_residual - next_item_size;
        score -= 40.0 - (third as f64).min(40.0);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space, worse when very small
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Last-chance bin: strong bonus to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless it's genuinely better than a tight fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a new bin is more attractive early when many items remain
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // Attractive if the item is large relative to capacity
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight penalty for leaving awkward tiny residuals (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver (min item size 1..100 -> keep threshold modest)
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits perfectly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_frac * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Global residual context: if this bin's residual is far above the mean, it is a
    // good candidate to absorb the item (keeps mean residual low and uniform).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: only attractive when item is large relative to capacity or
    // no open bin offers a decent fit; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 12.0 * desperation * (1.0 - big_item);
        score -= 4.0 * big_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Non-linear base: penalize large post residual, but with curvature
    // that depends on stream progress (early: prefer tight fits less strictly;
    // late: strongly prefer tight fits to avoid opening bins).
    let mut score = pr - 40.0 * pr2 + 30.0 * pr3;

    // Smooth progress coupling: weight tight-fit reward growing over time
    let tightness = 1.0 - pr_norm;
    score -= (0.5 + 1.5 * progress) * tightness * tightness * 20.0;

    // Mean residual interaction: penalize bins whose residual deviates from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth ramp)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = pr - nx;
        if fit_margin >= 0.0 {
            let m = (fit_margin / cap).min(1.0);
            score -= 15.0 * (1.0 - m) * (1.0 + progress);
        } else {
            score += 10.0 * (-fit_margin / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: smooth urgency bonus scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across too many open bins early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless residuals are large
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near 0 mod small integers
    // indicate residual space that other items can still tile cleanly.
    let pr = post_residual;
    let class_weight: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residue -> dead-space risk
    };
    score += class_weight;

    // Integer-division thresholds: penalize residuals too small for the
    // smallest possible item (1..100 unknown distribution; assume >= 10-ish
    // mass), but only mildly since sizes 1..100 are possible.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item divides the post_residual
    // space (exact tiling), penalize if next item barely fits or cannot.
    if next_item_size > 0 {
        if next_item_size <= pr {
            if pr % next_item_size == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the single fitting bin before
    // opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this item would leave a very
    // awkward residual in an existing bin, or stream is early and bins few.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Opening a fresh bin: baseline penalty so it is chosen only when
        // existing placements are bad; relax slightly as stream progresses
        // and open-bin count is low.
        score = 55.0 + 25.0 * (1.0 - progress) - 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If next item is huge, a fresh bin may serve it better.
        if next_item_size > 70 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins whose residual deviates
    // below the mean (tighter bins fill first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with larger residual relative to item
    // (avoid squeezing bins that could host larger future items).
    score -= 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items (1..100 range) are wasted. Penalize "unusable" gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: gap too small for the smallest possible item.
            score += 40.0;
        } else if post_residual < 25 {
            // Nearly dead: only very small items could still fit.
            score += 18.0;
        } else if post_residual < 50 {
            // Moderately tight gap: usable but risky.
            score += 6.0;
        }
    } else {
        // Perfect fit: completely eliminate the base residual score.
        score -= 100.0;
    }

    // Reward tight fits proportionally to how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use the leftover gap: penalize more when the gap is tiny.
            score += 8.0;
        }
    } else {
        // Last item in the stream: prefer closing bins out completely.
        score -= 12.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // avoid pushing the item into a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; a new empty bin should be penalized more
    // when open_bins_count is already high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 20.0 + 15.0 * open_bins_count as f64 + 10.0 * progress;
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate.
        score += new_bin_penalty;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if the average leftover across open bins is low,
    // bins are nearly full -> reward using this bin; if high, be pickier.
    if bin_residual != bin_capacity {
        if mean_residual < 20.0 {
            score -= 8.0;
        } else if mean_residual > 50.0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item fills bin, next item fills remainder.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect chain: this bin becomes ideal for the next item
        } else if post_residual > next_item_size {
            // leftover after next item would still fit; mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // next item cannot use the remainder; penalize dead space more when tiny
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Penalize leaving unusably small residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Favor tighter fits relative to mean residual across open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or item huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 150.0 * pressure; // costly when open bins still have room
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 120.0; // pair the next two items in a fresh bin
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fit is poor
    // and lookahead item is large (better to start fresh).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = 1.0 - fit_ratio.min(1.0);
        let lookahead_pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powi(2)
        } else {
            0.0
        };
        score = 60.0 + 50.0 * (1.0 - poor_fit) - 45.0 * lookahead_pressure - 20.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer
    // draining existing bins rather than fragmenting further.
    let drain_pressure = mean_residual / bin_capacity as f64;
    score += 15.0 * drain_pressure * (open_bins_count as f64).ln().max(0.0);

    // Slight preference to keep bin count low early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress);
    score += poly * cap * 0.35;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.2 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * cap * (0.6 + 0.8 * progress);
        // Reward leaving exactly enough room for the next item
        let match_fit = 1.0 - ((pr - nxt).abs() / cap);
        score -= match_fit.max(0.0) * cap * 0.25;
    }

    // Last-chance bonus: only bin that fits -> strong reward, decaying with progress
    if fitting_bins_count == 1 {
        score -= cap as f64 * (0.8 - 0.3 * progress);
    }

    // Mild regularization against proliferating open bins with large mean residual
    score += (open_bins_count as f64).ln() * mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap / 4.0;

    // Class A: post_residual == 0 -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: tiny dead space (<= 10) is nearly perfect.
    if post_residual > 0 && post_residual <= 10 {
        score -= 120.0;
    }

    // Class C: post_residual divisible by 8 -> "harmonic" residual, reusable by
    // many common item sizes (multiples of 8/16/25/50). Reward modulo harmony.
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 30.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Class D: integer division thresholds on post_residual.
    // Dead space in (0, quarter) is worst: unusable for most items. Penalize.
    if post_residual > 0 && (post_residual as f64) < quarter {
        score += 40.0 * (quarter - post) / quarter;
    }

    // Residual in a "harmonic band" (25..=50) is flexible: mild reward.
    if post_residual >= 25 && post_residual <= 50 {
        score -= 15.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size exactly or well?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits: reward tightness of that future fit.
            let future_residual = post_residual as u32 - next_item_size;
            score -= 20.0 + (future_residual as f64).min(60.0) * 0.5;
            if future_residual == 0 {
                score -= 60.0;
            }
            // harmonic bonus: post_residual is an exact multiple of next size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot use this bin's residual: penalize proportionally.
            score += 10.0 + nxt * 0.15;
        }
    } else {
        // Last item: prefer any fit, prefer tightest.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing residuals are poor (fragmented state).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs();
        // Base new-bin cost: discourage opening unless residuals are small.
        score += 90.0;
        // If mean residual across open bins is small (bad for future items),
        // a fresh bin becomes more attractive.
        score -= (mean_residual.min(100.0)) * 0.8;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
        // Avoid double counting fragmentation penalty for the fresh bin.
        score += fragmentation * 0.1;
    }

    // Mild preference for filling larger existing residuals when many bins open.
    if open_bins_count > 4 {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-dead zone: residuals 10..20 are only usable by tiny items.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit into post_residual but this bin is the
    // only fitting bin, avoid stranding the next item's options.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count == 1 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (mild, so bad dead space still wins over).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has no dead-space risk, but
    // opening bins is costly when many bins are already open. Make the
    // empty bin attractive only when open-bin pressure is low or fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced as pressure grows
        // (more open bins means consolidation matters less than spreading).
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 + 20.0 * pressure;
        // If item is large relative to mean residual, empty bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Mild open-bins pressure: encourage filling existing bins when few are open.
    if bin_residual < bin_capacity {
        score += 0.3 * open_bins_count as f64;
    }

    // Slight progression term: late in the stream, favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post_residual as f64 - nxt;
        if diff == 0.0 {
            score -= 60.0; // exact chain fit
        } else if diff > 0.0 {
            // next item fits after this one: reward proportionally
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit: penalize dead space proportional to gap
            score += (-diff).min(bin_capacity as f64) * 0.8;
        }
    }

    // Prefer bins tighter than the mean residual (good fits pack residual down).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (below minimum item size 1..100 unknown, use 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Slight bias toward using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 0.6;
    } else {
        // Perfect fill is highly desirable.
        score -= 40.0;
    }

    // Penalize dead space: residuals too small for the smallest item (1..100 range, assume min ~10 worst case).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Penalize placements that leave a residual just below the next item size
            // (wasted near-fit).
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // Last item: prefer perfect fill aggressively.
        score -= post_residual as f64 * 2.0;
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack elsewhere; prefer consolidating into bins with large residuals.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.25;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins tight for future flexibility); late in the stream, pack into
    // existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses,
        // unless it is a very early step or the fit elsewhere is terrible.
        score -= (1.0 - progress) * 20.0;
        score += progress * 30.0;
        // Opening a new bin early is fine when open_bins_count is already large.
        score += open_bins_count as f64 * 0.5 * (1.0 - progress);
    } else {
        // Existing bins get a mild late-stream preference.
        score -= progress * 5.0;
    }

    // Many open bins: encourage filling them rather than adding more.
    score += open_bins_count as f64 * 0.3 * progress;

    // Nonlinear coupling of fit tightness with lookahead feasibility.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: reward tight fits via quadratic in post_residual (dead-space penalty)
    let mut score = pr + 18.0 * pr_norm * pr_norm * cap;

    // Stream-progress coupling: early on, tolerate loose fits; late, demand tightness
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Non-linear interaction: post_residual x progress (small residuals matter more late)
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress * cap * 0.05;

    // Lookahead: if next item fits the post residual, strongly reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_ratio = nxt / pr.max(1.0);
            score -= 12.0 + 20.0 * fill_ratio * fill_ratio;
        } else {
            // next item won't fit: penalize by leftover gap magnitude
            score += 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean residual context: penalize bins far from the mean (anomalous residuals)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for too many open bins when a new bin is a candidate
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        // early stream: new bins are cheap
        score -= 10.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class bins into residue classes mod 10: residuals in [1,9] are "dead space"
    // classes (hard to fill with items >= 10), multiples of 10 are "harmonic".
    let dead = post_residual % 10;
    if post_residual > 0 {
        if dead == 0 {
            score -= 6.0; // harmonic residual: reusable
        } else if dead <= 3 {
            score += 18.0 - dead as f64 * 2.0; // tiny dead space, nearly useless
        } else if dead <= 9 {
            score += (9 - dead) as f64 * 1.5; // moderate dead space penalty
        }
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic check: next item leaves again a multiple-of-10 residual?
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
        score -= (next_item_size as f64) * 0.1; // larger next item => tighter chain
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how far off we are.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // --- Integer-division thresholds on bin fill fraction ---
    let fill_quintile = (bin_capacity - post_residual) / 20; // 0..=5
    score -= fill_quintile as f64 * 3.0; // prefer bins already well-filled

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0; // avoid opening a new bin if this is the only fit
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Only attractive when current bin would leave bad dead space
        // and lookahead also mismatches.
        let bad_dead = post_residual > 0 && post_residual % 10 != 0 && post_residual < 10;
        let lookahead_miss = next_item_size > 0 && post_residual < next_item_size;
        if bad_dead && lookahead_miss {
            score -= 15.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 0.5; // discourage new bins generally
        }
    }

    // --- Stream progression: tighten packing as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // --- Residual spread control: avoid extreme residuals vs mean ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items are 1..=100, but treat gaps < ~12 as near-wasted) are heavily penalized.
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    if bin_residual > 0 {
        score += (item_size as f64 / bin_residual as f64) * -10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins;
    // penalize the new-bin candidate more as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0 + 5.0;
        // But if next item is large and residuals are fragmented, opening fresh may help.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size as f64 > mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the post residual can still fit the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If placing here would leave a gap just below next item size, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild preference for bins with below-average residual (save roomy bins).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: item + next item fill bin
        }
        // Penalize leaving a residual that nothing useful can use later
        if post_residual < next_item_size && post_residual > 0 {
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // Last item: prefer tightest fit overall
        score += (post_residual as f64) * 0.5;
    }

    // Dead-space penalty: small unusable leftovers are bad
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare residual against mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no tight fit exists among open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Waste of capacity for small items; acceptable for near-full packing
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + waste * 0.4 - progress * 10.0;
        // If many bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 15.0;
        }
        // If no open bin fits (fitting_bins_count==1 refers to this new bin), allow it
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with less residual overall (best-fit flavor)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how well the next item fits the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Penalize leaving a residual too small for the known next item.
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual > 30 {
            // Poor fit on last chance: dampen the bonus.
            score += 10.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so open bins with decent fits win.
        score += 18.0;
        // As stream progresses, slightly discourage spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If many bins are open with large mean residual, prefer reusing them.
        score += 0.05 * (open_bins_count as f64) * (mean_residual / 10.0);
    } else {
        // Reward reusing bins that already have content, scaled by mean residual.
        score -= 2.0 * (mean_residual / 100.0);
    }

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Mild preference for balancing residuals toward the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Early stream: be more permissive with opening bins (exploration).
    let early = (step_index < total_items / 10) as f64;
    score -= 5.0 * early * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with progress-dependent weighting
    let mut score = pr * (0.9 + 0.6 * progress * progress);

    // Non-linear polynomial coupling of post-residual with progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress)
                 - norm_pr * progress * (1.0 - progress);
    score += 40.0 * coupling;

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 0.3 * (pr - mean_residual) * (norm_pr - 0.5);

    // Lookahead: reward leaving room for next item, smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).abs();
        let fit_norm = fit / cap;
        score -= 25.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - progress) * (pr >= nxt) as i32 as f64;
        score += 10.0 * (pr < nxt) as i32 as f64 * (1.0 - progress);
    }

    // Last-chance bonus: avoid opening new bins late in the stream
    let last_chance = (fitting_bins_count == 1) as i32 as f64;
    score -= 15.0 * last_chance * (0.5 + 0.5 * progress);

    // Mild penalty for proliferation of open bins, smoothed by progress
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);

    // Reward using existing bins vs. new bin (new bin has norm_pr = 1)
    score += 5.0 * (norm_pr - 1.0).abs() * (norm_pr - 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals in "dead zones": small but not tiny leftovers are hard to fill.
    // Harmonic classes via integer division thresholds (capacity / k).
    let q4 = post_residual / (bin_capacity / 4).max(1); // class 0..4
    let q8 = post_residual % (bin_capacity / 8).max(1); // modulo texture

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual < bin_capacity / 10 {
        // small dead space: penalize extra
        score += 40.0 * (1.0 - frac * 10.0);
    }

    // Class-based reward: quarter-class 0 is best, class 3 (large residual) is fine.
    score -= match q4 {
        0 => 120.0,
        1 => -60.0, // worst class: ~25-50 residual, awkward
        2 => 0.0,
        _ => 60.0,
    };

    // Modulo texture: residual divisible by common item sizes is more reusable.
    let pr_u = post_residual;
    if pr_u > 0 && (pr_u % 10 == 0 || pr_u % 20 == 0 || pr_u % 25 == 0) {
        score -= 25.0;
    }
    let _ = q8;

    // Lookahead: if next item fits the post residual exactly or well, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 150.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here; mild penalty for tight fills that strand space
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when current bin residual is very small
    // or the fit is terrible; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let tight = pr <= 15.0 && pr > 0.0;
        if tight {
            score -= 100.0; // better to open fresh bin
        } else {
            score += 60.0 + 0.3 * open_bins_count as f64; // prefer reusing open bins
        }
    }

    // Mild preference for fuller bins overall (tight packing).
    score -= 0.2 * (1.0 - frac) * 10.0;

    // Stream progression: later in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Mid-range residual is only useful if the next item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += 18.0;
        }
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer new bin only when all open bins
    // would leave bad dead space.
    if bin_residual == bin_capacity {
        let bad_fit_open = fitting_bins_count == 0
            || (post_residual < 10 && next_item_size > post_residual && next_item_size > 0);
        if bad_fit_open {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // If the next item exactly fills the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    // Mean residual coupling: when mean residual is low, conserve space.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward near-perfect fill (small post_residual).
    let cap = bin_capacity as f64;
    let fill_ratio = item_size as f64 / cap;
    score -= 18.0 * fill_ratio; // reward packing larger items tightly

    // Aggressive 2-step lookahead: ideal post_residual equals next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_err = (post_residual as f64 - nxt).abs();
        // Strong reward when the leftover exactly hosts the next item.
        score -= 25.0 * (1.0 - match_err / cap).max(0.0);
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        }
        // Penalize leftover that is too small for the next item (dead space),
        // but only mildly if leftover is tiny (near-perfect fill).
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize wasting a large-residual bin on a small item when many bins fit.
    if fitting_bins_count > 1 {
        let waste = post_residual as f64 - mean_residual;
        if waste > 0.0 {
            score += 0.15 * waste;
        }
    }

    // Contextual pressure: late in the stream or few open bins -> prefer reuse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    // New-bin candidate (residual == capacity): make it attractive only when
    // the item is large and no open bin offers a tight fit; otherwise deter it.
    if bin_residual == bin_capacity {
        if fill_ratio > 0.6 && fitting_bins_count == 0 {
            score -= 10.0 * fill_ratio;
        } else {
            score += 25.0 + 20.0 * fill_ratio;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residual too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (next_item_size as f64) * 0.2;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin when fit elsewhere is poor and mean residual is low
        let poor_fit = fit_ratio > 0.5;
        if poor_fit && mean_residual < 20.0 {
            score -= 35.0;
        } else {
            score += 50.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Time horizon: later in stream, be more aggressive about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // Prefer bins with residual close to mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight penalty for too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // normalized post residual in [0,1]
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64; // how tightly item fits

    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, prefer tight fits (large fit_ratio) less aggressively;
    // late in the stream, dead space becomes more costly.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * norm_post * norm_post * (0.5 + progress_poly);

    // Reward tight fits with a smooth saturating term
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - fit_ratio);

    // Penalize bins that would leave residual smaller than the next item
    // unless the next item fits exactly (smooth interaction, no hard cutoff)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - post).max(0.0) / cap;
        score += 15.0 * waste * waste * (1.0 - progress);
        // bonus if next item fits into post residual
        let fits_next = (nxt <= post) as i32 as f64;
        score -= 8.0 * fits_next * (nxt / cap) * (1.0 - progress_poly);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_post);
    }

    // Mild penalty for adding to a very fragmented pool of open bins
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 2.0 * open_norm * norm_post;

    // Prefer bins with residual close to the mean (balanced packing), smooth term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress_poly) + 6.0 * norm_post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;              // 0..10
    let post_class = post_residual / 10;          // 0..10

    // Reward tight fits: post_residual near zero is good
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Penalize dead space that no future item class can use:
    // residual slabs below the smallest item (10) are wasted unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic pairing: does next_item_size fit exactly or nearly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 100.0 - (slack as f64) * 3.0;
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            let overflow = next_item_size - post_residual;
            score += (overflow as f64) * 0.5;
        }
    }

    // Class complementarity: item_class + post_class == 10 means perfect pairing
    let complement = (item_class + post_class) as f64;
    if (complement - 9.0).abs() < 0.5 {
        score -= 150.0;
    }

    // Modulo logic on post_residual: residuals divisible by common item sizes
    // (e.g. multiples of 20, 25, 50) are reusable "harmonic" slots.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 80.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 40.0;
    } else if post_residual % 20 == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when the current bin would leave a bad residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // new bin baseline: cost = waste, discounted early, penalized late
        score = waste * (0.5 + progress) + 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0;
        }
    }

    // Prefer filling bins below mean residual (reduces fragmentation spread)
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    // Slight preference for fewer open bins when tight
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavy penalties.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tight fit relative to item size: small waste ratio is good.
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += waste_ratio * 20.0;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item fits poorly everywhere else (large item, poor existing fits).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        if item_size >= 70 {
            score -= 25.0; // huge items: a fresh bin is often best
        }
        if post_residual < 25 {
            score -= 15.0; // item nearly fills a fresh bin
        }
    }

    // Lookahead: if the next item would fit the post residual well,
    // reward this placement (sequencing synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0; // next item almost exactly fills the gap
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item can't use the leftover gap
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., we are closing out smaller bins first, keeping big gaps open).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: exact match between post_residual and next item ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect two-step fit: this bin becomes exactly filled by the next item.
        if post == nxt {
            score -= 60.0; // very strong reward
        } else if post >= nxt {
            // Next item fits here: reward proportional to how snugly it fits.
            let slack_after_next = post - nxt;
            score -= 25.0 - slack_after_next.min(25.0); // tighter chain fit => bigger reward
            // Extra reward if the two-step chain nearly exhausts the bin.
            if slack_after_next <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item will NOT fit in the leftover: penalize dead space,
            // scaled by how badly it misses and by stream progress.
            let miss = nxt - post;
            score += (miss * (0.3 + 0.7 * progress)).min(40.0);
        }
    } else {
        // Last item: reward tight closure.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // ---- Relative-to-mean residual coupling ----
    // Prefer bins whose residual is below-average (densely packed bins),
    // but avoid making the residual unusably small.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = post / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel); // denser than average: reward
        } else {
            score += 5.0 * (rel - 1.0).min(3.0); // looser than average: mild penalty
        }
    }

    // ---- Last-chance logic: if this is the ONLY bin that fits, use it ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no existing bin fits well:
        // penalize it so we prefer filling open bins, but not catastrophically
        // when open bins would leave huge dead space.
        let dead_elsewhere = if fitting_bins_count > 0 {
            // worst-case dead space if we place in an existing bin
            (bin_capacity as f64 - item_size as f64) * 0.5
        } else {
            0.0
        };
        score += 45.0 - dead_elsewhere.min(35.0);
    }

    // ---- Small dead-space shaping: leftover 1..9 is nearly unusable ----
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys capacity for the known next item.
            score += 10.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Mild pull toward mean residual: avoid leaving outliers.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: late in the stream, be conservative — favor existing bins,
    // penalize opening new bins (empty-bin candidate gets a rising penalty).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 14.0 + 30.0 * progress;
        // Early on, a fresh bin is fine if current bins would be badly fragmented.
        if post_residual < 5 && progress < 0.4 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual after placement stays "usable" (>= ~20)
    // unless the fit is near-perfect.
    if post_residual >= 20 && post_residual < 35 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), non-linearly penalize mid-range waste.
    let mut score = pr as f64;
    score += 40.0 * x * (1.0 - x) * (1.0 - x); // penalize half-empty bins (dead space)

    // Smooth stream-progress coupling: early on, tolerate waste to keep bins open;
    // later, strongly reward tight packing.
    let urgency = progress * progress;
    score -= 30.0 * urgency * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: if this is the only fitting bin, reward using it smoothly.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * urgency;
    }

    // Lookahead: if next item fits in post residual, reward leaving useful space.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / cap) * (1.0 - x);
        score -= 20.0 * fit_quality;
    } else if next_item_size > 0 {
        // Next item cannot use leftover space: penalize proportional dead space.
        score += 10.0 * (1.0 - x) * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure against proliferating many open bins early.
    score += (open_bins_count as f64).sqrt() * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals in "small" classes (<= 10) are near-perfect fills -> reward strongly.
    let class = post_residual % (bin_capacity / 4); // classes of size 25
    if post_residual <= 10 {
        score -= 40.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if class == 0 {
        score += 5.0; // residual exactly on quarter boundary: awkward
    }

    // Penalize dead space proportional to how unusable it is:
    // residual that cannot fit the smallest plausible item.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize if this was the only fitting bin
        if fitting_bins_count == 1 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins with decent fits,
    // but allow opening a new bin when all open bins would leave huge waste.
    if bin_residual == bin_capacity {
        let best_existing_penalty = if post_residual > 50 { 0.0 } else { 30.0 };
        score += 8.0 + best_existing_penalty;
    }

    // Prefer tighter fits overall: relative waste fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 20.0;

    // Coupling with mean residual: if this bin is below mean residual (tighter),
    // it is a good candidate -> reward.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in stream: consolidation matters more, penalize leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += waste_frac * progress * 25.0;

    // Integer-division threshold: post_residual / item_size ratio
    if item_size > 0 {
        let ratio = post_residual / item_size;
        if ratio >= 2 {
            score -= 5.0; // bin could hold another item of same size later: keep usable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 1..=100, but typical small items ~10+)
    // are pure waste. Penalize hard when post_residual falls into a "dead zone"
    // (1..10) — it can never be filled by an item of size >= 10.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0; // unusable sliver: heavily penalize
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strong reward
    } else {
        // Non-linear penalty on wasted fraction of the bin
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * waste_frac * waste_frac;
    }

    // Dead space is worse if the next item could have used this bin's residual
    // but won't fit after this placement (lookahead coupling).
    if next_item_size > 0 {
        if next_item_size > post_residual && next_item_size <= bin_residual {
            // We are "stranding" the lookahead item
            score += 12.0;
        }
        if next_item_size == post_residual {
            score -= 15.0; // chain fit: excellent
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than fragmenting space across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless this is a large item that would leave a bad gap elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0;
        // But if the item is huge relative to mean residual, a fresh bin is fine
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 35.0;
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinear penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Perfect fit: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills leftover
            let fill_after = post_residual - next_item_size;
            score -= 40.0 * (1.0 - fill_after as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space that blocks the chain
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance: strongly favor using the only bin that fits (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists;
    // penalize opening new bins early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin can chain two items: allow it
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fit quality: how much of the bin the item consumes
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits: post_residual close to 0 or small usable sliver
    let perfect_bonus = if post_residual == 0 {
        -60.0
    } else if post_residual <= 10 {
        -25.0
    } else {
        0.0
    };
    score += perfect_bonus;

    // Penalize dead space: residuals too small for typical items (1..100 unknown, assume >=10 useful)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Coupling with mean residual: prefer bins tighter than average
    let mean_diff = mean_residual - bin_residual as f64;
    score += 0.35 * mean_diff;

    // Lookahead: if next item fits into post_residual, big reward for this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.2 * next_item_size as f64;
    }
    // If next item would leave this bin's post_residual awkward, slight penalty
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so we prefer existing bins,
    // but the cost shrinks as the stream progresses and open bins get fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 - 8.0 * progress;
        // If item is large, opening a fresh bin is less costly
        score -= 0.15 * item_size as f64;
        // If many bins are open already, discourage spreading further early on
        score += 0.4 * open_bins_count as f64 * (1.0 - progress);
    } else {
        // Existing bin: slight reward scaled by how full it already is
        score -= 5.0 * fill_ratio;
    }

    // Non-linear residual shaping: convex penalty on large leftover residuals
    score += 0.05 * residual_ratio * residual_ratio * bin_capacity as f64;

    // Late stream: consolidation pressure — prefer bins that get very full
    if progress > 0.7 {
        score -= 10.0 * fill_ratio * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * pr * pr);

    // Smooth polynomial coupling with stream progress: later in stream, penalize wasted residual more
    score += 12.0 * progress * pr * (1.0 - pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item can use the post_residual
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let waste = (post - nxt).max(0.0) / cap;
        score += 6.0 * fits_next * waste * waste;
        score -= 4.0 * fits_next * (1.0 - waste);
    }

    // Penalize bins far from mean residual (fragmentation), scaled by open bins
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (1.0 + open_bins_count as f64).ln();

    // Mild bonus for filling bins nearly full (small post residual relative to item)
    score -= 3.0 * (item_size as f64 / cap) * (1.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more valuable (less dead space).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // capacity fraction

    // Modulo arithmetic on post_residual: treat residual in classes of 10.
    let class = (post_residual / 10) as f64;
    // Penalize residuals that are unusable for typical items (1..100):
    // a residual smaller than 10 is nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic penalty: residual just below common item sizes is wasteful.
    for k in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
        if post_residual > 0 && post_residual < k && bin_residual >= k {
            score += 4.0 * (k as f64 - post_residual as f64) / k as f64;
        }
    }

    // Reward tight fits: small post_residual relative to capacity.
    score -= 30.0 * (1.0 - frac) * (1.0 - frac);

    // Perfect fill bonus (modulo class 0).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly or
    // harmonically, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // current residuals are poor (fragmented) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base new-bin score: slightly worse than a decent fit.
        score = cap * 0.5 + 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
        // If open bins are highly fragmented, new bin becomes attractive.
        score -= 0.4 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is huge, a fresh bin with full capacity is valuable.
        if next_item_size > 50 {
            score -= 0.3 * next_item_size as f64;
        }
    }

    // Mild pressure against bin proliferation late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

