    }

    // Reward good tightness relative to residual used.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from open bin count: prefer reusing bins when many are open,
    // prefer opening new bins when few are open.
    score += 1.2 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only if the item would leave
    // large usable space and open bins are crowded or fit poorly.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64 / 8.0).min(1.0);
        let poor_fit = 1.0 - fill_ratio;
        score -= 10.0 + 20.0 * crowd * poor_fit;
        // Penalize opening a bin when the item is small (wasteful).
        score += 0.3 * item_size as f64;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // dead end for the known next item
    }

    // Mean residual coupling: avoid bins far below the mean (fragmentation).
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    // Slight progression bias: later in stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
