    }

    // Global fragmentation pressure: prefer bins with residual below mean
    // (consolidate small leftovers) when many bins are open.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15 * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be conservative (avoid wasting big bins);
    // late in the stream, prioritize closing out bins tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * tightness * 20.0;
    score -= t * (bin_residual as f64 - item_size as f64) * 0.1;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or the stream is early and item is big enough to anchor a fresh bin.
    if bin_residual == bin_capacity {
        let anchor_bonus = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 50.0 * anchor_bonus * (1.0 - 0.5 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm) * (1.0 + 0.5 * progress * progress);

    // Reward tight fits (small post_residual), stronger late in the stream.
    score -= (cap - post) * 0.15 * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt) * (1.0 + progress);
        } else {
            score -= 6.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - post_norm);
    }

    // Mild penalty when many bins are open and this fit is loose.
    score += 0.3 * (open_bins_count as f64) * post_norm * post_norm;

    // Discourage opening a new bin early unless it's genuinely needed.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (mod 10) are more likely reusable later.
    let r = post_residual;
    let residue_class = r % 10;

    // Reward small post_residual strongly (tight fit), with harmonic decay.
    let tight_bonus = match residue_class {
        0 => 6.0,   // perfectly divisible leftover
        5 => 4.0,   // half-decade leftover still useful
        _ => 1.5,
    };
    score -= tight_bonus;

    // Penalize dead space: leftover below the minimum item size (10) is wasted.
    if r < 10 && r > 0 {
        score += 12.0;
    }

    // Nonlinear penalty on large leftovers that no typical item can use:
    // leftover in (0, 20) is hard to fill; leftover >= 20 is flexible.
    if r > 0 && r < 20 {
        score += (20.0 - r as f64) * 0.8;
    }

    // Harmonic fraction of bin capacity used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Lookahead coupling: if next item fits exactly in the post_residual,
    // reward heavily (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 15.0;
        } else if next_item_size <= r {
            score -= 4.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover is stranded.
            score += (r as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate packing, keep large-residual bins for large items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Early stream: keep bins open and flexible; late stream: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // the current item is large and no tight fit is available.
    if bin_residual == bin_capacity {
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward gaps that can still host a typical item (usable slack).
    if post_residual >= 35 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 40.0; // would create a new dead gap for next item
        } else if post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // current item would leave a dead gap in every existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with good fits.
        score += 30.0;
        // Pressure grows with number of open bins (avoid bin sprawl).
        score += open_bins_count as f64 * 4.0;
        // But if placing here would create a dead gap, opening a fresh bin
        // becomes attractive: cancel the penalty.
        if post_residual > 0 && post_residual < 10 {
            score -= 90.0;
        }
        // If mean residual is small, existing bins are tight; new bin helps.
        if mean_residual < 15.0 {
            score -= 40.0;
        }
        // Late in the stream, avoid opening bins with large residual.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && item_size > 50 {
            score -= 20.0;
        }
    }

    // Mild open-bin pressure: fewer open bins is generally better, so
    // penalize bins slightly when many bins are open and the fit is loose.
    if open_bins_count > 5 && post_residual > 40 {
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer tighter bins overall (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize residual that next item cannot use, scaled by wasted space
        score += 0.5 * (post_residual as f64).powf(1.3);
    }

    // Relative to mean residual: prefer bins with less residual than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Small penalty for large dead space creating unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to item size
    let fit_ratio = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 0.0 };
    score += fit_ratio * 8.0;

    // Reward near-perfect fills (waste < 10) strongly
    if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, heavily favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize using a fresh bin unless it's actually a good idea
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 10.0;
        // Opening a new bin is more acceptable early in the stream
        score -= progress * 4.0;
        // More acceptable when many bins are already open (spreading load)
        if open_bins_count > 3 {
            score -= 2.0;
        }
        // If the item is large, a fresh bin is natural
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
        // If next item is large too, fresh bin helps pack it
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
        // Penalize if placing here leaves residual that next item barely misses
        if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual as u32 <= 5 {
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res - mean_residual) / mean_residual;
        // Prefer bins with residual close to item size (tight fit relative to fleet)
        score += dev * 3.0;
    }

    // Penalize leaving large dead space that few items can use (residual < 10 is near-dead)
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 8.0;
    }

    // Dynamic time horizon: later in the stream, prioritize consolidation (use existing bins)
    score += (1.0 - progress) * 2.0;

    // Mild penalty scaled by number of open bins to avoid runaway bin proliferation
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post residual, quadratically).
    // Late: residual value decays, smooth via (1 - progress) modulation.
    let decay = (1.0 - progress).powi(2);
    score += decay * 40.0 * x * x * cap;

    // Reward using nearly-full bins: subtract smooth bonus for small residuals.
    score -= 25.0 * (1.0 - x).powi(3);

    // Penalize leaving a gap that exactly matches nothing useful: gap too small
    // relative to typical item sizes (smooth via sigmoid-like term).
    let tiny = (-(x * cap - 10.0) / 8.0).exp();
    score += 15.0 * tiny * decay;

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 12.0 * (1.0 - fits_next / cap) * (1.0 - fits_next / cap) * (1.0 - x);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * x;

    // Smooth deviation from mean residual: prefer bins below mean residual
    // (i.e., fuller than average).
    let dev = (mean_residual - pr as f64) / cap;
    score -= 10.0 * dev;

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band it lands in.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Penalize residuals in "dead zones": too small to fit typical items (>= ~10)
    // but too large to ignore. Use integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is best possible
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver: dead space
    } else if post_residual <= eighth {
        score += 10.0; // very tight leftover, only tiny items fit
    } else if post_residual <= quarter {
        score += 4.0;  // moderate leftover
    } else if post_residual <= half {
        score -= 8.0;  // half-ish residual still very reusable
    } else {
        score -= 5.0;  // large residual, reusable but wasteful now
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // typical item sizes; small remainders waste space.
    let rem10 = post_residual % 10;
    score += (rem10 as f64) * 0.8;

    // Coupling with next item (lookahead): reward leaving exactly enough
    // space, penalize leaving almost-enough.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 12.0; // can chain the next item here too
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 8.0; // near-perfect two-item chain
            }
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score += 12.0; // tantalizing but insufficient: bad dead space
            }
        }
    } else {
        // Last item: only perfect fits matter.
        if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= quarter && post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Opening a new bin while others fit is wasteful early;
            // slightly more acceptable late in the stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 - 15.0 * progress;
        }
    }

    // Mild diversity penalty: avoid fragmenting residuals far below the mean.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 5.0;
    } else if (post_residual as f64) < mean_residual * 0.5 && post_residual >= 10 {
        score -= 5.0;
    }

    // Slight pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 range,
    // small items likely) are wasted; penalize unusable tiny gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // gap too small for next item: mild penalty
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot follow: penalize proportionally to dead space created.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let dead_ratio = dead / bin_capacity as f64;
        score += 25.0 * dead_ratio;
        // Extra penalty if this dead space is small-but-unusable (worst case).
        if dead < 10.0 {
            score += 15.0;
        }
    }

    // Tight fit reward: filling a bin almost completely.
    if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (compact bins), penalize spreading into fat bins.
    let res = post_residual as f64;
    score += 0.5 * (res - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: base cost of opening a fresh bin; allow it only when
    // it offers a great 2-step future (large residual for next item) or few options.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.4 * next_item_size as f64;
        }
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Early in the stream, opening bins is cheap; later, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small post residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            // post residual too small for next item: penalize proportionally
            let waste = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
            score += 0.3 * waste;
        }
    } else {
        // Last item: prefer filling existing bins fully
        score -= 40.0;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score -= pressure * 10.0;

    // Bin much tighter than average residual is valuable to fill
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Time horizon: early on, be more willing to open new bins (keep options open);
    // late, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 20.0 + 80.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Prefer bins whose post-residual matches next item modulo structure
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain < 10 {
            score -= 15.0; // chains into near-perfect next placement
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let res = bin_residual as f64;

    // Normalized post residual (0 = perfect fit, 1 = empty bin)
    let x = pr / cap;

    // Core: non-linear polynomial in normalized post residual.
    // Dead space is super-linearly penalized, so small residuals are strongly favored.
    let mut score = 6.0 * x * x + 2.0 * x * x * x;

    // Coupling with stream progress: later in the stream, waste matters more,
    // so amplify the polynomial curvature as progress grows.
    score *= 1.0 + 1.5 * progress * (1.0 - x);

    // Tightness of the current fit: reward bins where the item fills a large
    // fraction of the available residual (smooth, non-piecewise).
    let fill = it / res.max(1.0);
    score -= 3.0 * fill * fill * (1.0 - progress * 0.5);

    // Lookahead coupling: if the next item can fit into the post residual,
    // reward this bin smoothly by the fraction of next item covered.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nxt_fit = (pr / nxt).min(1.0);
        score -= 2.5 * nxt_fit * nxt_fit;
    } else {
        // Last item: only immediate waste matters; reward tight fits more.
        score -= 2.0 * fill;
    }

    // Scarcity pressure: if very few bins can fit this item, this bin is
    // precious — penalize rejecting it (i.e., reward using it) smoothly.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 4.0 * scarcity * (1.0 - x);

    // New-bin candidate handling: empty bin gets post_residual = capacity.
    // Make it attractive only when it would leave a highly reusable residual
    // and open bins are congested (high mean residual, few fitting bins).
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        // Mild baseline penalty so open bins with decent fits win by default.
        score += 0.8;
        // Reward opening when congestion is high (mean residual low relative
        // to item size means existing bins are nearly exhausted).
        let congestion = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 2.0 * congestion * congestion;
        // Slightly more willing to open early when many bins exist but none fit well.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * scarcity;
    } else {
        // Existing-bin bonus scaled by how much better its residual is than mean.
        let rel = ((mean_residual - res) / cap).clamp(-1.0, 1.0);
        score -= 1.2 * rel;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction classes
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;

    // Dead-space penalty: residuals that no item (min 10) can ever use again
    if post_residual < 10 {
        score += 40.0;
    } else {
        // Reward residuals that are harmonic multiples of common item sizes
        let usable = (post_residual / 10) as f64;
        score -= 3.0 * usable;
    }

    // Exact fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo harmony: does post_residual match the next item's class granularity?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if next item would fit nearly perfectly here
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 25.0;
            } else if gap < 20 {
                score -= 10.0;
            }
            // Integer-division threshold coupling
            let pair_quotient = (post_residual / next_item_size.max(1)) as f64;
            if pair_quotient >= 2.0 {
                score -= 5.0 * (pair_quotient - 1.0).min(3.0);
            }
        } else {
            // Next item cannot follow in this bin: penalize blocking
            score += 8.0;
        }
        // Class adjacency bonus: consecutive harmonic classes pack well
        let diff = (item_class as i32 - next_class as i32).abs();
        if diff == 0 || diff == 1 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (fitting_bins_count as f64).max(1.0);
        score += 45.0 / congestion - 20.0 * progress;
        // Opening a bin is fine when mean residual is fragmented
        if mean_residual < 25.0 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins (low residual before placement)
    score += 0.15 * (bin_residual as f64 - post_residual as f64) / item_size.max(1) as f64 * 10.0;

    // Penalize bins far from mean residual (fragmentation shaping)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // tiny gap => heavy penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Larger leftovers: mild superlinear penalty to prefer compact packing.
        let p = post_residual as f64;
        score += 0.02 * p * p;
    }

    // Reward bins whose residual is close to exactly consumed (tight packing).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few,
    // allow opening new bins for good fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "small" bin best consumed now.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // Lookahead: if the next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 5.0; // this leftover would be dead for the next item
        }
    }

    // New-bin candidate handling: opening a bin is reasonable early or when the
    // current bin would leave a large awkward residual; penalize otherwise.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score -= 8.0 * early;
        if post_residual > 40 {
            score += 20.0; // fresh bin wastes a lot of space on a small item
        }
        if fitting_bins_count > 0 {
            score += 15.0; // there are existing bins that fit; prefer them
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits snugly with small dead space left.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 - slack * 2.0;
        }
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Penalize creating unusable dead space (small residuals that few items can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., current bin residual is far above what the item leaves usable).
    if bin_residual == bin_capacity {
        // Baseline penalty keeps open bins preferred unless fit is poor.
        score += 30.0;
        // If the current bin would leave a large unusable remainder, opening
        // a fresh bin becomes competitive.
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 45.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Global state coupling: many open bins with large mean residual -> encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation_pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score -= 0.15 * consolidation_pressure * (1.0 + progress);

    // Early in the stream, be more willing to open new bins (spread items);
    // late in the stream, pack tightly into existing bins.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening a brand-new bin when good fits exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
    }

    // Mild penalty for wasting a nearly-full bin's remaining space on a small item.
    if item_size < bin_residual / 3 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty (wasted space grows superlinearly)
    let mut score = pr * (1.0 + norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on prefer tight fills (penalize large residuals less as stream ends)
    let coupling = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score += coupling * norm_pr * norm_pr * cap * 0.5;

    // Late-stream: strongly reward small post-residual (smooth ramp)
    score -= progress * progress * (cap - pr) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 0.1 * pr;
    }

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like fit)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        let fit_quality = (-gap * gap * 40.0).exp(); // ~1 when next item fits snugly
        score -= 6.0 * fit_quality;
        // penalize leaving residual just below next item size (dead space)
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        }
    }

    // Slight preference for bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild penalty for many open bins (encourage consolidation early)
    score += open_bins_count as f64 * 0.01;

    // Reward using nearly-full bins (smooth in residual)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_u = bin_capacity;
    let cap = cap_u as f64;
    let post_u = post_residual;
    let post = post_u as f64;
    let next_u = next_item_size;
    let next = next_u as f64;

    let mean = mean_residual.clamp(0.0, cap);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic partition: 8 capacity classes.
    let unit_u = (cap_u / 8).max(1);
    let unit = unit_u as f64;
    let post_class = (post_u / unit_u) as f64;
    let next_class = if next_u == 0 { 0.0 } else { (next_u / unit_u) as f64 };
    let item_class = (item_size / unit_u) as f64;

    let mut score = post;

    // Exact closure is dominant.
    if post_u == 0 {
        score -= 1.60 * cap;
    }

    // Two-item harmonic lookahead.
    if next_u > 0 {
        if post_u >= next_u {
            let after_u = post_u - next_u;
            let after = after_u as f64;

            // Approximate the residual remaining after placing the lookahead item.
            score -= next;

            if after_u == 0 {
                score -= 0.75 * cap;
            }

            // Reward residuals that remain in a class able to repeat the next item.
            let after_class = (after_u / unit_u) as f64;
            if after_class >= next_class {
                score -= 0.05 * unit;
            } else {
                score += 0.08 * (next - after).min(unit);
            }

            // Mild preference for leftovers near harmonic boundaries.
            let mod_after = after_u % unit_u;
            let boundary_dist = mod_after.min(unit_u - mod_after) as f64;
            score -= 0.02 * (unit - boundary_dist);
        } else {
            let gap_u = next_u - post_u;
            let gap = gap_u as f64;
            let class_gap = next_class - post_class;

            // A residual just below the next item's class is especially wasteful.
            let near_miss = if gap_u <= unit_u || class_gap <= 1.0 {
                1.25
            } else {
                1.0
            };

            // If mean residual suggests another open bin can take the next item,
            // reduce the estimated cost of opening a future bin.
            let alt_hint = if mean >= next {
                0.55
            } else if mean >= 0.50 * next {
                0.78
            } else {
                1.0
            };

            let extra_bin_cost = (cap - next).max(0.0) * alt_hint;
            score += near_miss * (0.45 * gap + 0.70 * extra_bin_cost);
        }
    }

    if is_new_bin {
        let mut new_penalty = if fitting_bins_count == 0 {
            0.03 * cap
        } else if fitting_bins_count == 1 {
            0.20 * cap + 0.18 * cap * progress
        } else {
            0.40 * cap
                + 0.22 * cap * progress
                + 0.015 * cap * (open_bins_count as f64).min(8.0)
        };

        // Existing bins are nearly full: opening another bin is less harmful.
        if mean < 0.20 * cap {
            new_penalty *= 0.85;
        }

        // Harmonic item-class adjustment.
        if item_class <= 1.0 {
            new_penalty += 0.03 * cap;
        } else if item_class >= 4.0 {
            new_penalty -= 0.02 * cap;
        }

        // High mean residual means existing capacity is plentiful; avoid fragmentation.
        if mean > 0.50 * cap {
            new_penalty += 0.04 * (mean - 0.50 * cap);
        }

        if fitting_bins_count > 0 {
            new_penalty = new_penalty.max(0.12 * cap);
        }

        score += new_penalty.max(0.0);
    } else if fitting_bins_count == 1 {
        // Last-chance open bin: reward using it before opening a new bin.
        score -= 0.08 * cap;
        score += 0.02 * (post - mean).clamp(-cap, cap);
    } else {
        // Mild compactness preference relative to the current open-bin field.
        score += 0.02 * (post - mean).clamp(-cap, cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that can only host the smallest items are near-waste.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; the residual becomes dead space
            // unless another bin can take the next item. Penalize more
            // when residual is small-but-nonzero.
            if post_residual > 0 && post_residual < next_item_size {
                score += 15.0;
            }
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(25.0);
    } else {
        // New-bin candidate: penalize when open bins already have slack
        // (mean_residual large) or when many bins are open.
        score += pressure * 0.8;
        if mean_residual >= item_size as f64 {
            score += 30.0;
        }
    }

    // Mild preference for bins whose residual is above the mean
    // (spread usage evenly, keep small residuals out of play).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize large post residuals that waste space relative to mean
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 100.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        if item_size >= 50 {
            score -= 30.0; // big items prefer fresh bins
        }
    }

    // Slight preference for tighter bins overall
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
            // Extra reward if the next item fits *snugly*.
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space for the lookahead: penalize proportionally to wasted gap.
            let gap = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 5.0 * gap / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when the item is large and would leave existing bins fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill = item_size as f64 / bin_capacity as f64;
        // Cost of a new bin, discounted when item is big (new bin will be well used)
        // or when existing bins have low mean residual (poor hosts anyway).
        let mut new_bin_score = 60.0 - 40.0 * fill;
        new_bin_score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        new_bin_score -= 15.0 * (1.0 - progress);
        // If many bins can fit, no reason to open a new one.
        new_bin_score += 8.0 * fitting_bins_count as f64;
        // Slight penalty with many open bins (fragmentation).
        new_bin_score += 0.5 * open_bins_count as f64;
        score = new_bin_score + post_residual as f64;
    } else {
        // Reward placing into bins with small residual (consolidate large gaps).
        let res_ratio = bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - res_ratio);
        // Mild penalty for spreading across too many bins.
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    let mut score = 2.0 * pr + 40.0 * poly;

    // Prefer tight fits more strongly late in the stream
    score -= (1.0 - x) * (1.0 - x) * (30.0 + 50.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 + 10.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation pressure)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (1.0 + progress);

    // Mild penalty for spreading across many open bins
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Favor reusing open bins over opening new ones, more so early on
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals that are "nice" fractions of
    // capacity (0, 25, 50, 75, 100) or common small remainders are reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic residual classes: divisible by 10/20/25/50 are likely to fit
    // future items exactly.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 20 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 50 == 0 { score -= 10.0; }

    // Dead-space penalty: residual too small to fit the minimum item size (1),
    // but small residuals under a harmonic threshold are wasted.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward; if it doesn't fit at all, mildly penalize creating
    // residual that strands the next item when other bins could take it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // closeness of fit for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap).max(0.0);
            // harmonic bonus if next item lands on a class boundary
            if (post_residual - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot use this residual
            score += 6.0;
            // penalize more if residual is in an awkward (non-harmonic) class
            if post_residual % 10 != 0 { score += 4.0; }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give empty bins a moderate default so tight fits win.
    if bin_residual == bin_capacity {
        // neutral-ish base for new bin, adjusted by stream position and load
        score = cap * 0.55;
        // late in the stream, be more conservative about opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // if many bins are open with slack, discourage another new bin
        score += (open_bins_count as f64).sqrt() * 2.0;
        // if mean residual across open bins is large, new bin is wasteful
        if mean_residual > item_size as f64 {
            score += (mean_residual - item_size as f64) * 0.3;
        }
        // but if next item is huge, a fresh bin gives flexibility
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild preference for fuller bins overall (post_residual already encodes
    // this), plus small penalty scaling with number of alternatives.
    score += fitting_bins_count as f64 * 0.5;

    // Tiny tie-breaker toward earlier progress to stabilize selection.
    score += (step_index as f64) * 1e-6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone_max {
        score += (dead_zone_max - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let residual = bin_residual as f64;
    if residual > 0.0 {
        score += (item_size as f64 / residual) * -10.0; // tighter fit => lower score
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation
    // by penalizing candidates that leave large post_residual when bins are plentiful.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score += post_residual as f64 * 0.05 * pressure;

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty for hoarding space.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // New-bin candidate: baseline cost so it's chosen only when open bins are truly poor.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 2.0;
        // Late in the stream, a fresh bin is less costly (fewer future placements to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
        // If no open bin leaves a workable gap, opening a new bin is attractive.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0;
        }
    }

    // Mild mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits exactly in the leftover: chain placement.
            score -= 40.0 - diff.min(40.0);
        } else {
            // Next item won't fit here; penalize creating dead space
            // that blocks the lookahead item.
            let dead = next_item_size as f64 - post_residual as f64;
            score += 0.6 * dead;
        }
        // Coupling: prefer tight residual relative to mean residual.
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent,
    // but allow new bins early in the stream or when many bins are open
    // (spread load for future flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - progress);
        if open_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 8.0;
        }
    }

    // Mild penalty for wasting large residual space in already-open bins.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = pr / cap;

    // Base: quadratic in post_residual (favor small waste, but not linearly)
    let mut score = pr * (1.0 + fit_ratio * fit_ratio);

    // Stream-progress coupling: early on, tolerate waste (explore); late, punish it
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += fit_ratio * fit_ratio * fit_ratio * cap * progress_weight;

    // Mean-residual coupling: penalize bins far from the mean residual (outliers waste)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * (1.0 - fit_ratio) * (0.5 + progress);
    }

    // Lookahead: reward leaving space that fits the next item, punish otherwise
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= ni as f64 * 0.3 * (1.0 - progress);
        } else {
            score += (ni - pr) * 0.2 * (0.5 + progress);
        }
    }

    // New-bin candidate: mildly penalize opening a bin unless it's clearly better late in stream
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.4 * progress) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how close it is to a "useful" residue class.
    // Residues that pair well with common small items (1..=100) are those near
    // multiples of 10 or very small (dead space).
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class 0..=10
    let rem = pr % 10;   // fine offset within class

    // Penalize dead space classes strongly: tiny residues (class 0..1) are nearly unusable.
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if pr <= 5 {
        score += 40.0; // near-dead space
    } else if pr <= 10 {
        score += 20.0;
    } else {
        // Reward residues in the "sweet spot" that can absorb mid-size items.
        // class 3..=8 (residual 30..90) are reusable; deeper reward for larger reusable space.
        score -= (class as f64) * 1.5;
        // Fine offset: prefer residues that are exact multiples of 10 (harmonic alignment).
        score += rem as f64 * 0.4;
    }

    // Lookahead coupling: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward: bin stays useful for the next item.
            score -= 8.0 + (next_item_size as f64) * 0.1;
            // Extra reward if next item fills the bin almost exactly (harmonic pair).
            let nxt_post = pr - next_item_size;
            if nxt_post == 0 {
                score -= 25.0;
            } else if nxt_post <= 10 {
                score += 6.0;
            }
        } else {
            // Next item cannot fit here; penalize slightly if residue is large-but-broken.
            if pr >= 20 {
                score += 4.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if pr > 0 && pr <= 5 {
            score += 25.0; // but avoid creating dead space anyway
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it attractive only when the item
        // is large relative to capacity or all open fits are poor.
        score += 30.0;
        // Large items (harmonic class >= 6 of item_size) pack well into fresh bins.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — finishing it off is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.15;
    }

    // Too many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 2.0 + (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are nearly worthless; penalize them hard.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold {
        score += 40.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap cannot fit the known next item: strong dead-space penalty.
        score += 25.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect provision for lookahead: reward.
        score -= 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins,
    // favor consolidating into existing residual.
    score += 0.8 * open_bins_count as f64;

    // If this bin's residual is far below the mean, it's a poor-fit candidate;
    // prefer bins with larger-than-mean residual for big items.
    if (bin_residual as f64) < mean_residual - 5.0 {
        score += 5.0;
    } else if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 3.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity) gets a mild
    // handicap so it only wins when no open bin offers a decent fit, but is
    // preferred over leaving tiny dead space in a nearly-full bin.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
    }

    // Late in the stream, avoid opening bins that will strand large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 40 && progress > 0.7 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    if next_item_size > 0 {
        // Perfect 2-step match: next item exactly fills the post residual.
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tight the 2-step fill is.
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - two_step_waste / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // scaled by how far off the next item is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
            // Large unusable post residuals are dead space.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer the tightest fit overall.
        score -= 50.0;
    }

    // Compare against mean residual: bins below mean residual are more "loaded";
    // filling them further is efficient.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when reasonable alternatives exist,
    // unless the fit is exceptionally tight.
    if bin_residual == bin_capacity {
        score += 80.0;
        if post_residual == 0 {
            score -= 500.0; // item exactly fills a fresh bin
        }
    }

    // Slight preference for consolidating into fewer bins late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(4) * 30.0;

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual as f64 - nxt;
            score -= (1.0 - slack / bin_capacity as f64) * 12.0;
        } else {
            // next item won't fit here; penalize more if post_residual is stranded
            score += (nxt - post_residual as f64).min(50.0) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * open_bins_count as f64 * 1.5;

    // Time horizon: early in stream, tolerate spreading; late, prefer tight packing
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.4 * t;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        // If mean residual is large and many bins open, opening new is less costly
        let relief = (pressure * open_bins_count as f64 * 1.5).min(40.0);
        score = base_penalty + post_residual as f64 - relief;
        // If this is the only fitting option context (no good fits), allow new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: quadratic post-residual shaped by stream progress.
    // Early on, moderate residuals are tolerable; late, they become costly.
    let phase = progress * std::f64::consts::PI;
    score += 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * phase.sin());

    // Reward tight fits (post_residual near zero) with smooth decay
    score -= 25.0 * (-norm_pr * 8.0).exp();

    // Penalize residuals that cannot fit the lookahead item (smooth via ratio)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let deficit = (nxt - pr).max(0.0) / cap;
        score += 30.0 * deficit * (1.0 + progress);
        // Bonus if post-residual smoothly accommodates next item
        let slack = (pr - nxt).max(0.0) / cap;
        score -= 10.0 * (-slack * 6.0).exp() * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it (smooth reward)
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many bins fit, encouraging diversity of choice
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Deviation from mean residual: prefer bins that reduce residual variance
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate: penalize opening a fresh bin, more so late in stream
    if bin_residual == bin_capacity {
        score += 35.0 + 40.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets
    let pr = post_residual;
    let class = pr % 10;
    // Leftovers that are "harmonically awkward" (small non-zero remainders) are penalized
    if pr > 0 && pr < 10 {
        score += 40.0 - (pr as f64) * 2.0; // dead space of 1..9 is very bad
    } else if class == 0 {
        score -= 12.0; // perfectly aligned leftover (multiple of 10) is desirable
    } else if class <= 5 {
        score -= 4.0 - (class as f64) * 0.5;
    } else {
        score += (class as f64) * 0.3;
    }

    // Integer-division thresholds: how many items of typical size (~ next_item_size) fit later
    if next_item_size > 0 && pr >= next_item_size {
        let fits = pr / next_item_size;
        score -= 8.0 * (fits.min(3) as f64);
    } else if next_item_size > 0 && pr < next_item_size {
        // leftover cannot host the lookahead item -> mild penalty unless leftover is tiny
        if pr >= 10 { score += 6.0; }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a base cost that shrinks as stream progresses
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 30.0 * progress;
        // opening a new bin is more attractive when few bins fit the item
        score += 10.0 * (fitting_bins_count as f64);
    }

    // Prefer bins tighter than the mean residual (compactness)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Capacity-fraction coupling: reward filling beyond half the bin
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill > 0.5 { score -= 15.0 * (fill - 0.5); }

    // Harmonic modulo on item size: pairing items whose sizes sum to harmonics of 10
    let s = (item_size + pr) % 10;
    score -= 2.0 * ((10 - s) % 10) as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect lookahead chaining: residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving residual slightly below next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 2.0;

    // New-bin candidate: penalize unless current item is large relative to capacity
    // and no good fit exists (i.e., this call is the empty-bin candidate).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 35.0 - large_item_bonus;
        // If the only fitting bin would leave bad dead space, allow new bin.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score -= 25.0;
        }
    }

    // Mild stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (2-step perfect match)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap.min(40.0);
        if gap == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits overall (small post residual relative to mean residual)
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if item is large or residuals are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0
            - (item_size as f64 / bin_capacity as f64) * 30.0
            - open_bins_count as f64 * 1.5
            - progress * 10.0;
        // If next item pairs well with the remainder of a fresh bin, encourage new bin
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Reward tight fills (quadratic coupling: near-perfect fits strongly favored)
    let tightness = 1.0 - post / cap;
    score -= 14.0 * tightness * tightness;

    // Penalize unusable dead space (residual too small for any item)
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    // Last-chance bonus: only open bin that fits the item
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: generally penalized, less so late in the stream
    if is_new_bin {
        score += 28.0 + 22.0 * progress;
        // Reward opening a fresh bin when it can also host the lookahead item
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 35.0;
        }
        // If existing bins are very full on average, a new bin is more acceptable
        score -= 0.08 * mean_residual;
    } else {
        // Prefer bins whose residual is close to the global mean (balanced usage)
        score += 0.12 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead coupling: favor placements leaving room for the next item
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 9.0;
        } else {
            score += 4.0;
        }
    }

    // Mild pressure against proliferating many half-empty bins
    score += 0.06 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: prefer small post residual (tight fit).
    let mut score = post;

    // Smooth dead-space penalty: worst when post_residual is small-but-nonzero
    // (unusable sliver). Bell-shaped penalty centered at ~1/8 of capacity,
    // vanishing at post == 0 and growing again for large residuals.
    let x = post / cap;
    let sliver = (-((x - 0.125) * (x - 0.125)) / 0.008).exp();
    score += 18.0 * sliver * (1.0 - x).max(0.0);

    // Perfect-fit reward: quadratic bonus that sharply favors post == 0.
    score -= 25.0 * (1.0 - x).powi(3);

    // Lookahead coupling: reward when the next item fits exactly in the
    // post residual (smooth kernel), penalize when it nearly-but-not fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let d = post - next_item_size as f64;
        score -= 10.0 * (-d * d / 12.0).exp();
    } else if next_item_size > post_residual && next_item_size > 0 {
        let d = next_item_size as f64 - post;
        score += 6.0 * (-d * d / 40.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor
    // using it over opening a new bin (scaled by stream progress).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0 + 8.0 * progress;
    }

    // New-bin candidate handling: mildly discourage opening a new bin when
    // good existing options exist, more so late in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 0.15 * open_bins_count as f64;
    }

    // Slight preference for filling bins with larger residuals relative to
    // the fleet mean (balances bin closure), smoothly weighted by progress.
    score += progress * 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by 10 is "reusable"
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 8.0; // perfectly harmonious residual (aligns with item grid)
    } else if cls <= 2 {
        score += 6.0; // nearly-dead sliver
    } else if cls >= 8 {
        score -= 3.0; // close to a harmonic boundary
    }

    // Integer-division thresholds on post_residual: classify leftover usability
    let div = post_residual / 10;
    score -= (div as f64) * 1.5; // bigger usable chunks are good

    // Capacity fraction coupling: penalize residuals in the awkward 1..20 band
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.2 {
        score += 10.0 * (0.2 - frac);
    } else if frac >= 0.5 {
        score -= 5.0; // half-full or emptier bin keeps flexibility
    }

    // Lookahead: if next item fits the post-residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item cannot use leftover: penalize proportionally to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
        // modulo harmony between next item and leftover
        if next_item_size % 10 == post_residual % 10 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else {
            score += 30.0; // prefer existing bins when one fits
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (post_residual as f64 / cap);

    // Mean residual context: if this bin is much tighter than average, prefer it
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // A residual gap is "dead" if no plausible future item can use it well.
        // Small gaps (< 10) are pure waste; scale penalty nonlinearly.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        } else if post_residual <= 20 {
            score += (20 - post_residual) as f64 * 1.5;
        }
        // Exact fit is golden.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if lookahead fits perfectly after this placement.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize stranding the next item in this bin's gap.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating
    // (larger fill), penalizing bins that leave large post residual.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += (post_residual as f64 / bin_capacity as f64) * 30.0 * pressure;

    // Favor bins tighter than the mean residual (better fits).
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score += (post_residual as f64 - mean_post) * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base hesitation to open new bins.
        score += 25.0;
        // More hesitation as stream progresses (sunk cost of open bins).
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // But if the only fitting bin would strand the next item, opening
        // a fresh bin becomes more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimize dead space)
    let cap = bin_capacity as f64;
    let perfect_fit = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * perfect_fit * perfect_fit;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 <= post_residual {
            score -= 30.0 * (1.0 - lookahead_gap / cap);
        } else {
            // next item cannot fit here; mild penalty proportional to overshoot
            score += 10.0 * (lookahead_gap / cap);
        }
    }

    // Compare post_residual against mean residual: avoid leaving much more than average
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += 0.5 * mean_gap;
    } else {
        score -= 0.25 * (-mean_gap);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 20.0 * (1.0 - tightness);
        // allow new bin for very large items that would wreck an open bin's flexibility
        if item_size as f64 > 0.75 * cap {
            score -= 25.0;
        }
    }

    // Late in the stream: consolidate aggressively, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: lower post residual is better, with non-linear emphasis.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Exact or near-exact fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the fit
    // is hopeless elsewhere. Penalize new bins by default, but relax the
    // penalty when the item leaves a large dead zone or no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut new_bin_penalty = 45.0;
        // If few bins fit the item, opening a new one is more acceptable.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 40.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty -= 15.0;
        }
        // Large items leave little residual in a fresh bin; slightly cheaper.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 20.0 * progress;
        // If mean residual across open bins is already large, prefer reusing.
        if mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    } else {
        // Reward bins whose residual is close to the item (good packing).
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 12.0;
        }
        // Penalize if post residual would strand space smaller than the
        // minimum plausible next item.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Global state coupling: when many bins are open with high mean
    // residual, prefer bins that absorb more space (larger item share).
    let load_ratio = item_size as f64 / bin_capacity as f64;
    if mean_residual > 50.0 && open_bins_count > 3 {
        score -= load_ratio * 15.0;
    }

    // Mild time horizon effect: early on, encourage consolidation;
    // late, prioritize simply fitting without waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - load_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space quadratically
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate larger residuals
    let coupling = norm_pr * (1.0 - norm_pr) * (0.5 - progress);
    score += 40.0 * coupling;

    // Reward nearly-full bins with a smooth cubic decay
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev.abs();

    // Last-chance bonus: smooth quadratic reward when few fitting bins
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 15.0 * scarcity * scarcity;
    }

    // Lookahead: smooth penalty if next item cannot use this residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 12.0 * (-gap / cap);
        } else {
            // reward residuals close to next item size (smooth kernel)
            let x = gap / cap;
            score -= 8.0 * (1.0 - (x * std::f64::consts::PI).cos()) * (1.0 - progress);
        }
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt() + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover: post_residual buckets via integer division.
    // Small leftovers (< 10) are near-dead space -> heavy penalty.
    let dead = (post_residual < 10) as i32 as f64;
    score += dead * 40.0;

    // Modulo classes on post_residual: leftovers that are "clean" fractions of
    // capacity (0, 25, 33, 50) are reusable; odd fragments are penalized.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 { 25.0 }
        else if pr % 50 == 0 { 15.0 }
        else if pr % 25 == 0 { 10.0 }
        else if pr % 33 == 0 { 6.0 }
        else if pr % 10 == 0 { 5.0 }
        else if pr % 5 == 0 { 2.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item cannot use this leftover: penalize proportionally to waste
            score += (next_item_size as f64 / cap) * 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // placement would leave large, awkward residue relative to mean residual.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let awkward = if waste > cap * 0.5 { 1.0 } else { 0.0 };
        score += 5.0 + awkward * 15.0 - (mean_residual / cap) * 10.0;
    } else {
        // Prefer bins that are already partially filled relative to fleet mean.
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= fill_frac * 10.0;
        // Tight fit reward: item fills most of the bin.
        let tight = item_size as f64 / bin_residual as f64;
        if tight > 0.8 {
            score -= 8.0;
        }
    }

    // Early in stream: be slightly conservative, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    // Penalize many open bins to encourage closing them out.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps are wasted.
    if post_residual > 0 {
        let dead = post_residual < 10; // nothing can fit in a gap < 10 (min item size interface: 1..100, use small threshold)
        if dead {
            score += 50.0;
        }
    }

    // Tight fits are rewarded: subtract more for smaller post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 6.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // 2-step lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize leftover dead space proportionally.
            let dead = post_residual as f64;
            score += 0.35 * dead;
        }
    }

    // Compare post residual against mean residual: leaving more than average waste is bad.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist; allow it only if this
    // placement would leave very unusable space in all open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // As stream progresses, avoid proliferation of many open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for many open bins already (consolidation pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * (next_item_size as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the leftover gap.
            score += 0.08 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill_ratio * (open_bins_count as f64).ln().max(0.0);

    // Global residual pressure: if mean residual across bins is high, be pickier
    // about which bin absorbs the item; encourage using bins above the mean fill.
    let mean_fill = bin_capacity as f64 - mean_residual;
    let this_fill = (bin_capacity - bin_residual) as f64;
    if this_fill > mean_fill {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Time horizon: early in the stream, be conservative (favor new bins to build
    // diverse partial bins); late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill_ratio;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: a fresh bin should only win when no open bin is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Base cost of opening a new bin, softened when current fits are poor.
        let poor_fits = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 18.0 - 14.0 * (1.0 - poor_fits);
        // Early stream: opening bins is cheaper to enable future pairing.
        score -= 8.0 * (1.0 - progress);
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual, mildly non-linear (waste grows quadratically)
    let mut score = norm_pr + 0.6 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 0.8 * coupling;

    // Penalize residual close to dead-space band, smoothly via sin-like polynomial
    let dead = 4.0 * norm_pr * (1.0 - norm_pr);
    score += 0.35 * dead * (1.0 - norm_item);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 0.5 * fits * nx * (1.0 - progress);
        // penalize residual just barely above next item (fragile fit)
        let gap = (pr - next_item_size as f64) / cap;
        if fits > 0.0 {
            score += 0.4 * (1.0 - gap) * (1.0 - gap) * nx;
        }
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    }

    // Mild pressure toward compacting when many bins are open
    score += 0.1 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * norm_pr;

    // Deviation from mean residual: prefer bins unlike the average (diversity of sizes)
    let dev = (pr - mean_residual) / cap;
    score -= 0.15 * dev * dev * dev.signum();

    // New-bin candidate: neutralize its raw residual advantage slightly
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small unusable" classes should be rewarded (tight packing).
    let cap = bin_capacity as f64;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual into harmonic classes via integer division thresholds.
    let cls = post_residual / 10; // 0..=10 classes of width 10
    match cls {
        0 => score -= 50.0,                 // nearly full bin, dead space tiny
        1 => score -= 30.0,                 // still quite tight
        2 => score -= 10.0,                 // moderate
        3 => score += 5.0,                  // 30..39 leftover: awkward zone
        4 => score += 0.0,
        5 => score -= 5.0,                  // ~50: half-empty, still useful
        6 => score += 5.0,
        7 => score += 8.0,
        _ => {}
    }

    // Modulo coupling: leftover that pairs well with common item sizes
    // (multiples of 5 / 10) is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 20.0;
            } else if slack <= 25 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here: mild penalty, worse if this bin was the only option
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; relax late in the stream or when many bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 45.0 - 20.0 * progress;
        if open_bins_count > 8 {
            open_cost -= 5.0;
        }
        // If mean residual is large, open bins are underfilled: discourage new bin.
        open_cost += (mean_residual - cap * 0.5).clamp(-15.0, 15.0);
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            open_cost -= 10.0;
        }
        score += open_cost;
    } else {
        // Prefer filling bins that are already relatively empty among open bins
        // (balance via mean residual): bins below mean residual get a small nudge.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Small penalty for wasting a big bin on a tiny item when alternatives exist.
    if item_size <= 15 && post_residual > 70 && !is_new_bin {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; the smaller the gap, the harsher the penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (12.0 - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 25.0;
    }

    // Reward tight fits relative to current residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when the item is large and fits nowhere well.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Bonus if next item fills the leftover almost exactly.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= (10 - gap) as f64 * 0.8;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover unusable by the next item: mild penalty.
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (concentrate waste in fewer bins) when the item still fits well.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only for
    // large items or when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let large_item = item_size >= bin_capacity / 2;
        let poor_alternatives = fitting_bins_count == 0;
        if large_item || poor_alternatives {
            score -= 10.0;
        } else {
            // Penalize wasteful bin opening when existing bins fit fine.
            score += 8.0 + (post_residual as f64) * 0.5;
        }
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about leaving tiny gaps since fewer items remain to fill them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 15 {
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match for the NEXT item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 25.0; // exact two-item packing
        }
        // Penalize leaving a gap that the next item cannot use at all.
        if post_residual > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Penalize creating dead space far below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins that are already tight (below-mean residual).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.1 * open_bins_count as f64;

    // New-bin candidate: keep it neutral-to-slightly-costly so it is only
    // chosen when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: reward keeping this residual usable.
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 2.5 * (waste / bin_capacity as f64) * (waste / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, more when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 14.0 + 10.0 * scarcity + 6.0 * (1.0 - progress);
        // But if the item is huge and would leave little residual anyway, opening is fine.
        if item_size >= 70 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balance load) mildly.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    // Prefer fuller bins as the stream matures (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space, amplified as stream progresses.
    let mut score = post + 120.0 * norm_post * norm_post * (0.4 + 1.6 * progress);

    // Cubic coupling: strongly punish medium dead space (unusable gaps).
    score += 60.0 * norm_post.powi(3) * (1.0 - progress);

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let residual_fit = (post - nxt) / cap;
            score -= 45.0 * (1.0 - residual_fit) * (1.0 - 0.5 * progress);
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 25.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: prefer existing bins unless they fit poorly.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let mean_gap = (mean_residual - post).abs() / cap;
        score += 90.0 * (1.0 - 0.6 * progress) - 30.0 * congestion + 20.0 * mean_gap;
        // Opening a new bin is attractive if no bin gives a tight fit.
        if fit_ratio < 0.55 {
            score -= 35.0 * (0.55 - fit_ratio) * 2.0;
        }
    }

    // Mild preference for balancing residuals toward the mean early on.
    score += 8.0 * ((post - mean_residual) / cap).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean"
    // divisors/multiples of common size classes (mod 10 classes).
    let pr = post_residual;
    let pr_mod = (pr % 10) as f64;
    // Perfect-fit reward
    if pr == 0 {
        score -= 1000.0;
    }
    // Reward residuals in "usable" classes: multiples of 10 are more likely
    // to be filled by future items (sizes often align to decade classes).
    score -= (10.0 - pr_mod) * 0.8; // exact decade residuals get max bonus

    // Penalize tiny unusable slivers (< 10) heavily: dead space.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Harmonic pairing: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 500.0;
        } else {
            score -= 30.0 * (1.0 - (pr - next_item_size) as f64 / 100.0);
        }
    }
    // Penalize if next item would NOT fit in this bin but could fit a tighter bin
    if next_item_size > pr && next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins are fragmented
    // or item barely fits anywhere. Penalize opening bins when mean residual
    // is already large.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        score = 100.0 - 0.5 * mean_r;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // big items cluster: fresh bin helps
        }
    }

    // Late in stream, prefer tighter packing (minimize post residual harder).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Prefer bins below mean residual (tighter bins) slightly.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot hold even the smallest plausible item is "dead".
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver: nearly worthless
        } else if post_residual <= 20 {
            score += 25.0; // narrow gap, hard to fill
        } else if post_residual <= 35 {
            score += 8.0; // moderately awkward
        } else {
            score -= 12.0; // large residual stays flexible
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 100.0;
    }

    // Reward exact next-item fit: post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap just below the next item (near-miss waste).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins first),
    // penalize bins far above the mean (hoarding space).
    if (bin_residual as f64) > mean_residual {
        score += ((bin_residual as f64) - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // New-bin candidate: only attractive when the item is large and open bins
    // are crowded; otherwise keep the default so open bins win.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if large_item || open_bins_count == 0 {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 25.0; // discourage opening bins for small items
        }
    }

    // Mild late-stream conservatism: fewer wasted gaps near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving near-zero dead space.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 == next_item_size as f64 {
            score -= 45.0; // exact 2-chain
        } else if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 8.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual
    // concentrates space, which is good; leaving above-average residual is wasteful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 12.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 6.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual relative to capacity means poor reuse).
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: opening a new bin is necessary
        }
    }

    // Late in the stream, favor tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post residuals too small to be useful
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect closure
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Time horizon: early on, prefer opening new bins less (consolidate);
    // late, prefer tight packing of existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Penalize using a nearly-empty existing bin when many bins are open
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_frac * 3.0;

    // New-bin candidate handling: empty bin gets a mild penalty so it's
    // chosen only when open bins fit poorly, but reward when open bins
    // are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Mild penalty proportional to number of open bins to discourage sprawl
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: penalize large post_residual more as stream progresses
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += poly * cap;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    score -= (1.0 - norm_pr).powi(3) * cap * (0.3 + 0.7 * progress);

    // Penalize creating dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * cap * (1.0 + progress);
        // Reward post_residual that still fits the next item
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * norm_item * cap * 0.5;
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.4 + 0.4 * progress);
    }

    // Mild coupling with open bins count: discourage spreading across many bins early
    let bins_term = (open_bins_count as f64).ln().max(0.0);
    score += bins_term * norm_pr * cap * 0.2 * (1.0 - progress);

    // Mean residual smooth interaction: prefer bins below mean residual (tighter bins)
    let mr = mean_residual / cap;
    score += (norm_pr - mr).abs() * cap * 0.3 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by common item sizes is reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = false;
        for d in [10u32, 20, 25, 50, 5] {
            if pr % d == 0 {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 8.0;
        }
        // Dead-space penalty: tiny leftover that few items can use
        if pr < 10 {
            score += 12.0;
        }
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic pairing: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins (tight packing) scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.3 * (0.5 + progress);

    // New-bin candidate: penalize opening a bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 25.0 * progress;
        if mean_residual > 25.0 {
            score += 15.0;
        }
        let _ = fragmentation;
    }

    // Prefer bins below mean residual slightly (balance while keeping big holes)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to hold even the smallest plausible item.
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // likely dead space for most items
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it still fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 {
            score += 10.0; // blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer opening a bin only under pressure or for large items.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        score += 30.0 - 35.0 * pressure;
        if item_size > 70 {
            score -= 20.0; // big items pair well in fresh bins
        }
    }

    // Open-bin pressure: mild reward for consolidating into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Prefer filling tighter bins (small residual relative to capacity).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Slight preference for bins below the mean residual (keeps residuals balanced).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64); // good chain
        } else {
            // next item does not fit here; penalize leaving awkward space
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.3 * waste;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 0.1 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && item_size == next_item_size {
            score -= 10.0; // pairing identical items into fresh bins is fine
        }
    }

    // Late-stream pressure: as stream progresses, discourage opening new bins further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Dead-space penalty: residuals too small to matter for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large residual that goes unused
            score += 6.0;
        }
    } else {
        // Last item: minimize residual waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count > 0 && post_residual >= 20 {
            score += 60.0; // decent fit exists elsewhere; don't open new bin
        } else {
            score -= 15.0 * fit_quality; // poor fits elsewhere -> new bin ok
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Global state: many open bins with high mean residual -> prefer filling bins with large residuals.
    let rel_res = (bin_residual as f64) / (bin_capacity as f64);
    if mean_residual > 0.0 {
        score += 5.0 * (rel_res - mean_residual / bin_capacity as f64);
    }

    // Crowding: fewer fitting bins -> favor this bin more.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, but non-linearly (quartic smooth coupling).
    let mut score = x.powf(2.0) * cap * (1.0 + progress) + x.powf(4.0) * cap * (2.0 - progress);

    // Smooth interaction: dead-space penalty grows with stream progress.
    score += (x * (1.0 - x)).powf(2.0) * cap * 0.5 * (1.0 + progress);

    // Lookahead: reward leaving room for the next item (subtract when next fits well).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).max(0.0);
        score -= fit_gap.max(0.0).min(0.5) * cap * (1.5 - progress);
        // Penalize if next item won't fit this bin's residual.
        if x < nx {
            score += nx * cap * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bonus: strongly favor using a bin when it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= cap * (0.8 + 0.4 * progress);
    }

    // Diversify open bins early; consolidate late.
    let open_norm = open_bins_count as f64;
    score += open_norm * (1.0 - progress) * 2.0;
    score -= open_norm * progress * 0.5;

    // Mean residual coupling: prefer bins near mean residual (smooth gaussian-like term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // Tight-fit reward for the current item.
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= tight * tight * cap * 0.25;

    // New-bin candidate handling: mildly penalize opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.8 * (1.0 - progress)) - x * cap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "usable"
    // class (large enough for typical small items) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Dead-space penalty: leftover too small to fit anything useful.
    // Class boundaries via integer division thresholds (capacity/10 units).
    let class = post_residual / 10; // harmonic class index 0..10
    match class {
        0 => score += 40.0,               // 0..9  : dead space, very bad
        1 => score += 25.0,               // 10..19: nearly dead
        2 => score += 12.0,               // 20..29: only tiny items fit
        3 => score += 5.0,                // 30..39: marginal
        4 | 5 => { score -= 2.0; }        // 40..59: good usable band
        6 | 7 => { score -= 4.0; }        // 60..79: excellent band
        _ => { score -= 1.0; }            // 80..100: fine but wasteful
    }

    // Modulo coupling: leftover that matches common item-size classes
    // (multiples of 10) is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual
    // (perfect chaining), penalize if next item cannot fit any residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect pair
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.15; // next fits here
        } else {
            score += 4.0; // next item cannot use this bin's leftover
        }
        // Harmonic compatibility: next item in same decade class as residual
        if (next_item_size / 10) == (post_residual / 10) && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if item is large relative to capacity and no good band exists,
        // opening fresh is fine: reduce penalty.
        if item_size as f64 > 0.7 * cap {
            score -= 10.0;
        }
        if next_item_size > 0 && (next_item_size as f64 / cap) + (item_size as f64 / cap) > 1.0 {
            score -= 5.0; // items can't share a bin anyway
        }
    }

    // Tightness reward: prefer bins that become nearly full.
    let tightness = 1.0 - frac;
    score -= tightness * tightness * 8.0;

    // Mean residual coupling: avoid leaving this bin far above the mean
    // residual imbalance (keeps bin portfolio balanced).
    score += ((pr - mean_residual) * 0.05).abs();

    // Slight preference to fill older bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

