    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += (mean_residual / bin_capacity as f64) * 20.0 * (1.0 - tightness);

    // New-bin candidate: only attractive when current bin would leave nasty dead space
    // or no bin fits well. Base new-bin score should be moderately high.
    if bin_residual == bin_capacity {
        score = 70.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 1 {
            // An existing last-chance bin beats opening a new one.
            score += 40.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0; // big item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured by starting at post_residual.

    // Two-step lookahead: strongly reward bins where the NEXT item also fits the post_residual.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            // Next item chains perfectly into this bin: big reward proportional to how snug the chain is.
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 40.0 + 0.5 * next_item_size as f64 - 0.3 * chain_waste;
        } else {
            // Next item won't fit here: penalize leaving medium dead space that nothing can use.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 0.25 * (next_item_size as f64 - dead);
            }
        }
    } else {
        // Last item: only immediate tightness matters.
        score -= 10.0;
    }

    // Reward near-perfect fills (post_residual tiny) extra.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: make an empty bin attractive only when no open bin offers a good chain.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with stream progress (late bins are wasteful)
        // and with how many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * progress + 1.5 * open_bins_count as f64;
        // But if mean residual of open bins is too small to hold the next item either,
        // opening fresh is more forgivable.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 35.0;
        }
        // If the current item is large relative to capacity, a fresh bin gives flexibility.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild pressure toward bins with residuals close to the mean (balanced packing),
    // slightly discouraging dumping into already-loose bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Post residual still usable by next item: reward it.
            score -= 6.0 * (post_residual as f64 / (post_residual as f64 + next_item_size as f64));
        } else {
            // Dead space: penalize proportionally to wasted capacity.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins are open, prefer filling existing ones over new bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual < bin_capacity {
        score -= 4.0 * pressure;
    }

    // Global residual imbalance: if this bin is far below mean residual,
    // it is a good "sponge" bin for the current item.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, allow tighter packing emphasis.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.10 * (1.0 - t);

    // New-bin candidate: penalize slightly so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // new bin pairs well with similar-sized next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = x * x;
    score += 0.35 * x * (1.0 - progress);
    score -= 0.5 * x * x * progress;
    score -= 0.25 * (1.0 - x) * (1.0 - x) * progress;
    if fitting_bins_count <= 1 {
        score -= 0.6;
    } else {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 0.4 * fits_next * (1.0 - progress);
        score += 0.15 * (next_item_size as f64 / cap) * (1.0 - fits_next);
    }
    score += 0.02 * open_bins_count as f64 * x;
    score += 0.1 * (mean_residual / cap - x).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 gets strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic class: how well post_residual partitions into small item sizes (1..=20)
        let mut best_class = f64::INFINITY;
        for s in 1..=20u32 {
            let r = post_residual % s;
            let penalty = r as f64 + (post_residual / s) as f64 * 0.5;
            if penalty < best_class {
                best_class = penalty;
            }
        }
        score += best_class * 0.3;

        // Penalize dead space that no plausible item (>=1) can use well:
        if post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        }
    }

    // Fractional capacity coupling: residual fraction of capacity
    let res_frac = bin_residual as f64 / cap;
    score -= (1.0 - res_frac) * 10.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin is a bad fit
    if bin_residual == bin_capacity {
        // neutral base; opened only if all open bins score worse
        score = cap * 0.9 - mean_residual * 0.5 + open_bins_count as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // sequence of large items: fresh bin useful
        }
    }

    // Mild stream-progression pressure to consolidate late in the stream
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold: f64 = 10.0; // smallest item size is ~10, gaps below are dead
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the next item can still use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize a gap that just barely fails the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when it avoids dead space
    // elsewhere; base cost keeps it from winning against decent fits.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If the current fit would create dead space, opening fresh is better.
        if post_residual > 0 && (post_residual as f64) < dead_threshold {
            score -= 45.0;
        }
        // If next item is large, a fresh bin gives it room.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect two-step chain: item fills bin, next item fills remainder exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits exactly into residual without this item? still good chain.
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the residual -> residual likely dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize tiny dead space that nothing can use (sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer it only when residual is full capacity and
    // current item is large (poor fit elsewhere); otherwise penalize opening.
    if bin_residual == bin_capacity {
        score += 5.0;
        if item_size >= bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: the smaller the post-residual relative to item size, the better.
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
        score -= 18.0 * tightness;
    }

    // Penalize very small dead space only if it's truly unusable (<10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead: if the next item fits into post_residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 + 8.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize slightly more if this creates a stranded gap.
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Many open bins with high mean residual => encourage consolidation into existing bins.
    if open_bins_count > 2 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.03 * spread;
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Early in the stream: slightly favor opening fresh bins to build diverse residual pools.
    if progress < 0.15 && is_new_bin {
        score -= 4.0;
    }

    // New-bin candidate handling: baseline penalty so it's chosen only when existing fits are poor.
    if is_new_bin {
        score += 14.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is required
        } else {
            // Prefer new bin when all existing fits are loose (high post_residual elsewhere is
            // already scored, so just soften the penalty when bins are fragmented).
            if open_bins_count > 4 && mean_residual > 40.0 {
                score -= 6.0;
            }
        }
    }

    // Mild time-horizon scaling: later in the stream, waste matters more.
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let poly = prn * prn * (1.0 + progress) + prn * progress * (1.0 - progress);
    score += 12.0 * poly;

    // Penalize leaving dead space that cannot fit the next (lookahead) item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / cap) * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving exactly enough room for the next item
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 15.0 * (it / cap) * (1.0 + progress);
    }

    // Mild pressure toward consolidating into fewer bins
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (it / cap) * prn;

    // Reward tight fits (low post residual relative to item size)
    score -= 10.0 * (it / (it + pr + 1.0));

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let spread = (mean_residual / cap - 0.5).abs();
        score += 20.0 - 14.0 * spread - 10.0 * progress;
        if fitting_bins_count == 0 { score += 0.0; } else { score += 5.0 * (fitting_bins_count as f64).sqrt().recip(); }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo classes
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class 0..=10
    match class {
        0 => { score -= 40.0; }           // near-perfect fit, strongly reward
        1 => { score -= 25.0; }           // excellent fit
        2 => { score -= 12.0; }           // good fit
        3 => { score -= 4.0; }            // decent fit
        4 => { score += 0.0; }            // neutral
        5 => { score += 6.0; }            // half-empty bin, mild penalty
        6 => { score += 12.0; }
        7 => { score += 18.0; }
        8 => { score += 26.0; }
        9 => { score += 34.0; }
        _ => { score += 42.0; }           // nearly untouched bin, big penalty
    }

    // Fine modulo structure on post_residual within class (harmonic sub-classes)
    let sub = pr % 10;
    score -= (10 - sub) as f64 * 0.3;     // smoother: larger sub (more waste) -> higher score

    // Dead-space unusability: penalize residuals that no plausible item can fill
    if pr > 0 && pr < 10 {
        score += 8.0;                     // tiny sliver, likely wasted
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item's class aligns with residual
            let next_class = next_item_size / 10;
            let res_class = pr / 10;
            if next_class == res_class {
                score -= 15.0;            // same harmonic class: excellent chain
            } else if next_class + 1 == res_class || next_class == res_class + 1 {
                score -= 7.0;             // adjacent class: decent chain
            }
            score -= (next_item_size as f64) * 0.1;
        } else {
            // next item won't fit here; residual becomes terminal dead space
            let waste = pr as f64;
            score += waste * 0.25;
            // extra penalty if waste is in an awkward harmonic band
            if pr % 20 >= 11 {
                score += 5.0;
            }
        }
    } else {
        // last item: only immediate fit quality matters
        score -= 20.0 * (1.0 - pr as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.55 + 10.0;
        // more attractive late in the stream when many bins are open and fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 12.0;
        // if existing bins are fragmented (low mean residual relative to item), new bin is better
        if (mean_residual as u32) < item_size + 5 {
            score -= 20.0;
        }
        // don't open a new bin when several bins already fit
        if fitting_bins_count >= 3 {
            score += 25.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with lower residual when many bins are open
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual alignment: favor bins close to the mean (avoid extreme fragmentation)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap is "dead" if the next item (or typical items) cannot use it.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(100)) {
        // Gap too small for the lookahead item: near-total waste.
        score += 60.0;
    }
    // Penalize any tiny residual strongly (non-linear).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 25 {
        score += 15.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: this bin becomes dead space for the future.
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: discourage proliferation of open bins with scattered residuals.
    score += open_bins_count as f64 * 1.5;

    // Slight preference to fill bins whose residual is near the mean (consolidate gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Late in stream: become more conservative, avoid leaving many mid-size gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 30 {
        score += 10.0 * progress;
    }

    // Brand-new bin candidate: neutral baseline; only choose when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity > 0 { bin_capacity as f64 } else { 1.0 };
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let next_exists = next > 0.0;

    let mean_res = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        0.0
    };
    let mean_share = mean_res / cap;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;
    let fresh_post = (cap - item).max(0.0);

    let next_fits_here = next_exists && post + 0.5 >= next;
    let pair_possible = next_exists && fresh_post + 0.5 >= next;

    let hidden_bins = open_bins_count.saturating_sub(fitting_bins_count);
    let crowded = fitting_bins_count > 1 || hidden_bins > 0;
    let scarce_space = mean_share <= 0.32 && next > mean_res;
    let pair_aggressive = pair_possible && (!crowded || scarce_space);

    let mut score = post;

    // Keep the resulting residual from deviating too sharply from the current mean residual.
    score += 0.08 * cap * ((post - mean_res) / cap).abs();

    if next_exists {
        if next_fits_here {
            // Strong reward when this bin can also accept the lookahead item.
            let slack = post - next;
            let tightness = (1.0 - slack / cap).clamp(0.0, 1.0);
            score -= cap * (0.50 + 0.50 * tightness * tightness);
            score -= cap * 0.05 * mean_share * tightness;
        } else {
            // Penalize residual space that is dead with respect to the next item.
            let dead = ((next - post) / cap).clamp(0.0, 1.0);
            score += cap * (0.25 * dead + 0.65 * dead * dead);

            // If a fresh bin could complete the current+next pair, punish this bin for
            // stranding a small residual, but only when opening a bin is not clearly wasteful.
            if pair_aggressive {
                let post_vs_next = (post / next).clamp(0.0, 1.0);
                let below_mean = ((mean_res - post) / cap).clamp(0.0, 1.0);
                let dominance = 0.30 + 0.25 * (1.0 - post_vs_next) + 0.15 * below_mean;
                score += cap * dominance;
            }
        }
    } else {
        // No lookahead: tighten the bin as much as possible.
        score += 0.06 * post;
    }

    // Last-chance bonus for the only open bin that can currently fit the item.
    if !is_new_bin && fitting_bins_count == 1 {
        let usefulness = if !next_exists {
            (post / cap).clamp(0.25, 1.0)
        } else if next_fits_here {
            1.0
        } else if !pair_possible {
            (post / cap).clamp(0.20, 1.0)
        } else if pair_aggressive {
            0.0
        } else {
            0.80
        };

        score -= cap * (0.12 + 0.33 * usefulness);
    }

    // New-bin candidate handling: expensive by default, cheaper only when the
    // two-step lookahead gives it a clear pairing advantage or no open bin fits.
    if is_new_bin {
        let mut penalty = cap
            * (0.50
                + 0.035 * open_bins_count as f64
                + 0.22 * mean_share
                + 0.10 * progress);

        if fitting_bins_count == 0 {
            penalty -= cap * 0.80;
        }

        if pair_aggressive {
            penalty -= cap * 0.35;
        } else if pair_possible {
            penalty += cap * 0.45;
        }

        if !next_exists && fitting_bins_count > 0 {
            penalty += cap * 0.30;
        }

        if penalty < 0.0 {
            penalty = 0.0;
        }

        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: post_residual that is too small to be useful later.
    // Dead space threshold grows with item size distribution knowledge.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= 25.0 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            // This placement may strand space the next item needs.
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be conservative (favor good fits for
    // the long run); late in the stream, just close bins out aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is penalized unless the item
    // fits badly everywhere (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let big_item = (item_size as f64 / bin_capacity as f64).powi(2);
        let urgency = pressure * (20.0 + 60.0 * big_item);
        // Late in the stream, opening a bin is cheaper; early it is costly.
        let horizon = 1.0 - 0.5 * progress;
        score += urgency * horizon;
    } else {
        // Slight preference for fuller bins (best-fit flavor) scaled by load.
        score -= 5.0 * (1.0 - (bin_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear penalty on wasted space, growing with stream progress
    score += 12.0 * (pr_norm * pr_norm) * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth cubic term
    score -= 6.0 * (1.0 - pr_norm).powi(3);

    // Penalize bins whose residual is far from the current mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: penalize leaving a residual that only barely fails the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += 8.0 * gap * gap;
        } else {
            // reward leaving room for the next item, smoothly scaled by fit quality
            let slack = (pr - ni) / cap;
            score -= 5.0 * (1.0 - slack).max(0.0);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: make empty bins less attractive unless residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 - mean_residual / cap;
        score += 3.0 + 10.0 * tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "useful" residue classes
    // (multiples of common item sizes / small residues) are more likely reusable.
    let cap = bin_capacity as f64;

    // Reward post_residuals that are exact multiples of common size classes (harmonic bins)
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = if pr % 10 == 0 {
            6.0
        } else if pr % 5 == 0 {
            3.0
        } else if pr % 20 == 0 {
            8.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead-space penalty: tiny unusable leftovers (1..=9) are nearly worthless
        if pr < 10 {
            score += 12.0 - pr as f64;
        }
    } else {
        // Perfect fit is the best outcome
        score -= 15.0;
    }

    // Integer-division threshold classes on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 4.0; // still very flexible
    } else if pr >= quarter {
        score -= 1.0; // moderately useful
    } else {
        score += 2.0; // cramped
    }

    // Lookahead coupling: if next item fits harmonically into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 5.0;
            if pr % next_item_size == 0 {
                score -= 4.0; // perfect future packing
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 7.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits: scale by scarcity
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Early in stream: be a bit more conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mild pressure against accumulating many open bins with large residuals
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Opening a new bin costs: penalize unless item is large and fits poorly elsewhere
        let big_item = item_size > bin_capacity * 3 / 4;
        if big_item {
            score -= 3.0; // large items deserve fresh bins
        } else {
            score += 6.0; // prefer existing bins for small/medium items
        }
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the leftover can host the next item, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // leftover likely becomes dead space
    }

    // Last-chance pressure: only one bin fits, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many open bins mildly.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing fits are poor (large post_residual) or no real fitting bin exists.
    if bin_residual == bin_capacity {
        // Baseline score equals post_residual (= capacity), already high.
        // Discount slightly so it wins only when open bins leave big waste,
        // but add pressure so it loses against decent fits.
        score -= 15.0;
        score += (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    } else {
        // Real bin: compare against the new-bin alternative (capacity - 15 + 2*open).
        let new_bin_score = bin_capacity as f64 - 15.0 + (open_bins_count as f64) * 2.0;
        if score > new_bin_score && post_residual > 40 {
            // Poor fit: make this bin lose to the new-bin candidate naturally,
            // no extra adjustment needed; but cap runaway penalties.
            score = score.min(new_bin_score + 200.0);
        }
    }

    // Stream progression: late in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, amplify with square.
    score += 0.5 * (post_residual as f64).sqrt();

    // 2-step lookahead: if next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nr).abs() < 1.0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits perfectly-ish: reward proportional closeness
            score -= 10.0 * (1.0 - (pr - nr) / pr.max(1.0));
        } else {
            // next item won't fit here: penalize wasted potential
            score += 0.3 * (nr - pr);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare residual to mean residual across open bins.
    score += 0.2 * ((post_residual as f64) - mean_residual).max(0.0);

    // Penalize opening new bins when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual usable by lookahead: reward proportional to reusability
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // dead space penalty grows with how far below next item it falls
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalty for spreading across many open bins
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: neutral baseline, slightly discouraged unless current bin would be wasted
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count == 1 {
            // opening a fresh bin is fine here
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: minimize post residual, with non-linear shaping
    let mut score = r + 12.0 * rn * rn * cap;

    // Smooth progress coupling: later in stream, weight residual more strongly
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Penalize dead space relative to capacity non-linearly
    score += 20.0 * rn * rn * rn * cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly unless post residual is very tight
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).powi(3);
        score = 60.0 * (1.0 - tightness) + 40.0 * progress;
    }

    // Lookahead: reward bins whose post residual fits next item smoothly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * fit_quality * fit_quality;
    }

    // Penalize bins with residual far above mean (fragmentation avoidance)
    let dev = (r - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // chunk sizes (25, 20, 10) are more likely reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 9.0; }
        else if pr % 10 == 0 { score -= 6.0; }
        if pr % 7 == 0 { score -= 3.0; }
        if pr < 10 { score += 25.0; } // dead space below min item size
        else if pr < 20 { score += 10.0; }
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
            // harmonic class match between next item and post residual
            if pr % next_item_size == 0 { score -= 8.0; }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Tightness reward: filling most of the bin is good.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 15.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we only open bins when
    // existing fits are truly poor; decay as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 8.0 * progress;
        // opening a new bin is more attractive if open bins are fragmented
        if mean_residual < 25.0 { score -= 10.0; }
    }

    // Prefer denser packing when many bins are open (consolidation).
    score += open_bins_count as f64 * 0.15;

    // Integer-division threshold on item size: big items prefer low residual bins.
    if item_size / 40 >= 1 && post_residual < 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap is pure waste
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize residual that cannot fit even the smallest possible next item (1..100 interface).
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 15.0;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bins pressure: discourage spreading across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= 10.0 + 30.0 * (fragmentation - 0.5).clamp(0.0, 1.0);
    }

    // Slight preference for tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover dead space
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // tiny scrap is fine
            } else {
                score += 0.3 * dead;
            }
        }
    } else {
        // Last item: strongly reward exact closure.
        if post_residual == 0 {
            score -= 80.0;
        }
    }

    // Compare residual against mean residual: favor bins already below mean
    // (concentrate waste in few bins) unless this is a last-chance bin.
    if fitting_bins_count == 1 {
        score -= 40.0; // last chance before opening a new bin
    } else if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: make empty bin attractive only when no
    // open bin offers a good fit (post_residual small).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted if current fit is bad
        let best_possible = if post_residual < 15.0 { 0.0 } else { post_residual as f64 };
        score = 70.0 + best_possible;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 10.0; // fresh bin guarantees lookahead room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(3) / (bin_capacity as f64).powi(2);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size {
        score += 8.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: as the stream progresses, consolidate more aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 5.0;
    }

    // New-bin candidate: make empty bins slightly unattractive unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Mild preference for bins with residual close to item size (perfect-ish fit).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 15.0 * (1.0 - gap * gap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: quadratic dead-space penalty, sharpened with stream progress
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth progress coupling: penalize wasted space more as stream advances
    score += 20.0 * progress * pr_norm * pr_norm * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 15.0 * (-pr_norm * 8.0).exp();

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * (1.0 - progress);
    }

    // Lookahead: penalize if post_residual can't fit the next item, smoothly
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let next_norm = next_item_size as f64 / cap;
        score += (1.0 - fits_next) * (6.0 + 10.0 * next_norm) * (0.5 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for reusing bins over opening new ones
    score += 1.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by capacity fraction
    let frac = post_residual as f64 / cap_f; // 0..1
    // Class boundaries at 0, 10, 20, 50, 100 (harmonic classes)
    let class_penalty = if post_residual == 0 {
        -50.0 // perfect fit, strongly reward
    } else if post_residual <= 10 {
        -20.0 // near-perfect, dead space minimal
    } else if post_residual <= 20 {
        0.0
    } else if post_residual <= 50 {
        15.0 // mid dead space
    } else {
        30.0 // large residual: bin still useful, less penalty for wasting
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals matching common item sizes
    // (multiples of 10) are more likely to be filled by future items
    let harmonic_mod = post_residual % 10;
    if post_residual > 0 {
        score += harmonic_mod as f64 * 1.5; // non-multiple residuals = awkward dead space
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward chains: next item fits, especially exact/near-exact
        let chain_slack = post_residual - next_item_size;
        score -= 25.0 - (chain_slack as f64) * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize slightly if residual becomes stranded
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is unusable
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; discount when many bins open or item is large
        score += 60.0;
        if item_size >= 60 {
            score -= 25.0; // large items start fresh bins fine
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing potential with next item
        }
    }

    // Mean residual coupling: if mean residual is low, protect open bins less
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (mean_residual / cap_f) * 5.0 * (1.0 - progress);

    // Integer-division threshold: residual that can hold at least half-capacity item
    if post_residual / 2 >= 25 && post_residual < 50 {
        score -= 8.0; // residual still valuable for medium items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual <= 30 {
        score += 4.0;
    } else {
        // Larger post-residuals are more usable; gently reward them.
        score -= 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaves a gap that cannot host the next item: penalize proportionally.
        score += 0.15 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, tolerate spreading less.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is tight relative to the mean (well-packed).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in the stream, be more conservative: favor tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: penalize small post-residual nonlinearly.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        score += (post_residual as f64).powf(1.3) * 0.15;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.2; // next item fits, reward closeness
        } else {
            // next item won't fit here; penalize proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits, avoid waste.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless it enables a good chain for the next item.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            40.0
        } else {
            0.0
        };
        // New bin baseline: worse than a decent existing fit.
        score += 120.0 - chain_bonus + (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Slight preference for filling fuller bins early.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative waste ratio
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space: post_residual too small for typical future items
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * chain;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual can't host next item: penalize proportionally
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when it's genuinely a good fresh start
    if bin_residual == bin_capacity {
        // Prefer new bin when current bin fit is poor and item is large
        let poor_fit = fit_ratio < 0.6;
        if poor_fit {
            score -= 15.0 + item_size as f64 * 0.3;
        } else {
            score += 50.0; // discourage wasteful new bins
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    score -= 5.0 * consolidation * (0.5 + progress);

    // Late-stream: prefer filling existing bins more aggressively
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: penalize post residual, scaled by stream progress (late stream -> tighter packing)
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear coupling: reward small post residuals with a quadratic trough
    score -= 30.0 * (1.0 - prn) * (1.0 - prn) * (1.0 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next_fit = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    score += 12.0 * (1.0 - next_fit) * (0.3 + progress);

    // Reward last-chance bins smoothly
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (1.0 - prn);

    // Mild penalty when bin residual deviates from mean residual (encourage balanced fills)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for opening new bins early, reusing bins late
    score += (1.0 - progress) * 3.0 * (prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and integer-division tiers.
    let pr = post_residual;
    let residue = pr % 10;
    let tier = pr / 10; // 0..=10

    // Reward tight fits: small post residual is good, but dead space in (0,10) is worst.
    if pr == 0 {
        score -= 120.0; // perfect fit
    } else if pr < 10 {
        score += 45.0 - (pr as f64) * 4.0; // small unusable sliver penalty
    } else if pr >= 10 && pr <= 20 {
        score -= 25.0; // post residual can host a typical small item
    }

    // Tier-based harmonic reward: prefer post_residuals divisible into useful chunks.
    let harmonic = match tier {
        0 => 0.0,
        1 => -10.0,
        2 => -18.0,
        3 => -8.0,
        4 => 6.0,
        5 => 0.0,
        6 => -6.0,
        7 => 4.0,
        8 => 2.0,
        9 => 8.0,
        _ => 0.0,
    };
    score += harmonic;

    // Modulo-10 residue shaping: round residuals are more reusable.
    if residue == 0 {
        score -= 12.0;
    } else if residue == 5 {
        score -= 6.0;
    } else if residue <= 2 || residue >= 8 {
        score += 3.0;
    }

    // Lookahead coupling: does next item fit exactly into post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / 40.0);
            if gap % 10 == 0 {
                score -= 8.0; // harmonic chain
            }
        } else {
            // next item won't fit here; penalize less if other bins remain
            if fitting_bins_count <= 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin before opening a new one: strong bonus unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr <= 30 {
            score -= 35.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when mean residual is small
    // or the current fit leaves a bad harmonic class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 100.0 - 40.0 * progress + 10.0 * pressure;
        if pr == bin_capacity {
            // empty-bin call: pr == capacity; keep neutral baseline
            score = 60.0 + 10.0 * pressure - 40.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Small global tightening with progress.
    score *= 1.0 + 0.1 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Penalize creating a residual that no plausible item can use later:
    // if post_residual < next_item_size, this bin's leftover is likely dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 4.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // this bin can still serve the lookahead item
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing ones rather than opening more; when few are open, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Deviation from mean residual: prefer bins that deviate from the mean
    // (reduces fragmentation diversity across bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild stream-progression term: later in the stream, be more conservative
    // with new bins (slight extra penalty on the empty-bin candidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead coupling: does the next item fit what remains? ---
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect two-item chain: strongly reward
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits, reward proportional to tightness of that future fit
            let slack = (pr - nx) / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack);
        } else {
            // Placement creates dead space unusable by the next item
            let waste = (nx - pr) / nx.max(1.0);
            score += 18.0 * waste;
        }
    }

    // --- Tightness of the current placement ---
    let br = bin_residual.max(1) as f64;
    score -= 22.0 * (item_size as f64 / br);

    // --- Last-chance bin: avoid opening a new bin when this is the only fit ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- Relative residual context: prefer bins tighter than the average ---
    score += 0.12 * (bin_residual as f64 - mean_residual);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && post_residual == next_item_size;
        if perfect_chain {
            // Opening fresh is fine if it enables an exact next-item fit
            score -= 6.0;
        } else {
            // Prefer existing bins unless nothing else works
            score += 14.0;
            if fitting_bins_count == 0 {
                score -= 20.0; // no open bin can fit: new bin is necessary
            }
        }
    }

    // --- Mild stream-progress pressure: late in the stream, consolidate ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0; // unusable sliver
        } else {
            score += 0.35 * dead * (1.0 - tightness);
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: strongly prefer filling existing bins completely
        score -= 80.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (post_residual as f64 / bin_residual as f64);
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well. Penalize opening a new bin, more so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = bin_capacity as f64 - item_size as f64;
        score += 20.0 + 30.0 * progress + 0.2 * waste;
        // if many bins already open and mean residual is large, opening new is bad
        score += 0.1 * open_bins_count as f64 + 0.05 * mean_residual;
        // but if item is huge and mean residual is small, new bin is less bad
        if item_size >= 70 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate waste).
    if bin_residual < bin_capacity {
        score += 0.08 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Time-horizon coupling: early on, be greedy about fill; late, preserve space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear shaping: penalize large dead space
    // quadratically, but reward tight fits (small x) super-linearly.
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (less room to fix it).
    let dead_penalty = x * x * (1.0 + 2.0 * progress) * cap * 0.5;
    let tight_reward = (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);

    score += dead_penalty;
    score -= tight_reward;

    // Cubic interaction: mid-range residuals get extra smoothing depending
    // on mean residual across bins (relative fragmentation).
    let mean_x = mean_residual / cap;
    score += 0.5 * x * x * x * cap * (mean_x - x).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        let fit_quality = 1.0 - diff / cap;
        if pr >= nx {
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized early,
    // but attractive when open bins are highly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score = cap as f64 * (0.9 + 0.3 * progress) - 30.0 * frag * (open_bins_count as f64).ln1p();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible by 10 (harmonic with typical item sizes) are more usable.
    let harmonic = if post_residual % 10 == 0 {
        0.0
    } else if post_residual % 5 == 0 {
        4.0
    } else {
        8.0
    };
    score += harmonic;

    // Penalize very small dead space that nothing (min item ~10) can use.
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; leftover is "wasted" until later
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive only if the item is large relative to capacity
        // and no tight fit exists elsewhere.
        score += 15.0 - (item_size as f64 / bin_capacity as f64) * 20.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Progress-based tiebreak: slight preference for tighter bins early,
    // more aggressive consolidation late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are pure waste,
    // but gaps too small for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // hard-to-fill gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last fitting bin: strong pressure to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins with residual close to the mean (keeps residual profile uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits in the post-residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the next item
    }

    // New empty bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 70.0 + 15.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin is perfect — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 35.0 * snug;
        } else {
            // Next item will NOT fit in this bin's leftover: penalize dead space,
            // more so if the leftover is small (unusable wedge).
            let dead = post_residual as f64;
            if dead < 20.0 {
                score += 25.0 * (1.0 - dead / 20.0);
            }
        }
    }

    // Compare residual against mean residual: bins with more free space than
    // average are better hosts for large future needs; prefer spreading load.
    if post_residual as f64 > mean_residual {
        score -= 5.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score += 5.0 * ((mean_residual - post_residual as f64) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Late in the stream, consolidation matters more — penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 10.0;
    }

    // Penalize creating dead space that can only hold tiny future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual as u32 {
            // next item still fits after this placement: mild reward
            let slack = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 15.0 * (1.0 - slack);
        } else {
            // next item won't fit here; penalize less if post residual is still large
            let waste_ratio = next_item_size as f64 / bin_capacity as f64;
            score += 8.0 * waste_ratio;
        }
    } else {
        // Last item: any bin that fits is fine, prefer fullest.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open,
        // reward when open bins are mostly full (low mean residual).
        score += 15.0 + 2.0 * crowding;
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score -= 25.0 * mean_fullness;
    } else {
        // Existing bin: reward using crowded, residual-rich bins.
        score -= 5.0 * (1.0 - 1.0 / (1.0 + crowding));
    }

    // Time horizon: early in the stream, opening bins is cheap (future
    // items can fill them); late in the stream, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild preference for bins whose residual is close to item size
    // (relative fit quality), independent of absolute post residual.
    let fit_quality = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_quality;

    // Penalize wasting large residual bins on small items.
    if item_size < bin_residual / 2 && bin_residual > bin_capacity / 2 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize leftover space, quadratically normalized by capacity.
    let mut score = (pr / cap).powi(2) * cap;

    // Non-linear coupling of post_residual with stream progress:
    // early in the stream, tolerate larger leftovers (bins stay reusable);
    // late in the stream, strongly prefer tight fits.
    let progress_pressure = (progress * std::f64::consts::PI).sin().abs();
    score *= 1.0 - 0.45 * progress_pressure * (1.0 - (pr / cap));
    score += 0.35 * progress * (pr / cap) * cap;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = (-pr / 20.0).exp();
    score -= 6.0 * tightness;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.25 * it;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs();
        score -= 8.0 * fits_next * (-gap / 25.0).exp();
        // Penalize leaving a gap slightly larger than next item (dead space).
        score += 4.0 * (pr / cap) * (1.0 - (-gap / 15.0).exp());
    }

    // Prefer spreading across many open bins when mean residual is high,
    // but only via smooth coupling with post_residual.
    let mean_norm = mean_residual / cap;
    score += 3.0 * mean_norm * (pr / cap).sqrt() * (1.0 + progress);

    // Mild penalty for using a fresh empty bin when other bins could fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo classes on capacity ---
    // Class 0: post_residual == 0 (perfect fit) -> strong reward
    // Class 1: post_residual in 1..=10 (near-perfect) -> reward
    // Class 2: post_residual in 11..=30 (medium dead space) -> mild penalty
    // Class 3: post_residual > 30 (large usable space) -> mild reward
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 30 {
        score += 25.0;
    } else {
        score -= 10.0;
    }

    // Harmonic compatibility: does post_residual form a "good pair" with next_item_size?
    // If next item exactly fills the leftover, huge reward; if next item can't fit
    // into leftover, penalize dead space proportionally to how "wasted" it is.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            // leftover after next item: harmonic class of the pair remainder
            let rem = post_residual - next_item_size;
            if rem == 0 {
                score -= 120.0;
            } else if rem <= 10 {
                score -= 50.0;
            } else {
                score += (rem as f64) * 0.5;
            }
        } else {
            // next item cannot use this bin's leftover -> leftover is at risk of dead space
            // penalize more when leftover is small-but-nonzero (classic awkward class)
            if post_residual <= 10 {
                score += 40.0; // awkward sliver, next item can't use it
            } else {
                score += 10.0;
            }
        }
    } else {
        // last item: prefer perfect fit strongly
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad fit
    // unless the fit is actually good.
    if fitting_bins_count == 1 && post_residual > 30 {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is wasteful unless current item is large
    // and would leave a usable harmonic leftover. Penalize new bin, scaled by progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // large items (>50) justify new bins more; small items should use existing bins
        score += 120.0 - 80.0 * fill_ratio + 20.0 * progress;
        // if no open bins at all, opening is necessary
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Tie-break toward consolidating residuals: bins far from mean residual get slight penalty
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Perfect fit for a known next item: strongly reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless it enables a large item placement
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
    }

    // Late in stream: be more conservative, avoid leaving medium gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual >= 10 && post_residual < 25 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: place item so that the residual perfectly
    // accommodates the next item — a huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item still fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
    }
    // Next item does NOT fit here: penalize proportional to wasted lookahead.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Penalize dead space smaller than the minimum plausible item size (1..100):
    // residual below ~10 is nearly unusable.
    if post_residual < 10 {
        score += 150.0;
    }

    // Prefer bins whose residual is already below the mean (tighter bins close faster).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse; make new bin expensive).
    if bin_residual == bin_capacity {
        score += 80.0 + (fitting_bins_count as f64) * 30.0;
        // Early in the stream, opening bins is cheaper (builds diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
    }

    // Mild preference for tighter fits overall (waste minimization).
    score += (item_size as f64 / bin_residual as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space avoidance).
    if post_residual < 10 {
        score -= 25.0;
    }
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize large leftover gaps that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }
    if post_residual >= 50 {
        score += 5.0; // large residual is fine but not for tiny items
    }
    if item_size < 20 && post_residual > 40 {
        score += 8.0; // avoid wasting big space on tiny items
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 10.0;
            // bonus if next item then leaves a small remainder (chain fit)
            let chain = post_residual as f64 - next_item_size as f64;
            if chain < 10.0 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation (prefer fuller bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64).ln() * 3.0;
    score += consolidation * (1.0 - fit_ratio);
    score += 6.0 * progress * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Early stream: be more open to new bins; late stream: fill existing bins.
    if progress < 0.25 && bin_residual == bin_capacity {
        score -= 4.0;
    }
    if progress > 0.75 && bin_residual == bin_capacity {
        score += 10.0; // discourage new bins late in stream
    }

    // New-bin candidate baseline: keep it competitive only when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let progress_weight = 0.35 * t + 0.25 * t * t;
    score += progress_weight * norm_pr * cap;

    // Penalize large dead space quadratically
    score += 0.15 * norm_pr * norm_pr * cap;

    // Reward near-perfect fits (post_residual small relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 3.0 * (next_item_size as f64 / cap);
        } else {
            score += 1.5 * (1.0 - pr / cap) * (next_item_size as f64 / cap);
        }
    }

    // Prefer filling bins when many bins are open relative to mean residual
    let mean_gap = (mean_residual - pr) / cap;
    score += 0.5 * mean_gap * mean_gap * (open_bins_count as f64).sqrt();

    // Mild preference for keeping fewer open bins early
    score += 0.02 * (open_bins_count as f64) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: items are 1..=100, capacity 100.
    // Class the post_residual into 10-wide harmonic buckets; small classes are good.
    let post_class = post_residual / 10;
    score += match post_class {
        0 => -25.0,                    // post_residual < 10: nearly perfect fit
        1 => -10.0,                    // 10..19: fits the smallest item class
        2 => -4.0,                     // 20..29
        3 => 0.0,
        4 => 5.0,
        5 => 9.0,
        6 => 13.0,
        7 => 16.0,
        8 => 18.0,
        _ => 20.0,                     // huge leftover: wasteful placement
    };

    // Exact modulo coupling: leftover that is an exact multiple of small item
    // granularities is reusable dead space, reward it.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 4.0; }
    }

    // Lookahead: does the next item fit into the post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward keeping room for the next item, stronger if the leftover
        // leaves a tight (harmonically small) remainder after that too.
        let second = post_residual - next_item_size;
        score -= 12.0 - (second as f64) * 0.05;
        if second < 10 { score -= 6.0; }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize mildly, scaled by how far off we are.
        let gap = next_item_size - post_residual;
        score += (gap as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure coupling: when many bins are open with high mean residual,
    // prefer filling existing bins harder (penalize leaving big leftovers).
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.08;
    }

    // New-bin candidate: residual == capacity. Opening a new bin is only good
    // if the item is large relative to capacity or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score = 45.0 - fill_frac * 30.0; // baseline for fresh bin
        if fitting_bins_count == 0 { score -= 100.0; } // must open a bin
        if item_size >= 70 { score -= 15.0; }          // big items deserve fresh bins
    }

    // Slight progression bias: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (10.0 - post_residual.min(10) as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item also fits well into resulting residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted gap
        score += 8.0;
    }

    // Penalize small unusable dead space (waste) relative to capacity
    if post_residual > 0 {
        let waste = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += waste * 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer tighter-than-average bins
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in stream: slightly favor opening fresh bins to build flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/tight fits.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * fitting_bins_count as f64;
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // New bins more acceptable if mean residual across bins is large.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Mild bonus for keeping mean residual balanced.
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Prefer filling bins with high residual among fitting bins slightly less
    // than tight ones (best-fit baseline already does this via post_residual).

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = 1.0 + progress;
    let poly = norm_post * (1.0 + 0.8 * progress * norm_post + 0.6 * p * norm_post * norm_post);

    let mut score = poly * 100.0;

    // Penalize dead space that can never be used by the next item
    if next_item_size > 0 && post > 0.0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
            score += (gap / cap) * (30.0 + 40.0 * progress) * (gap / cap);
        } else {
            score -= 12.0 + 18.0 * progress;
        }
    }

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (20.0 + 60.0 * progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Mild pressure against accumulating many open bins with slack
    score += (open_bins_count as f64) * norm_post * 1.5;

    // Encourage bins whose residual deviates favorably from the mean
    score -= (mean_residual - post) * 0.15;

    // New-bin candidate: neutral-ish baseline, penalized slightly early, less late
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - norm_post * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space quality.
    // Residuals that can host common small items (multiples of 10/20) are valuable.
    let post = post_residual;
    if post == 0 {
        // Perfect fit: ideal packing.
        score -= 60.0;
    } else if post >= 10 && post <= 20 {
        // Small dead space, still usable by small items.
        score -= 10.0;
    } else if post > 20 && post < 40 {
        // Awkward mid-range dead space: penalize.
        score += 15.0;
    } else if post >= 40 && post < 60 {
        // Moderately usable.
        score -= 5.0;
    } else {
        // Large residual: bin still very flexible.
        score -= 20.0;
    }

    // Harmonic class via integer division: post_residual / 25 buckets.
    let bucket = post / 25;
    score -= (bucket as f64) * 8.0;

    // Lookahead: does this bin also fit the next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            // Can host the next item too: strong reward, scaled by how snugly.
            let slack = post - next_item_size;
            score -= 25.0;
            if slack <= 10 {
                score -= 15.0; // near-perfect chain fit
            }
        } else {
            // Next item won't fit: mild penalty proportional to gap.
            score += ((next_item_size - post) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize empty-bin choice, more when many bins are open.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        score += 35.0 + open_pressure * 2.0;
        // But early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer tighter fits overall: reward small post_residual relative to capacity.
    score += (post as f64 / bin_capacity as f64) * 10.0;

    // Deviation from mean residual: bins far below mean are already tight,
    // filling them fully is good; bins far above mean should be kept flexible.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small gaps that no future item (min size 1..100, but
    // typically >= 10) can use are wasted. Penalize tiny post_residuals sharply.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        } else if post_residual < 20 {
            score += 15.0; // hard to fill
        } else if post_residual < 35 {
            score += 4.0;
        }
    } else {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward tight fits relative to bin capacity
    score += 20.0 * (1.0 - (item_size as f64 / bin_capacity as f64));

    // Open-bins pressure: more open bins -> penalize spreading into new/loose bins
    score += 1.5 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits, slight penalty for wasting the gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 12.0; // discourage opening new bin when alternatives exist
        }
    }

    // Mean residual coupling: if this bin is far below mean residual (very full),
    // it's precious; penalize dumping items into already-tight bins unless tight fit.
    let dev = mean_residual - bin_residual as f64;
    if dev > 15.0 {
        score += 5.0;
    } else if dev < -15.0 {
        score -= 3.0;
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is an ideal chained placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more dead space: mild penalty on slack
            score -= 40.0 - 2.0 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            let gap = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins that keep
    // residuals balanced (avoid stranding many large residuals).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 80.0;
        // but if lookahead item is huge and this bin would be very tight, allow it
        if next_item_size > 0 && item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Late in the stream, consolidate: favor bins with small residuals overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item (1..100 unknown).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 6.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 9.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: any placement is fine, prefer the emptiest bin.
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // When many bins fit the item, prefer the fullest bin (best-fit pressure).
    if fitting_bins_count > 1 {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Global state coupling: if mean residual is low, opening new bins is costly;
    // favor reusing open bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 5.0 * mean_pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin should only win when the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 8.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0; // fresh bin can host a pair
        }
        score += 2.0 * open_bins_count as f64 * 0.1; // mild penalty for bin proliferation
    }

    // Mild exploration term: slight non-linear nudge based on residual structure.
    score -= 0.02 * (bin_residual as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit typical future items
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (1.0 + progress);
        } else {
            score -= 5.0 * (1.0 - (ni / pr)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mild penalty for spreading across many bins late in stream
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral baseline, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice" fractions
    // of capacity (0, 10, 20, 25, 50) are more reusable -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nice = [0.0, cap * 0.1, cap * 0.2, cap * 0.25, cap * 0.5];
    for n in nice.iter() {
        let d = (post - n).abs();
        if d < 1.0 {
            score -= 6.0 * (1.0 - d);
        }
    }

    // Integer-division harmonic classes: post_residual divisible by 10 or 5
    // creates cleaner packing structure.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Dead-space penalty: small unusable leftovers (1..10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much slack remains after it
            let chain = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - chain / cap);
        } else {
            // next item won't fit here: penalize tight-but-wasteful leftovers
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 3.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // item fits poorly everywhere. Base new-bin score is its full residual (100),
    // so subtract when opening is genuinely desirable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = mean_residual / cap;
        let tight_fit = (item_size as f64 / cap) > 0.8;
        if open_bins_count == 0 || (fitting_bins_count == 0) || tight_fit || crowdedness < 0.15 {
            score -= 20.0 + 10.0 * (1.0 - progress);
        } else {
            score += 10.0 + 15.0 * crowdedness;
        }
    } else {
        // Mild preference for tighter (smaller-residual) bins beyond raw post_residual.
        score -= 0.02 * (bin_residual as f64 - post);
    }

    // Late-stream consolidation: favor filling nearly-full bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 2.0 * progress * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Prefer bins with residual below mean (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact match with next item size (perfect 2-step packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Big bonus if next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize if next item cannot fit here after placement (dead-end).
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Penalize tiny unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize opening a new bin when others fit,
    // unless the item is large and would leave a very tight residual elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 60 {
            score -= 20.0; // large items are fine in fresh bins
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += (post_residual as f64 - mean_r) * 0.5;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap that traps it.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // (large items deserve fresh space) or current fit is hopeless.
    if bin_residual == bin_capacity {
        let largeness = item_size as f64 / bin_capacity as f64;
        let bad_fit = if post_residual > 0 { (post_residual as f64) / bin_capacity as f64 } else { 1.0 };
        let penalty = 60.0 - 55.0 * largeness - 20.0 * (1.0 - bad_fit);
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += penalty * (0.6 + 0.6 * progress);
    }

    // Global state coupling: many open bins with high mean residual => encourage
    // filling existing bins (avoid bin sprawl).
    let sprawl = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    if bin_residual != bin_capacity {
        score -= sprawl.min(20.0);
    }

    // Small penalty for bins whose residual becomes awkwardly small-but-nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: prefer tight fits but keep flexibility (moderate residuals OK).
    // Late in the stream: strongly prefer minimal post_residual to squeeze the tail.
    let pr_norm = pr / cap;
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += 40.0 * w_early * pr_norm * (1.0 - pr_norm);
    score -= 30.0 * w_late * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Dead-space penalty: residuals too small to fit typical items are bad,
    // especially mid/late stream. Smooth quadratic in pr_norm.
    let dead = (pr_norm * (1.0 - pr_norm)).max(0.0);
    score += 25.0 * (0.25 - dead) * (0.5 + progress);

    // Lookahead coupling: reward residuals that can still hold the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 15.0 * (1.0 - slack) * (0.3 + 0.7 * progress);
        } else {
            // post-residual can't fit next item: penalize smoothly.
            let gap = (n - pr) / cap;
            score += 12.0 * gap * gap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly early (reuse bins), but allow opening
    // a fresh bin late when post_residual of existing bins would be tiny/dead.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0;
        if item_size as f64 / cap > 0.7 {
            score -= 10.0; // big items fit cleanly in fresh bins
        }
    }

    // Encourage balancing against mean residual (smooth spreading of load).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-capacity classes are gold.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes on post_residual: small residues that pair with common
    // small items (<= 20) are reusable; mid residues (21..=40) are decent;
    // large residues are near-empty bins, mildly penalize waste.
    let r = post_residual % 20;
    let class_bonus = match r {
        0 => 25.0,
        1..=10 => 12.0,
        11..=19 => 4.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer division thresholds: residual bucket by fifths of capacity.
    let fifth = (post_residual * 5) / bin_capacity.max(1);
    score -= match fifth {
        0 => 30.0,          // nearly full bin: excellent packing
        1 => 18.0,
        2 => 8.0,
        3 => -6.0,          // penalize leaving a half-empty bin (waste)
        _ => -12.0,         // barely-touched bin: strong penalty
    };

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // smooth lookahead fit reward, stronger for tight fits
        let tight = 1.0 - (post - next_item_size as f64) / cap;
        score -= 30.0 * tight.max(0.0);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally
        score += 10.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        // prefer new bin when existing residuals are small (crowded bins)
        score += 55.0 * (1.0 - crowding) - 55.0 * crowding;
        // late in the stream, avoid proliferating bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild pressure against accumulating many open bins with large residuals.
    score += 0.02 * (open_bins_count as f64) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residual gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny gap = dead space
        } else if post_residual < 20 {
            score += 15.0;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly into the resulting residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 20.0;
        } else if gap < 10.0 {
            score -= 10.0;
        } else {
            score += gap * 0.3;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 1.5;
        score += 10.0 + pressure;
        if fitting_bins_count == 0 || post_residual as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Mild pressure to prefer filling already-open bins as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward exact match of leftover to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Leftover can host next item: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // Leftover too small for next item: penalize dead space, worse when tiny.
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 2.0;
        }
    }

    // Penalize leaving tiny unusable gaps (dead space below min item size 1..10 zone).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they leave bad residue.
        score += 300.0;
        // If no other bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Prefer bins tighter than average (best-fit flavor relative to mean residual).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.5;
    }

    // Mild reward for keeping number of open bins low by filling existing ones.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize dead space relative to the smallest plausible item (1..100 range).
    let waste = post_residual as f64;
    if waste > 40.0 {
        score += 0.6 * (waste - 40.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = waste > 40.0 && next_item_size > post_residual;
        if poor_fit {
            score -= 30.0; // fresh bin is genuinely better
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64; // prefer reusing open bins
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 <= 10 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's remainder; penalize leaving big gap
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Global state coupling: with many open bins, prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fullness * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be conservative with new bins; late, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early in the stream, tolerate loose fits less (keep bins flexible);
    // late in the stream, reward tight packing more aggressively.
    let tightness = 1.0 - (pr / cap);
    let coupling = tightness * (1.0 + 2.0 * p2 + 3.0 * p3) * 20.0;
    score -= coupling;

    // Penalize large dead space non-linearly (quartic in normalized residual).
    let dead = pr / cap;
    score += 35.0 * dead * dead * dead * dead;

    // Lookahead: penalize if the next item cannot use the post-residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            score += 12.0 + 0.15 * (ni - pr);
        } else {
            // Reward leaving space exactly usable by the next item.
            let fit_quality = 1.0 - ((pr - ni) / cap);
            score -= 8.0 * fit_quality * fit_quality;
        }
    }

    // Last fitting bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate handling: penalize opening new bins when good fits exist.
    if bin_residual == bin_capacity {
        let avg_dead = dead * 0.5 + (mean_residual / cap) * 0.5;
        score += 10.0 + 40.0 * (1.0 - avg_dead);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild penalty for proliferating open bins early on.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Mean-residual alignment: prefer bins whose post-residual tracks the mean.
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod common item sizes
    let pr = post_residual;
    // Reward leftover that lies in a "usable" harmonic class (multiple of 10/20/25)
    if pr == 0 {
        score -= 40.0; // perfect fit is king
    } else if pr % 10 == 0 && pr >= 10 {
        score -= 12.0;
    } else if pr % 25 == 0 {
        score -= 10.0;
    } else if pr % 20 == 0 {
        score -= 8.0;
    } else {
        // awkward dead space: penalize small unusable slivers
        if pr < 10 {
            score += 25.0;
        } else {
            score += (pr as f64) * 0.35;
        }
    }

    // Lookahead coupling: does the next item fit exactly into the leftover?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item fits, but measure how well
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 15.0;
            }
            score -= gap as f64 * 0.4;
        } else {
            // next item cannot use this bin's leftover; leftover riskier
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // opening new bin is penalized mildly unless existing bins are fragmented
        score += 20.0 - 25.0 * (1.0 - pressure) - (mean_residual / bin_capacity as f64) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress-based mild regularization
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits (small but still potentially usable gaps).
    if post_residual <= 15 {
        score -= 12.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item cannot fit in the post residual but could fit elsewhere:
    // creating a gap that strands the lookahead item.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across too many bins when
    // this bin is a poor fit; encourage using existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit anywhere) or no open bins exist.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0; // base cost of opening a new bin
        score -= 35.0 * tightness.max(0.6) - 21.0; // discount for large items
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference toward bins with residuals close to the mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize residuals too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
        // Reward leaving room that still fits the next item snugly
        if post_residual >= next_item_size && diff <= 20.0 {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Reward using bins that are already partially filled
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // Slight preference for tight packing relative to mean residual
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Stream progression: later in stream, be more conservative about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be picky about tight fits; later, just fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward tight fits: small post_residual is already the base, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't fit the average upcoming item.
    let avg_next = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    if (post_residual as f64) < avg_next * 0.5 && post_residual > 0 {
        score += 6.0 * (1.0 - post_residual as f64 / avg_next.max(1.0));
    }

    // Lookahead: if the next item fits perfectly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 15.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't follow here; slight penalty unless bin becomes near-full anyway.
        score += 3.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when good fits exist
    // or the stream is late (amortization of the new bin is short).
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Early on, opening bins is cheaper (future items can share).
        score -= 20.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is actually fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mild preference for bins with residuals below mean (balance across bins).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.05 * (residual_f - mean_residual);
    } else {
        score -= 0.03 * (mean_residual - residual_f);
    }

    // Spread load when many bins are open and stream is early.
    if open_bins_count > 3 && progress < 0.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post_residual (non-linear)
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 40.0 * (1.0 - tight);

    // Perfect-fit style reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * ratio * (1.0 - tight);
        } else {
            // dead space relative to lookahead: penalize unusable remainder
            let waste = (post_residual as f64 - (post_residual as f64).min(next_item_size as f64)).max(0.0);
            score += 0.15 * waste * (0.5 + progress);
        }
    }

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - progress) + pr * progress * progress;
    score += 35.0 * poly;

    // Mild pressure against proliferating many bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    // Prefer bins with residual near mean (balance)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 buckets.
    let class = post_residual % 10;
    // Small remainders (dead space) get penalized progressively.
    score += (10 - class) as f64 * 0.8;

    // Fraction-of-capacity coupling: post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize mid-range residuals (hard to fill later), reward very small ones.
    if frac > 0.3 && frac < 0.7 {
        score += 12.0;
    } else if frac <= 0.1 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else {
            score -= (10 - gap % 10) as f64 * 1.5;
            score -= gap as f64 * 0.05;
        }
    }
    // Penalize if next item cannot fit here (bin becomes dead weight for lookahead).
    if next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: encourage consolidation (prefer tighter fills).
    score += (open_bins_count as f64) * 0.3;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Integer-division threshold on post_residual: chunks of 25.
    let chunk = post_residual / 25;
    score += chunk as f64 * 2.0;

    // New-bin candidate: mild penalty so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable gap (items are >= 10)
    } else if post_residual == 0 {
        score -= 60.0; // perfect fill, strongly reward
    }

    // Penalize medium-dead-space zone mildly, reward large usable residuals.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual >= 50 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * (post_residual - next_item_size) as f64;
    }

    // Last-chance bin before opening a new one: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when no open bin fits well
    // (large item or all residuals too small).
    if bin_residual == bin_capacity {
        let poor_fits = mean_residual < item_size as f64 + 5.0;
        if poor_fits || item_size > 70 {
            score -= 15.0;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Slight preference for bins tighter than the mean (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space the next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: penalize opening a new bin unless it's a large item
    // or no good fits exist elsewhere
    if bin_residual == bin_capacity {
        let base = 120.0;
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 30.0 };
        score += base + lookahead_bonus
            - if item_size > bin_capacity / 2 { 40.0 } else { 0.0 }
            + (open_bins_count as f64) * 2.0;
    }

    // Progress scaling: tighten criteria late in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Penalize large dead space after placement (waste).
    if post_residual > 0 {
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 2.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        score -= 15.0;
        // Extra reward if next item fills the bin nicely after this one.
        let second_residual = post_residual as u64 - next_item_size as u64;
        if second_residual < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to mismatch.
        let mismatch = (next_item_size as f64 - post_residual as f64).abs();
        score += mismatch * 0.15;
    }

    // New-bin candidate handling: opening a new bin should be penalized mildly,
    // unless no open bin fits well (large post_residual everywhere).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 25.0;
        // Many open bins: discourage opening yet another.
        new_bin_score += open_bins_count as f64 * 2.0;
        // If mean residual is large, open bins have room; discourage new bin.
        new_bin_score += mean_residual * 0.3;
        // If this item is small relative to capacity, new bin wastes space.
        new_bin_score += (bin_capacity - item_size) as f64 * 0.4;
        // If item nearly fills a bin alone, new bin is fine.
        if item_size >= bin_capacity * 9 / 10 {
            new_bin_score -= 45.0;
        }
        // If no other bin can fit (this call is the only candidate), allow new bin.
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    // Mild global pressure: keep scores comparable across bins via mean residual.
    score -= mean_residual * 0.05;

    // Time-horizon modulation: early on, be more exploratory (favor diversity of fills);
    // later, favor tight packing more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= tightness * 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: waste after placement, with non-linear curvature favoring small residuals.
    let mut score = post + 30.0 * post_norm * post_norm;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (post_norm^2 term dominates); later, punish slack harder.
    score += 60.0 * post_norm * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits with smooth quadratic reward around post_residual near zero.
    score -= 25.0 * (1.0 - post_norm).powi(3) * (1.0 - progress);

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt).abs() / cap;
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here; slight penalty proportional to excess.
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, with smooth scaling by fitting_bins_count.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 40.0 * scarcity;
    }

    // Mild dispersion penalty: avoid bins far from the mean residual (keeps bin pool uniform).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so as the stream matures.
    if bin_residual == bin_capacity {
        score += 45.0 + 40.0 * progress;
    } else if fitting_bins_count == 1 {
        // Overriding new-bin preference when this is the last chance.
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "usable"
    // residue classes (multiples of 10, or small enough to be near-full) are rewarded.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 && pr <= 40 {
        -35.0 // clean, reusable residual
    } else if pr < 10 {
        -20.0 // near-perfect fill, tiny dead space
    } else if pr % 10 == 0 {
        -15.0 // clean but large leftover
    } else {
        // awkward residue: penalize proportionally to how non-aligned it is
        let off = (pr % 10) as f64;
        5.0 + off * 1.5
    };
    score += class_bonus;

    // Integer-division thresholds: does the leftover fit a "harmonic slot"
    // that could host a typical next item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as f64 >= n {
            // lookahead fits: reward, more so if it's a tight fit
            let tightness = 1.0 - ((pr as f64 - n) / cap);
            score -= 10.0 + 25.0 * tightness;
        } else {
            score += 8.0; // blocks the known next item
        }
        // modulo coupling: next item aligned with residual in 10-grid
        if pr % 10 == 0 && (next_item_size % 10 == 0) {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: discourage spreading, prefer tight fills.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 20.0 * crowding * (post_residual as f64 / cap);

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Progress-scaled tie-break: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / cap) * 10.0;

    // New-bin candidate: only attractive when current item is large relative
    // to residual (poor fit) or when residuals are generally low.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        score = cap * 0.6 - 30.0 * fit_ratio + 10.0 * (1.0 - progress);
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) >= next_item_size {
            score -= 12.0; // fresh bin can host the lookahead too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero leftovers are the worst outcome.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavy penalty.
        score += 45.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Penalize waste proportional to how much of the bin's useful space is destroyed.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: prefer spreading load / discouraging hoarding in few bins
    // when many bins are open; encourage closing tight bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave a bad gap
    // or when the next item would fit better in the leftover.
    if bin_residual == bin_capacity {
        let gap_bad = post_residual > 0 && post_residual < next_item_size.max(1);
        if gap_bad {
            score -= 40.0; // open fresh bin instead of ruining this one
        } else {
            score += 25.0; // discourage gratuitous bin opening
        }
    }

    // Lookahead: if next item exactly fits post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 10.0; // sets up a future sliver
    }

    // Slight preference for bins tighter than average (good fits cluster).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-perfect two-step matches: post_residual pairs with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins where next item leaves small slack again
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item can't use this dead space; penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
        // If next item is huge, prefer keeping residuals that can host it
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: minimize waste directly
        score += 0.3 * post_residual as f64;
    }

    // Tight fit bonus relative to mean residual: prefer bins tighter than average
    let tightness = (mean_residual - post_residual as f64).max(0.0);
    score -= 0.4 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large or fits are poor
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 20.0 * big_item - 30.0 * pressure;
    }

    // Slight preference for consolidating when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty (post_residual relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 40.0;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if the next item could have fit better in this bin's
    // post-residual than in the current item's placement.
    if next_item_size > 0 {
        if next_item_size as f64 > post_residual as f64 {
            // Next item won't fit here anyway; mild penalty proportional to dead space.
            score += 5.0;
        } else if next_item_size as u32 == post_residual {
            // Next item exactly fills the leftover: excellent chaining.
            score -= 35.0;
        } else {
            // Next item fits in the leftover: reward proportionally.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global state: many open bins with high mean residual -> prefer reusing bins
    // to avoid bin proliferation.
    if open_bins_count > 2 {
        score += (open_bins_count as f64).ln() * 2.0;
    }
    if mean_residual > (item_size as f64) {
        // Plenty of room elsewhere; only pick this bin if the fit is tight.
        score += 3.0;
    }

    // Discourage new-bin candidate unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * progress;
        // If mean residual across open bins is small, a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 12.0 * poly * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_post) * (1.0 + progress) * 8.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins with residuals below mean residual (compact usage)
    score -= (mean_residual - post).max(0.0) * 0.3;

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= (1.0 - ((post - nxt) / cap).abs()) * 4.0 * (1.0 - progress);
        } else {
            score += 3.0;
        }
    }

    // Penalize opening new bins early; allow it late when post_residual is large waste
    let new_bin = bin_residual as f64 == cap;
    if new_bin {
        score += 6.0 * (1.0 - progress) - 4.0 * progress * (1.0 - norm_post);
    }

    // Mild penalty for too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue bands
    // via integer division on 100-capacity fractions.
    let pr = post_residual;
    let class = pr / 10; // 0..10 harmonic classes of leftover space

    // Reward small leftover classes strongly (tight fit).
    match class {
        0 => score -= 60.0,               // perfect / near-perfect fit
        1 => score -= 40.0,               // leftover <= 19
        2 => score -= 25.0,               // leftover <= 29
        3 => score -= 12.0,
        4 => score -= 5.0,
        5 => score += 3.0,                // ~half-full leftover: poor
        6 => score += 8.0,
        7 => score += 14.0,
        8 => score += 20.0,
        _ => score += 25.0,               // barely used bin
    }

    // Nonlinear coupling: leftover that exactly complements a plausible
    // next item (lookahead) is valuable.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;                // next item fills this bin exactly
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= (20.0 - (slack as f64) * 0.4).max(0.0);
        } else {
            // next item cannot use leftover: leftover is more likely dead space
            score += (pr as f64) * 0.15;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, softened for large items
        // (which are hard to place later).
        let item_frac = item_size as f64 / cap;
        score = 55.0 + 30.0 * (1.0 - item_frac) + (pr as f64) * 0.1;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Many open bins with slack: avoid opening another.
        score += (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Prefer bins whose residual is below mean (packing big gaps first),
    // keeping tighter bins in play.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Mild pressure to use very full bins first.
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..~10)
    // are pure waste; penalize heavily as post_residual approaches unusable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * (fill_ratio - 0.8);
    }

    // Open bins pressure: discourage spreading across many bins when a good fit exists
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / 10.0;
        } else {
            // next item cannot use the gap -> dead space likely
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Mild preference to fill bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; fitting_bins_count==0 handled by caller
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.35;

    // 2-step lookahead: if the next item fits perfectly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover after that (double dead space)
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.55;
        } else {
            // next item does NOT fit this bin: post_residual is pure dead space
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean (already tight)
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        score += 15.0 + mean_residual * 0.4;
        if fitting_bins_count > 0 && post_residual > 0 {
            // only open new bin if open bins fit poorly
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Penalize large post_residual that is too small for typical items (dead space band)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream nears end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more strongly nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that likely can never be used again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Deter opening new bins when many bins are open and mean residual is small.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 45.0;
        // Cheaper to open new bin early in stream or when open bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If mean residual is small, open bins are nearly full -> new bin is fine.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        // If next item is large, a fresh bin is attractive.
        score -= 0.15 * next_item_size as f64;
        // If only one bin fits the item, opening a new bin wastes the tight fit.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Mild preference for bins with residual close to mean (balance workload).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight time-varying exploration pressure: later in stream, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 1.0 + 0.6 * progress + 0.8 * p2 - 0.4 * p3;

    let mut score = pr * poly;

    // Penalize large residual early (waste), reward tight fits increasingly late
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Dead-space penalty: residual too small to fit typical future items
    let dead = ((30.0 - pr).max(0.0) / 30.0).powi(2);
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Mild dispersion penalty vs mean residual
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: slightly favored early, discouraged late
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in the "small residue" band
    // (1..=10) is nearly unusable for items in [1,100] with typical sizes >=10,
    // so penalize it hard.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 25.0;
    } else if pr > 10 && pr <= 20 {
        score += 8.0;
    }

    // Integer-division thresholds on post_residual: classify residual into
    // capacity-fraction buckets; mid-size residuals are the most valuable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > half {
        score -= 6.0; // still roomy, good
    } else if pr > quarter {
        score -= 2.0;
    }

    // Modulo arithmetic: residuals congruent to small values mod 10 pair well
    // with typical item granularities.
    let m = pr % 10;
    if m == 0 {
        score -= 4.0; // clean multiple of 10, reusable
    } else if m >= 8 {
        score += 3.0; // awkward leftover
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 12.0;
        } else {
            score -= (10.0 - slack as f64 / 10.0).max(0.0);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize more if residual is tiny anyway
        if pr <= 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 10 {
            score += 20.0; // but a nearly-dead bin is not worth it
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer using it only when open bins are few or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.3;
    }

    // Mild pressure to consolidate: fewer open bins -> favor existing bins.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: gaps too small to plausibly hold future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, offset by benefit of full flexibility
        // when current bin would leave a large dead gap.
        let gap_penalty = if post_residual < 20 { 0.0 } else { (post_residual as f64 - 20.0) * 0.5 };
        score += 55.0 - gap_penalty;
        // Fewer open bins => cheaper to open new bin (spread load early).
        if open_bins_count > 3 {
            score += 10.0;
        }
    }

    // Pressure from many open bins: prefer tightening existing bins.
    score += (open_bins_count as f64).ln() * 3.0;

    // Lookahead: if next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; a large residual is still useful then.
        score += 5.0;
    }

    // Prefer bins tighter than average (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item leaves exactly room for next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Post-residual can fit next item comfortably (chain potential).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Perfect closure: bin filled exactly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize tiny dead space (unusable slivers) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 40.0 - 50.0 * avg_fullness;
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 20.0; // next item can't fit an empty bin anyway? (impossible) keep neutral
        }
    }

    // Late in the stream: consolidate into existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual below mean (pack tighter bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that end with small leftover.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual <= 25 {
        score -= 6.0; // still usable for small items
    } else if post_residual > 50 {
        score += 8.0; // leaving huge slack = poor packing
    }

    // Exact or near-exact fill is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item can use the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // next item won't fit here: leftover is likely dead weight
            score += 5.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual <= 30 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large item, few fitting bins) or when
    // the stream is young (many future items justify fresh capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64;
        // baseline new-bin cost grows with number of open bins (prefer consolidation)
        let mut nb = 60.0 + 3.0 * open_bins_count as f64;
        nb -= 50.0 * scarcity; // no alternative -> new bin is fine
        nb -= 80.0 * (1.0 - fit_ratio).min(1.0) * (1.0 - progress); // early stream, small item: fresh bin OK-ish
        nb += 40.0 * poor_fit * progress; // late stream: avoid waste, prefer existing bins
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            nb -= 30.0; // next item pairs perfectly with this item in a fresh bin
        }
        score += nb;
    }

    // Global state: when mean residual is high, packing into existing bins is cheap;
    // encourage using the bin whose residual is closest to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild time horizon shaping: early on, be greedy about tight fits; later, be conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.10 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, prefer tight fits more aggressively.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * it * (0.5 + 2.0 * progress) * 2.0;

    // Penalize large dead space super-linearly, scaled by progress.
    score += (pr / cap) * (pr / cap) * (20.0 + 40.0 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Reward bins whose residual aligns with the next item (smooth gaussian-like kernel).
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (-(d * d) * 200.0);
    }

    // Slight preference for bins below mean residual early (balance load),
    // above mean later (consolidate).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (5.0 - 10.0 * progress);

    // Mild penalty for opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that are "awkward": in (0, 10) nothing else fits (items >= 10... but sizes 1..100, so treat small leftover as waste only if tiny).
    if post_residual == 0 {
        score -= 25.0; // perfect fit is best
    } else if post_residual < 5 {
        score += 8.0; // unusable sliver
    }

    // Class-based bonus: residual divisible into likely future item sizes (harmonic classes of 10, 20, 25, 50).
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                b += 4.0 + (r / m) as f64;
            }
        }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional closeness of fit for next item
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual % next_item_size == 0 {
                score -= 6.0; // harmonic divisibility
            }
        } else {
            // next item won't fit here; penalize leaving large dead space
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer tight fills (low post_residual already does).
    if open_bins_count > 8 {
        score += 2.0 * frac;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when mean is high.
    if mean_residual > 20.0 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        // fresh bin: score = capacity, subtract a bonus so it competes when fits are poor
        score -= 10.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // pairing potential with next item
        }
    }

    // Progress-based mild annealing: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead-space zone: penalize proportionally.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual but still usable).
    if post_residual >= 10 && post_residual <= 30 {
        score -= 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit in the post residual, penalize slightly (dead end).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Mild penalty so existing bins with decent fits win.
        score += 10.0;
        // But relieve pressure if many bins are open and mean residual is low (poor fits everywhere).
        if mean_residual < (item_size as f64) {
            score -= 30.0;
        }
    }

    // Progression: slightly more conservative early (keep bins flexible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Discourage bins whose residual deviates wildly from mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead space penalty shaping)
    let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * fit_quality * fit_quality;

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack after hypothetically fitting next item: smaller slack is better
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - chain_slack / (bin_capacity as f64));
        } else {
            // post_residual cannot host next item: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(60.0);
        }
        // Bonus if next item would fit *exactly* after this placement
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 12.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        if fitting_bins_count > 0 && post_residual + item_size as u32 >= bin_capacity / 2 {
            score += 20.0;
        }
    }

    // Early stream: be slightly more liberal with opening bins (build good structure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress) * fit_quality;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing can use later (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave a big awkward gap.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: as the stream progresses, be more conservative with new bins
    // (fewer chances to consolidate), so favor existing bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream advances and when many bins are open.
        score += 15.0 * progress + 0.5 * open_bins_count as f64;
        // But if no open bin fits well (large item, few fitting bins), new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Global state coupling: penalize bins far from mean residual when mean is low
    // (keep residuals uniform to preserve combinability).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - progress);

    // Prefer filling bins that are already mostly full (low residual) generally.
    score += 0.1 * bin_residual as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize large post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr;
    score += 30.0 * pr_norm * pr_norm * cap;

    // Non-linear coupling with stream progress: later in the stream,
    // tight fits (small post-residual) become more valuable
    let tightness = 1.0 - pr_norm;
    score -= 40.0 * progress * tightness * tightness * tightness * cap * 0.1;

    // Smooth interaction: post_residual vs mean_residual divergence
    let mr = mean_residual.max(0.0);
    let dev = (pr - mr) / cap;
    score += 15.0 * dev * dev * cap;
    score += 10.0 * progress * dev * cap * 0.5;

    // Last-chance bonus: only bin that fits — reward using it smoothly
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress) * (1.0 - pr_norm * pr_norm);
    }

    // Lookahead: penalize if post-residual cannot fit next item (smooth gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth sigmoid-like gate around the fit boundary
        let margin = (pr - nxt) / cap;
        let gate = 1.0 / (1.0 + (-margin * 40.0).exp());
        score -= 12.0 * fits_next * gate * (nxt / cap);
        score += 8.0 * (1.0 - fits_next) * (nxt / cap);
    }

    // Mild penalty for too many open bins, smoothed by progress
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline so it's chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of dead space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tight * tight;

    // Harmonic class penalty: dead space in awkward bands (31..=50, 51..=70)
    // is less reusable than either tiny slivers (< 31, near-full) or large gaps (> 70).
    let cls = post_residual / 10;
    match cls {
        0 => score -= 6.0,          // near-perfect fill
        1 | 2 => score += 10.0,     // 10..29: poor reusability
        3 | 4 => score += 4.0,      // 30..49: mediocre
        5 | 6 => score += 7.0,      // 50..69: medium awkward
        7 | 8 => score -= 3.0,      // 70..89: still useful for big items
        _ => score -= 5.0,          // >= 90: highly reusable
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 9.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 8.0; // perfect chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasting this bin's residual.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make it attractive only when current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (item_size as f64) / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalty shrinks as stream progresses or bins are crowded.
        score += 18.0 * (1.0 - crowded.min(1.0)) * (1.0 - 0.5 * progress);
        // If no open bin fits, new bin is the fallback: soften penalty.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // when filling (concentrate waste), above average when item is large.
    let dev = bin_residual as f64 - mean_residual;
    if item_size > 50 {
        score += 0.08 * dev;
    } else {
        score -= 0.05 * dev;
    }

    // Mild bonus for using older/more populated bin sets to keep bin count stable.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
