    // New-bin candidate: keep neutral-ish, slightly penalized early, more attractive late
    if bin_residual == bin_capacity {
        score += 5.0 - 8.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small to ever hold the smallest item (1..100 range, use < 10 as conservative threshold).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Harmonic class logic: bucket post_residual by modulo-20 phase.
    // Residuals just above common item sizes (multiples of 10/20) are more reusable.
    let phase = post_residual % 20;
    score += phase as f64 * 0.4;

    // Integer-division threshold: residual in [50,100] is "half-bin or better" -> reusable, reward slightly.
    if (post_residual / 50) >= 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead coupling (k=2): reward bins that can also host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item leaves another usable residual (chained fit).
            if post_residual - next_item_size >= 10 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; if residual also can't fit anything later, penalize.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Progression-aware tightening: late in the stream, avoid fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Crowding: with many open bins, prefer compacting into existing ones.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // Brand-new empty bin candidate: baseline slightly worse than any reasonable existing fit,
    // so it only wins when all open bins would create bad (small/dead) residuals.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 15.0;
        // A new bin is attractive if the item is large (would leave little residual anyway).
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: small nonzero gaps are unusable for future items (min size 1..100 unknown,
    // so treat very small gaps as waste) unless they are perfect fits (post_residual == 0).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        score -= 30.0; // perfect fit: reward strongly
    }

    // Reward filling bins deeply (high fill fraction of residual).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current item leaves a large gap in existing bins
    // or no bin fits well. Penalize fresh bin slightly so it's chosen only when it returns lowest score.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If next item is large, a fresh bin is more valuable (keeps big space for big items).
        if next_item_size > 50 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the post-residual exactly accommodates the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if post-residual is nonzero but too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Slight preference for bins below mean residual (balance load) — mild term.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fit
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 15.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are more "loaded";
    // favor them slightly to close bins out.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discard new-bin candidate unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * item_size as f64;
        if item_size > bin_capacity / 2 && (fitting_bins_count == 0 || post_residual < 15) {
            score -= 45.0;
        }
    }

    // Dead-space penalty: tiny post-residuals that can't hold min-size items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual dominates, but boost small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, higher = tighter
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to host a future item (items >= 1 here,
    // but small residuals below typical item sizes are likely unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is pure waste
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use this residual: penalize proportionally to wasted space
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // New-bin candidate handling: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; shrinks when many bins are open and residuals are fragmented.
        let mut penalty = 55.0;
        if open_bins_count > 0 {
            let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            penalty -= 35.0 * frag; // fragmented residuals -> new bin more acceptable
        }
        if next_item_size > 0 && next_item_size >= item_size {
            penalty += 10.0; // large follow-up item benefits from fresh capacity
        }
        score += penalty;
    }

    // Time horizon: early in the stream, be conservative (fewer bins), later allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * fit_ratio; // tighter fits matter more early on
    score += 5.0 * progress * (open_bins_count as f64).ln().max(0.0); // late: tolerate spreading

    // Global residual alignment: prefer bins whose residual is close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let x = pr / c; // normalized post residual

    // Smooth polynomial coupling of post-residual with stream progress:
    // early in the stream, prefer filling bins tightly (penalize large residuals),
    // later, tolerate moderate residuals to keep flexibility.
    let progress_weight = 0.35 * t * (1.0 - t); // zero at ends, peak mid-stream
    score -= progress_weight * (x - x * x) * c;

    // Non-linear dead-space penalty: residuals too small to be useful later.
    let dead = ((pr - next_item_size as f64).max(0.0) / c).powi(2);
    score += 0.5 * dead * c;

    // Reward near-perfect fits with smooth quadratic term.
    score -= 0.4 * (1.0 - x) * (1.0 - x) * (item_size as f64 / c);

    // Last-chance bonus (smoothly scaled).
    if fitting_bins_count == 1 {
        score -= 0.6 * (1.0 + t);
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 0.05 * (open_bins_count as f64) * x * x;

    // Prefer bins whose residual deviates smoothly from the mean (balance).
    score += 0.1 * ((pr - mean_residual) / c).abs();

    // New-bin candidate: keep it neutral-slightly high unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.3 * (pr / c) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in lower "harmonics"
    // (small post_residual is fine, mid-range residuals are the worst waste).
    let pr = post_residual;
    if pr > 0 {
        if pr <= 10 {
            score -= 25.0; // near-perfect fit
        } else if pr <= 25 {
            score += 8.0; // awkward dead zone
        } else if pr <= 50 {
            score += 3.0; // moderately reusable
        } else {
            score -= 5.0; // large residual still flexible
        }
    } else {
        score -= 60.0; // perfect closure
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 15.0 + 0.05 * (next_item_size as f64);
    } else if next_item_size > 0 {
        score += 6.0; // cannot chain the next item here
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer tighter bins when many bins are open (fragmentation control).
    score += 0.15 * (open_bins_count as f64) * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    // Pull toward mean residual: bins close to the mean are interchangeable,
    // prefer filling below-mean-residual bins first.
    score -= 0.2 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when current item leaves huge waste
    // in every existing bin (post_residual very small relative to capacity
    // means good fit, so new bin should rarely win).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open new bin
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < 25 {
        // small gap: risky, may become dead space unless next item fits
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // lookahead item fits perfectly into the gap
        } else {
            score += 18.0;
        }
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // healthy residual: mild reward scaled by how much was consumed
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // gap remains usable for the next item
        }
    }

    // Exact-fit bonus: residual equals a plausible next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 2.5 * open_bins_count as f64;

    // Penalize bins whose residual deviates badly from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate logic: an empty bin is only attractive when the
    // current fit is poor or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < 10.0 || fitting_bins_count <= 1;
        if poor_fit {
            score -= 45.0; // allow opening a fresh bin for a bad landscape
        } else {
            score += 55.0; // prefer reusing existing bins on decent fits
        }
    }

    // Late in the stream, consolidate harder to avoid leftover near-empty bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: next item fills post_residual perfectly -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 60.0;
        if slack == 0 {
            score -= 80.0; // perfect two-item packing
        } else {
            score += slack as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space creation.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize small, unusable post_residual (dead space).
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be slightly more willing to open new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - post / cap; // 1.0 = perfect fill
    score -= 2.5 * tightness * tightness * cap * 0.1;

    // Lookahead: if the next item exactly fits the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let next_fit_quality = 1.0 - (post - nxt) / cap;
            score -= 3.0 * next_fit_quality;
        } else {
            // Post-residual too small for next item: penalize dead space more when residual is tiny.
            if post < 10.0 {
                score += 6.0 * (10.0 - post);
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a reasonable fit (post_residual too small to be reusable).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap - item + 4.0;
        // If the stream is early or bins are scarce, opening a bin is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
        // If many open bins are congested (low mean residual), new bin is attractive.
        score -= 0.05 * (cap - mean_residual).max(0.0);
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size as f64 > 0.6 * cap {
            score -= 5.0;
        }
    }

    // Mild penalty for leaving awkward mid-range residuals that few items fit.
    if post > 0.0 && post < 20.0 {
        score += 3.0 * (20.0 - post) / 20.0;
    }

    // Slight preference for balancing residuals toward the mean (spread load).
    score += 0.02 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear dead-space penalty: quadratic growth of waste potential.
    score += 0.004 * pr * pr / cap;

    // Smooth coupling: waste matters more as the stream progresses.
    score += 0.02 * pr * progress * (pr / cap);

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 2.0 * (1.0 - slack / cap);
            // Perfect chain fit bonus (next item exactly fills what remains).
            score -= 3.0 * (1.0 - (slack / cap).abs().min(1.0));
        } else {
            // Residual too small for lookahead: dead-space risk grows non-linearly.
            score += 1.5 * (nxt - pr) / cap + 2.0 * ((nxt - pr) / cap).powi(2);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when open bins exist, scaled by progress.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 5.0 + 6.0 * progress + 0.3 * open;
        // But if the item is large relative to mean residual, opening is less bad.
        score -= 3.0 * (item / cap) * (mean_residual / cap).max(0.0);
    } else {
        // Slight preference for bins below mean residual (balance residuals).
        score += 0.5 * ((pr - mean_residual) / cap);
    }

    // Fragmentation guard: residuals that are too small to fit anything useful.
    let min_item = 1.0f64;
    if pr > 0.0 && pr < min_item {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: classify leftover space into
    // capacity fractions. Residuals in (0, 10] are dead space; residuals that
    // are exact capacity fractions (25, 50, 75, 100) are reusable "harmonics".
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional class of post_residual: 0 = tiny (dead), 1..4 = quarter classes.
    let quarter = bin_capacity / 4;
    let class = (post_residual + quarter / 2) / quarter; // 0..4 rounded class

    // Penalize dead space superlinearly below the smallest item size.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward residuals that are exact harmonic fractions of capacity
    // (25/50/75/100) — these accept future items cleanly.
    let harmonics = [bin_capacity / 4, bin_capacity / 2, 3 * bin_capacity / 4, bin_capacity];
    if harmonics.contains(&post_residual) {
        score -= 25.0;
    }

    // Modulo-based granularity: residuals divisible by common item sizes
    // (10,20,25,50) are more likely reusable.
    let div_bonus = [10u32, 20, 25, 50]
        .iter()
        .filter(|&&d| d > 0 && post_residual % d == 0 && post_residual > 0)
        .count() as f64;
    score -= div_bonus * 4.0;

    // Integer-division threshold: post_residual in the same "decade class"
    // as next_item_size means the next item likely fits the leftover.
    if next_item_size > 0 {
        let next_decade = next_item_size / 10;
        let post_decade = post_residual / 10;
        if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills.
            let fill_ratio = next_item_size as f64 / post.max(1.0);
            score -= 12.0 * fill_ratio;
            if next_decade == post_decade {
                score -= 6.0; // near-perfect follow-up
            }
        } else {
            // Next item cannot use this bin's leftover: penalize small leftovers
            // harder (wasted capacity), scaled by stream progression.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += (next_item_size - post_residual) as f64 * (0.15 + 0.25 * progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well; make the
    // empty bin moderately expensive so we prefer reusing open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * (1.0 - progress);
        // But if mean residual across open bins is small (all bins tight),
        // opening fresh is fine: reduce the penalty.
        score -= (mean_residual / cap_f).min(1.0) * 10.0;
    }

    // Mild tie-breaker: prefer bins whose residual is far below the mean
    // (consolidate fullness) early in the stream.
    let residual_gap = mean_residual - (bin_residual as f64);
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += residual_gap * (0.10 - 0.08 * progress);

    // Penalize very large leftovers that fall in awkward classes (class 3,
    // i.e., residual just above 3/4 capacity but not harmonic) — hard to fill.
    if class == 3 && !harmonics.contains(&post_residual) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that no plausible item (>=1) can use is pure waste, but tiny
    // gaps (1..=5) are nearly unusable too — punish them harder than mid gaps.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 5 {
        score += 400.0; // dead space: worse than leaving a medium gap
    } else if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead):
    // if the next item can't use this leftover, the gap is likely dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward residuals that can host the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Open-bin pressure: discourage opening new bins when reuse is viable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (open_bins_count as f64 * (2.0 + 3.0 * progress));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 120.0;
    }

    // Mild preference for bins already below mean residual (tighter bins first).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly/well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize proportionally to overshoot
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
        // perfect chain bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0 * fit_ratio;
    }

    // Relative to mean residual: bins below mean residual are more "used up", favor them
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.35 && next_item_size > 0 && post_residual < next_item_size;
        if bad_fit {
            score -= 20.0; // allow opening fresh bin for large item with poor fit
        } else {
            score += 45.0; // default: prefer existing bins
        }
    }

    // Mild pressure toward consolidation as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: post_residual penalized more strongly as stream progresses
    let pr = post_residual as f64 / bin_capacity as f64;
    score += (pr * pr) * (1.0 + 2.0 * progress) * (bin_capacity as f64);

    // Reward tight fits smoothly (small post_residual gets extra discount)
    score -= (1.0 - pr) * (1.0 - pr) * item_size as f64;

    // Penalize bins whose residual deviates from mean residual (non-linear)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 20.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += (gap / bin_capacity as f64) * (gap / bin_capacity as f64) * 10.0;
        if post_residual as u64 >= next_item_size as u64 {
            score -= 5.0;
        }
    }

    // Mild penalty for proliferation of open bins, growing with progress
    score += (open_bins_count as f64).ln() * 2.0 * (0.3 + progress);

    // New-bin candidate: neutral-ish baseline that loses only when fits are good
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress + 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: perfectly full (best possible outcome).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows superlinearly for small residuals that
        // cannot host even the smallest plausible item (harmonic class of 10).
        if post_residual < 10 {
            score += 60.0;
        } else {
            // Modulo-based usability: residuals that are multiples of common
            // size classes (10, 20, 25, 50) are more likely to be reused.
            let r = post_residual;
            let mut bonus = 0.0;
            if r % 10 == 0 { bonus += 8.0; }
            if r % 20 == 0 { bonus += 5.0; }
            if r % 25 == 0 { bonus += 4.0; }
            if r % 50 == 0 { bonus += 6.0; }
            score -= bonus;

            // Integer-division threshold: how many "mid-size chunks" fit later
            let chunks = r / 25;
            score -= chunks as f64 * 2.0;
        }
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // next item fits in this bin only if we place current item here
            score += 3.0;
        }
        // Harmonic class match between next item and post residual
        if post_residual > 0 && next_item_size % 10 == 0 && post_residual % (next_item_size.max(1)) == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current bin
    // would leave terrible dead space and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly, more early in the stream
        score += 30.0 + 20.0 * (1.0 - progress);
        // But if the current placement would strand a tiny residual and
        // the next item is large, opening a fresh bin is attractive.
        if post_residual < 10 && next_item_size > 60 {
            score -= 45.0;
        }
        // If mean residual across open bins is small (bins nearly full),
        // a new bin is more justified.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Small noise-free harmonic tiebreaker on residual mod 7
    score += (post_residual % 7) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual capacity.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by a tiny dead gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual deviates favorably.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: keep it attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (small post residual)
    let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fit_quality * fit_quality;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        let match_quality = 1.0 - (gap as f64) / (bin_capacity as f64);
        score -= 18.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the next item (dead space)
        score += 8.0;
    }

    // Penalize deviation from mean residual (prefer balanced bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Late in the stream, tighten packing (avoid opening new bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate: penalize slightly so it is only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized time horizon and fit quality
    let t = step_index as f64 / (total_items.max(1) as f64);
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits (waste-aware): penalize post_residual with a dead-space curve
    let waste_penalty = (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;
    score += waste_penalty;

    // Reward using most of the bin (high fit_ratio)
    score -= fit_ratio * 20.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if post-residual is too small for the next item,
    // penalize creating unusable slivers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 12.0; // tiny dead space, hard to fill later
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 8.0;
        }
    }

    // New-bin candidate handling: empty bins get a moderate default score so we
    // only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, or when many bins are open, discourage proliferation
        score += t * 10.0 + (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Global state coupling: if mean residual across open bins is large,
    // prefer consolidating into bins with residual near mean (avoid outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - t);

    // Early stream: slightly favor keeping residuals balanced
    if t < 0.3 {
        score -= (bin_residual as f64 - mean_residual) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth coupling: later in the stream, tighten more aggressively
    let tightness = 1.0 + 1.2 * progress * (1.0 - pr_norm);
    score *= tightness;

    // Dead-space penalty: small unusable residuals are bad; smooth quadratic bump
    let dead = (cap * 0.5 - pr).abs() / cap;
    score += 8.0 * dead * dead * pr_norm;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Scarcity pressure: few fitting bins -> prefer reuse over opening new bins
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 6.0 * scarcity;

    // Lookahead: reward residuals that can still host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening bins when open bins fit well
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr).abs();
        score += 10.0 + 5.0 * (1.0 - progress) + mean_gap * 0.1;
    }

    // Mild diversity: avoid concentrating everything in few bins early
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: quantize post_residual into capacity-fraction classes.
    let q = bin_capacity / 4; // 25-unit harmonic quantum
    let class = post_residual / q; // 0..4 integer class
    let phase = (post_residual % q) as f64 / q as f64; // within-class phase

    // Reward small post_residual, but modulate by class:
    // classes 0 (nearly full) are best; class 3 (large residual) penalized.
    score -= (3.0 - class as f64) * 8.0;

    // Phase refinement: prefer residuals that are exact multiples of common
    // item sizes (harmonic alignment) — divisible residuals pair well.
    for &s in &[10u32, 20, 25, 50] {
        if post_residual >= s && post_residual % s == 0 {
            score -= 6.0;
        }
    }

    // Penalize awkward dead space: post_residual in (0, 10) is unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would have fit before, but not after this placement
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are
    // heavily fragmented or item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0
            - 25.0 * fragmentation
            - 10.0 * progress
            - (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Small phase tilt to break ties toward balanced residuals.
    score += phase * 2.0 - 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are wasted space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits but doesn't, penalize leaving a near-miss gap.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 6.0;
    }

    // Last chance: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress * 0.5);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; using it consolidates space.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    }

    // New-bin candidate: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        // Slight bias toward filling existing bins unless they're all fragmented.
        score += 12.0 - (mean_residual - item_size as f64).max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = post_residual as f64 - next_item_size as f64;
        // Perfect match is heavily rewarded; near matches partially.
        if slack == 0.0 {
            score -= 60.0;
        } else {
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Penalize leaving residual that next item overshoots badly relative to mean residual
        if (next_item_size as f64) > post_residual as f64 + mean_residual.max(0.0) * 0.5 {
            score += 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here regardless; penalize wasting this bin's potential
        score += 15.0;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize tiny dead space (< 10) that likely becomes unusable, unless it's near-zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference for filling bins that are already mostly full.
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but penalize dead space
    // that is too small for typical items (1..100).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 90.0 } else { 0.0 };
        score += dead;
    } else {
        score -= 40.0; // perfect fit reward
    }

    // Lookahead: reward residual that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0) * 0.4;
            if post_residual == next_item_size {
                score -= 30.0; // chain fit
            }
        } else {
            score += 8.0; // residual too small for next item
        }
    } else {
        // Last item: prefer closing bins completely.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation (prefer fuller bins).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= pressure * 1.5;

    // Time horizon: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.3;

    // Mean residual coupling: if mean residual is small, avoid wasting this bin.
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 6.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            // Open bins exist that fit; new bin is worse unless post_residual
            // of this empty bin beats typical open-bin outcomes (rare for big items).
            score += 45.0 - (item_size as f64) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;

    // Tightness of fit: fraction of bin consumed by this item
    let fit_ratio = item_size as f64 / capacity;
    let tightness = 1.0 - (post_residual as f64 / capacity);
    // Smooth non-linear reward for tight fits (cubic coupling)
    score -= 12.0 * tightness * tightness * tightness * (0.5 + 0.5 * fit_ratio);

    // Penalize dead space that is too small to be useful later:
    // smooth trough around half-capacity residual via quadratic deviation
    let half = 0.5 * capacity;
    let dev = (post_residual as f64 - half) / capacity;
    score += 6.0 * dev * dev;

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Prefer bins with below-mean residual early, above-mean later (smooth coupling)
    let mean_dev = (bin_residual as f64 - mean_residual) / capacity;
    score += mean_dev * (2.0 + 6.0 * progress_sq);

    // Lookahead: if next item fits exactly into post_residual, reward; if post_residual
    // is smaller than next item but nonzero, mildly penalize stranded space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 15.0;
        } else if (post_residual as f64) < nxt && post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // New-bin candidate: neutral-ish baseline; slightly discourage early in stream
    // when many bins could fit, encourage late when fragmentation is high
    if bin_residual == bin_capacity {
        let frag = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 8.0 * (1.0 - progress) - 10.0 * frag * (0.3 + 0.7 * progress);
    }

    // Mild penalty for bin proliferation
    score += 0.15 * open_bins_count as f64 * progress_sq;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small sizes) are rewarded.
    let r = post_residual;
    if r > 0 {
        // perfect fit: huge reward
        if r == 0 {
            score -= 1000.0;
        }
        // leftover exactly reusable by common small item sizes
        if r % 10 == 0 {
            score -= 6.0;
        } else if r % 5 == 0 {
            score -= 3.0;
        }
        // integer-division thresholds: leftover that can host mid/large items
        if r >= 50 {
            score -= 8.0;
        } else if r >= 30 {
            score -= 4.0;
        } else if r >= 20 {
            score -= 2.0;
        } else {
            // tiny dead space penalty, scaled by how dead it is
            score += (10.0 - r as f64) * 0.6;
        }
    } else {
        // perfect fit
        score -= 1000.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: penalize leaving residual that cannot host the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.1;
        } else if post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit is poor everywhere.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so we prefer existing bins unless they're bad
        score += 9.0;
        score -= crowding * 1.5;
        score -= progress * 3.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 5.0; // an empty bin guarantees hosting the next item too
        }
    }

    // Slight preference to consolidate into emptier bins when many are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64) * 0.15;

    // Mild noise-free tie-break via harmonic class of residual
    score += ((r as f64 * 0.6180339887) % 1.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Dead space relative to the next item's needs.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins; opening new bins
    // (full residual) is penalized when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Slight preference for bins tighter than the mean residual (good packing).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more conservative: penalize leaving large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
