pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: post_residual that cannot fit even the smallest item.
    if post_residual < 1 {
        score -= 100.0; // perfect fill, extremely desirable
    } else if post_residual > bin_capacity / 2 {
        score += 10.0; // wasteful placement leaving big gap
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to leftover uselessness
            score += (post_residual as f64) * 0.2;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened casually
        score += 45.0;
        // but if existing bins are all poor fits (high mean residual mismatch), ease opening
        let avg_waste = mean_residual - item_size as f64;
        if avg_waste < 0.0 {
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // many open bins: discourage more
        score += open_bins_count as f64 * 1.5;
    } else {
        // using an existing bin reduces open-bin pressure slightly
        score -= open_bins_count as f64 * 0.3;
        // favor bins whose residual is close to mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Mild time-horizon coupling: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post_norm * post_norm * (1.0 - progress) + post_norm * progress * (2.0 - progress);
    score += 40.0 * poly;

    // Tight fit reward, amplified late in the stream
    let tightness = 1.0 - post_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    let dead = (post - mean_residual) / cap;
    score += 15.0 * dead * dead.abs();

    // Last-chance bonus when few bins can fit the item
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - post_norm);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 10.0 * (1.0 - ((post - nxt) / cap).abs());
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across too many open bins early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" residue classes get rewarded, dead-space classes penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes (0..=10)
    let class_bonus: f64 = match class {
        0 => 60.0,              // perfect / near-perfect fit: strongly reward
        1 => 25.0,              // small leftover, still usable by tiny items
        2 => 5.0,
        3 => 0.0,
        4 => -8.0,              // awkward mid-range dead space
        5 => -15.0,             // ~50 leftover: classic dead zone
        6 => -10.0,
        7 => 8.0,               // large residual: bin still flexible
        8 => 18.0,
        9 => 28.0,
        _ => 35.0,              // nearly empty bin
    };
    score -= class_bonus;

    // Modulo-10 harmonics: leftover divisible by 10 pairs well with
    // decile-sized items; leftover ≡ item-like residues waste less.
    if pr % 10 == 0 {
        score -= 12.0;
    }
    // Penalize leftovers that no plausible item (1..=100) can use finely:
    // residue classes 1..3 are nearly unusable.
    let r = pr % 10;
    if pr > 0 && r <= 3 {
        score += 10.0 - 3.0 * r as f64;
    }

    // Lookahead coupling: reward leaving exactly room for next item,
    // penalize leaving almost-room (blocking the next placement).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr as f64) - ni;
        if gap == 0.0 {
            score -= 45.0; // perfect chaining
        } else if gap > 0.0 && gap <= 10.0 {
            score -= 20.0; // next item fits comfortably
        } else if gap < 0.0 && gap > -10.0 {
            score += 25.0; // barely blocks next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large or open bins are crowded/fragmented.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        let big_item = (item_size as f64) / cap;
        let early = step_index as f64 / (total_items.max(1) as f64);
        let discount = 30.0 * big_item + 12.0 * pressure.min(3.0) + 15.0 * (1.0 - early);
        score += discount;
        // Fresh bin has pristine post_residual; re-apply fair baseline so it
        // competes honestly with good fits.
        score += 20.0;
    }

    // Mild preference for tighter bins overall (fragmentation control).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Progression drift: later in stream, prefer filling bins more fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += (open_bins_count as f64) * 1.5;

    // If the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits in post_residual, mild reward; if not, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Baseline moderate score; last-chance open bins should beat it.
        score = 45.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild deviation penalty relative to mean residual (balance-aware).
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    // Progression: later in the stream, slightly favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

