    }

    // Penalize large dead space, but only if it can't hold a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else {
            score -= 5.0; // residual still usable by lookahead item
        }
        // Bonus if this placement leaves room exactly for the next item.
        if post_residual == next_item_size {
            score -= 150.0;
