    // late in the stream, accept anything that fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Global residual pressure: if open bins are generally full, prefer
    // spreading items; if mean residual is high, prefer tight fits more.
    if mean_residual > item_size as f64 * 2.0 {
        score += 10.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    if open_bins_count > 5 {
        score -= (open_bins_count.min(20)) as f64 * 0.5;
    }

    // Brand-new empty bin candidate: penalize unless current bin fits are bad
    // (large post_residual waste) or no open bin fits well.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 60.0 - waste * 0.3;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing else fits: new bin is mandatory
        }
    }

    // Mild preference for filling fuller bins (smaller residual) first.
    score += bin_residual as f64 * 0.05;

