}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight fit), scaled by capacity.
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p_norm = post / cap;
    let t = progress;
    // Early in stream: waste is cheap-ish; late in stream: waste is costly.
    let waste_weight = 0.5 + 1.5 * t * t;
    score += waste_weight * p_norm * p_norm;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - p_norm;
    score -= 0.8 * tightness * tightness * (0.3 + 0.7 * t);

    // Penalize bins that leave post_residual below next item size when the
    // next item is large (dead space that likely cannot be reused).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 1.2 * gap * (1.0 + t);
        } else {
            // Smooth reward if next item could still fit into this bin's residue.
            let fit = post / nxt.max(1.0);
            score -= 0.3 * (fit.min(2.0)) * t;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty so best-fit logic dominates.
        score += 0.05 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: if this bin is far below mean residual
    // (relatively empty), mildly deprioritize it; nearly-full bins favored.
    let dev = (post - mean_residual) / cap;
    score += 0.4 * dev * dev - 0.2 * dev;

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // current item's complement; make it costly unless item is large and
    // stream is late (few future chances to fill residue).
    if bin_residual == bin_capacity {
        let new_waste = (cap - item) / cap;
        score = 1.0 + new_waste * (1.6 - 0.8 * t);
        if fitting_bins_count == 0 {
            score -= 2.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into
    // capacity-fraction buckets (1/4, 1/3, 1/2 of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits aggressively (waste close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if pr <= cap * 0.1 {
        score -= 25.0;
    } else if pr <= cap * 0.25 {
        score -= 8.0;
    }

    // Penalize residuals falling into the "useless middle band":
    // too small for typical items (<=10) but too large to call tight.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space: nothing can ever use it
    }

    // Harmonic / modulo logic on post_residual: residuals that are
    // exactly divisible into common item-size classes (multiples of
    // 10 or 5) are more likely to be filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        score += 4.0; // odd residual unlikely to be matched
    }

    // Integer-division thresholds: post_residual divided into capacity
    // quarters; the lowest quarter is premium space.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    score -= (4 - quarter.min(4)) as f64 * 2.0;

    // Lookahead coupling: if the next item fits exactly into the
    // post residual, this is a harmonic pair — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual.
    // Prefer it only when the fit is structurally good (item is large
    // relative to capacity) or existing bins are too crowded/fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Base penalty for opening a new bin (bin count economy).
        score += 18.0;
        // Large items pair well with fresh bins.
        score -= frac * 30.0;
        // If mean residual across open bins is small, open bins are
        // nearly full — a new bin is justified.
        score -= (cap - mean_residual).max(0.0) * 0.2;
        // If no open bin fits comfortably, encourage new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild stream-position adaptation: early in the stream, be more
    // willing to open bins (long horizon to amortize); later, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Slight preference for bins whose residual is far from mean
    // (balance residual distribution across bins).
    score += ((pr - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..30) are mildly wasteful.
    if post_residual >= 10 && post_residual < 30 {
        score += 0.5 * (30.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Next item can't use this bin's remainder: penalize relative gap.
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: fewer open bins preferred; penalize spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (concentrate filling into already-small-residual bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere;
    // base penalty keeps it behind decent fits, but empty bin has full residual.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
    }

    // Late-stream urgency: as stream nears end, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let diff = (post_residual as f64 - next_f).abs();
        // Perfect 2-chain match: strong reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item still fits after this placement: reward closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            score += 0.5 * (next_f - post_residual as f64);
        }
    }

    // Reward tight fits (small post_residual), especially early/mid stream
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Penalize post_residual far above mean residual (wasteful placement)
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: encourage consolidating into existing bins, avoid spreading
    if open_bins_count > 3 {
        score -= 2.0 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 45.0;
        // but if the current item is large and would leave tiny unusable space
        // in any existing bin, opening a fresh bin becomes preferable
        let tight_threshold = 12.0;
        if post_residual as f64 > 0.0 && post_residual < item_size && (post_residual as f64) < tight_threshold {
            score -= 60.0;
        }
        // early in the stream, opening bins is cheaper
        score -= 20.0 * (1.0 - progress);
        // if next item is large and would fit better in a fresh bin
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > bin_capacity - bin_residual {
            score -= 15.0;
        }
    }

    // Mild late-stream conservatism: squeeze every existing bin harder
    if progress > 0.7 {
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste penalty
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Perfect or near-perfect fit gets a strong discount
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits exactly in the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use leftover space; penalize large leftovers
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins when many bins are open
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * open_bins_count as f64;

    // Time horizon: later in the stream, be more conservative (favor tight fits more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * waste;

    // Global residual pressure: if mean residual is small, keep bins tight
    score += 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if item is huge and no bin is tight, new bin is okay
        if item_size > bin_capacity * 3 / 4 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && waste > 0.5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (good fit), with non-linear sharpening
    let mut score = x.powf(1.6) * cap;

    // Smooth interaction: good fits matter more as stream progresses
    let fit_reward = (1.0 - x).powf(2.5) * (1.0 + progress) * 30.0;
    score -= fit_reward;

    // Penalize dead space that can't hold typical items: smooth coupling with progress
    let dead = (x * cap - 10.0).max(0.0) / cap;
    score += dead * dead * cap * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - x) + 10.0 * progress;
    }

    // Crowding pressure: when many bins open, prefer filling existing ones
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * x * 8.0;

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = (x - nx).max(0.0) * (1.0 - (x - nx)).max(0.0);
        score -= compat * 20.0;
        // penalize leaving exactly awkward slivers
        let sliver = (x - nx).max(0.0);
        score += sliver * sliver * 5.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized early, allowed late
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) + crowding * 2.0;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into
    // "useful" residue classes (small, reusable sizes) are preferred.
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Reward residuals that are multiples of common small sizes (harmonic classes)
    for d in [10i64, 20, 25, 50] {
        if pr > 0 && pr % d == 0 {
            score -= 8.0 + d as f64 / 10.0;
        }
    }

    // Penalize awkward dead space: nonzero residuals in awkward bands
    if pr > 0 && pr < 10 {
        score += 15.0; // unusable sliver
    }

    // If the lookahead item fits exactly into post_residual, strongly favor
    if nis > 0 && nis == pr {
        score -= 300.0;
    } else if nis > 0 && nis < pr {
        // reward leaving room for next item, scaled by how well it fits
        let slack = (pr - nis) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if nis > 0 && nis > pr && pr > 0 {
        // next item won't fit here; penalize slightly if we create tight space
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 60.0 - 40.0 * progress - pressure.min(50.0);
    }

    // Late in the stream, tighten packing: prefer smaller post_residual more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space that cannot fit even the smallest plausible item is wasted.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        }
        // Quadratic penalty on tight leftovers to prefer near-perfect fits.
        score += 0.15 * (post_residual as f64) * (post_residual as f64) / 10.0;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 + 2.0 * progress);

    // New-bin candidate handling: allow opening a fresh bin when open bins
    // would leave large dead space, but bias against it early/mid stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress);
        // If the next item would fit the leftover of this placement, opening
        // a new bin is unattractive.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 30.0;
        }
    } else {
        // Lookahead: reward placements whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Prefer bins below the mean residual (keeps residuals balanced).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match within small tolerance.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 5.0 {
            score -= 25.0 - 4.0 * diff;
        }
        // Penalize residuals that cannot host the next item (dead space risk).
        if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Reward residuals below the mean residual (tight packing), penalize above.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (dead space < 10 is useless),
    // reward dead space that could still hold medium items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 {
        score -= 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // If next item exactly fills post residual, big bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly; the penalty shrinks when mean residual is low
        // (open bins nearly full) or stream is late.
        score += 18.0 - 25.0 * (1.0 - crowded) - 10.0 * progress;
        // If many open bins can fit, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 4 {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Mild penalty for wasting a large bin residual on a small item.
    if item_size < 30 && bin_residual > 70 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= poly * cap * (0.4 + 0.6 * progress);

    // Penalize large dead space late in the stream (quadratic in progress)
    score += norm_pr * norm_pr * cap * progress * 0.5;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_item) * (1.0 - norm_item) * 10.0 * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward residual that can fit next item, smoothly
    if next_item_size > 0 {
        let fits_next = (norm_next <= norm_pr) as i32 as f64;
        let slack = (norm_pr - norm_next).max(0.0);
        score -= fits_next * (6.0 + 8.0 * slack) * (1.0 - progress);
        score += (1.0 - fits_next) * norm_next * cap * 0.15;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) + 3.0 * progress;
    }

    // Coupling with mean residual: prefer bins near the mean to balance load
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes (10,20,25,50)
    // are more reusable; penalize awkward residues.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 {
        score -= 12.0; // harmonically reusable residual
    } else if pr < 10 {
        score += 25.0; // dead space below minimum item size
    } else if pr < 20 {
        score += 10.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item's class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here too; reward, scaled by tightness of the pair
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - 0.15 * slack;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 8.0; // exact divisor: excellent packing
            }
        } else {
            // next item cannot follow here; mild penalty for stranding residual
            score += 6.0 + 0.1 * (pr as f64);
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin residual is awkwardly small
    // or no good fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 * 0.4;
        // reward new bin if mean residual is small (open bins nearly full)
        score = 40.0 + open_pressure - 20.0 * (mean_residual / bin_capacity as f64) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big item coming, fresh bin useful
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor)
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    // Late-stream consolidation: favor filling existing bins harder near the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64).recip().min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small unusable gaps (< 10, since min item size is 1... use small threshold)
        if post_residual < 5 {
            score += 60.0;
        } else if post_residual < 15 {
            score += 25.0;
        }
        // Reward leaving gaps that can still fit typical items
        score -= (post_residual as f64).sqrt() * 3.0;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer existing bins when many are open
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New bin candidate: penalize slightly so only chosen when fits are poor
        score += 30.0;
        // Early in stream, opening bins is cheaper
        score -= (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills this bin afterwards.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item can fit into the post residual: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.3 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }
    // Post residual is small but nonzero and unusable by next item: dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + (next_item_size - post_residual) as f64;
    }

    // Prefer tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in stream: encourage filling bins tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would leave tiny waste.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0; // fresh bin perfect for the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to hold future items (typical min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // Penalize leaving a residual just below the next item's size (blocked space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer
    // consolidating into bins below the mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger post-residual
    // slightly more); late in the stream, prioritize closing bins out (any fit is fine).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (many fitting bins means we should reuse).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // must open a bin anyway
        } else if fitting_bins_count == 1 {
            score += 30.0; // a fitting open bin exists; strongly prefer reuse
        } else {
            score += 18.0 + 2.0 * (fitting_bins_count.min(10) as f64);
        }
        // Late stream: prefer reusing open bins even more.
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let prn = pr / cap;

    // Smooth polynomial coupling: base cost from post-residual, warped by progress.
    let mut score = prn * (1.0 + 0.6 * progress * progress);

    // Penalize tiny unusable residues smoothly (quartic bump near zero).
    let dead = (1.0 - prn).max(0.0);
    score += 12.0 * dead * dead * dead * dead * prn;

    // Reward tight fits: coupling of fit ratio with post-residual.
    score -= 6.0 * fit * fit * (1.0 - prn);

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - prn) * (1.0 - prn);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins relative to mean residual state.
    score += 0.02 * open_bins_count as f64 * prn;
    score -= 1.5 * (mean_residual / cap - prn).abs();

    // New-bin candidate: neutral-ish, slightly discouraged when tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * (1.0 - fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: how "reusable" is the leftover space? ---
    // Residuals divisible by 10 pair well with the 10..80 item range; reward them.
    let post = post_residual;
    if post == 0 {
        // Perfect fit: best possible outcome.
        score -= 1000.0;
    } else {
        let class = post % 10;
        // Reward residuals that are "harmonic" (multiples of 10) with small remainder.
        score -= match class {
            0 => 30.0,
            1 | 9 => 10.0,
            2 | 8 => 6.0,
            3 | 7 => 3.0,
            _ => 0.0,
        };
        // Penalize tiny dead space (post_residual in 1..10) heavily: unusable sliver.
        if post < 10 {
            score += 25.0;
        }
        // Integer-division thresholds: leftover >= 50 keeps room for half-capacity items.
        if post >= 50 {
            score -= 12.0;
        } else if post >= 30 {
            score -= 5.0;
        }
    }

    // --- Lookahead coupling: does post_residual still fit the next item? ---
    if next_item_size > 0 {
        if post >= next_item_size {
            // Chain-friendly: this bin can also host the next item.
            score -= 15.0;
            // Extra reward if it fits the next item snugly (harmonic pairing).
            let gap = post - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        } else if post > 0 && post < next_item_size {
            // Bin becomes useless for the next item; penalize proportional to waste.
            score += (next_item_size - post) as f64 * 0.5;
        }
    } else {
        // Last item: only the immediate fit matters; push toward tightest packing.
        score -= 20.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one. ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // --- New-bin candidate handling: empty bin should lose unless nothing fits well. ---
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a decent fit, but below a bad fit.
        score = bin_capacity as f64 * 0.9;
        // Late in the stream, prefer reusing open bins to avoid stranded leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many open bins already exist, discourage opening yet another.
        score += open_bins_count as f64 * 2.0;
        // Exception: if the item is huge relative to typical residual, a fresh bin is fine.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // --- Mean-residual context: if this bin is far below average residual, using it
    //     balances the bin population (keeps many medium bins alive). ---
    let diff = mean_residual - post as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // --- Modulo harmonic on item_size itself: items near multiples of 25 like
    //     bins whose residual is also near a multiple of 25. ---
    let item_class = item_size % 25;
    let res_class = bin_residual % 25;
    if item_class == res_class {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the real enemy.
    // A residual that is too small for the minimum plausible item (<= ~12)
    // is nearly unusable dead space -> heavy penalty.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Danger zone: only fits very small items.
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual > 50 {
        // Large residual is flexible; reward keeping big gaps open.
        score -= 10.0;
    }

    // Perfect-ish fits are gold: reward very tight placements.
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits but not quite, slight penalty for stranding it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open;
    // encourage consolidation when open bins are few.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 15.0 + pressure * 2.0;
    } else {
        // Reward reusing existing bins, scaled by how full they already are.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 + 15.0 * fill;
    }

    // Nudge toward bins whose residual is below the mean (tighter bins first),
    // leaving larger residuals available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space quadratically
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
            if gap == 0.0 {
                score -= 200.0; // perfect chain fit
            }
        } else {
            // next item cannot follow in this bin: penalize proportionally
            let deficit = (next_item_size - post_residual) as f64;
            score += 15.0 + deficit / (bin_capacity as f64) * 30.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Prefer denser packing early in the stream; allow new bins later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax as stream progresses
        score += 60.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that nothing can fill (min item size 1..100 unknown; use 10 as reference).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last chance: this is the only bin that fits -> strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: only attractive if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If current bin would leave a large gap, opening new bin is fine.
        let waste_here = post_residual as f64;
        if waste_here > 40.0 {
            score -= 12.0;
        }
        // Lookahead: if next item could combine with current item's leftover, favor open bins.
        if next_item_size > 0 && (next_item_size as f64) <= waste_here {
            score += 10.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Lookahead coupling for open bins: leftover after placing should complement next item.
    if bin_residual != bin_capacity && next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 6.0; // leftover can host next item
        } else if post_residual > 0 {
            score += 4.0 * (nr - post_residual as f64) / nr;
        }
    }

    // Global state: when mean residual is high, prefer filling fuller bins (best-fit bias).
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Mild preference to use bins with lower residual overall (pack tightly).
    score += 0.02 * bin_residual as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 30.0 * norm_item * norm_pr * (1.0 - progress);

    // Stream-progress coupling: early stream, prefer tight fits less aggressively
    let progress_coupling = (progress - 0.5) * (progress - 0.5) * 4.0; // 0..1 parabola
    score += progress_coupling * norm_pr * 25.0;

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr as f64 - mean_residual).abs();

    // Last-chance bonus: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits into the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 20.0 + 25.0 * fit_quality * (1.0 - progress);
        } else {
            // next item won't fit; penalize proportionally to overflow
            score += 10.0 * ((nxt - pr) / cap);
        }
    }

    // Mild pressure against hoarding many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // New-bin candidate handling: neutral-ish baseline, slightly favored early
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 30.0 * (1.0 - progress) + 20.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is.
    // Residuals divisible by small size classes are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual in {0} -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: post_residual divisible by 10 (harmonic decade class) -> reusable by typical items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }

    // Class 3: post_residual divisible by 5 -> moderately reusable.
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 8.0;
    }

    // Dead-space penalty: small odd residuals (1..9) are near-unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Harmonic lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        if post_residual % next_item_size == 0 {
            score -= 15.0; // exact harmonic division
        }
    }
    // If next item would leave a tiny residue, penalize.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is huge (harmonic top class), a fresh bin is fine.
        if item_size * 5 >= bin_capacity {
            score -= 55.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer tighter bins: reward low residual relative to capacity.
    score -= (1.0 - pr / cap) * 10.0;

    // Spread-awareness: if this bin is much tighter than average, favor it.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space: heavy penalty.
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Last chance bin before opening a new one: reward to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills.
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: baseline slightly above good fits, below bad fits.
        score = 45.0 + open_bins_count as f64 * 0.2;
        // Encourage new bin when lookahead won't fit well anywhere anyway.
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Early stream: slight preference to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more dead space afterwards: mild reward,
            // scaled by how tightly it fits.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 200.0 * tightness;
        } else {
            // Next item does NOT fit into the leftover: penalize leaving a gap
            // that is useless for the immediate future.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating dead space below the minimum item size (unusable gap).
    // Items are >= 1, but gaps smaller than typical items are hard to reuse;
    // scale penalty by progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Prefer bins with below-average residual (tighter bins get filled first),
    // keeping more slack spread across bins for future items.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Slight inherent reluctance to open a new bin.
        score += 30.0;
        // But if many bins are open with high mean residual, opening fresh is fine.
        if mean_residual > 40.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small dead space.
    score -= 2.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into the post residual,
    // penalize otherwise (chained placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus for near-perfect chain: post residual close to next item.
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the item is large and bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0;
        score -= 10.0 * progress;
        // If the item is big, a fresh bin is more attractive.
        score -= 0.15 * item_size as f64;
        // If open bins are fragmented (mean residual low), opening new bin is ok.
        score -= 0.2 * open_bins_count as f64;
        if fragmentation > 20.0 {
            score -= 10.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room for chaining in fresh bin
        }
    }

    // Prefer filling bins with larger residuals when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild time pressure: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: prefer tight fits, with non-linear (quadratic) waste penalty
    let mut score = pr as f64 + 8.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: waste penalized more as stream progresses (fewer future chances to reuse space)
    score += 30.0 * norm_pr * norm_pr * progress * cap;

    // Interaction between item size and residual: large items into large-residual bins slightly favored
    score -= 10.0 * norm_it * (1.0 - norm_pr) * cap * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving residual that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let d = (pr - nxt).abs();
        score -= 12.0 * (-d / 15.0) * (1.0 + progress);
        // Penalize residual just barely below next item (dead space risk)
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * cap * 0.5;
        }
    }

    // Mild penalty for scattering across many open bins early
    score += (open_bins_count as f64).ln() * 1.5 * (1.0 - progress);

    // Pull toward mean residual to balance bin loads (smooth)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate handling: empty bin gets a moderate default score so it wins
    // only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 10.0 * (1.0 - progress) - 15.0 * (fitting_bins_count == 0) as i32 as f64;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let d = (cap - it - nxt).abs();
            score += 8.0 * (-d / 20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes (10, 20, 25, 50) are "reusable" classes; odd/prime-ish
    // residues are dead space.
    let r = post_residual;
    let reusable = if r == 0 { 3.0 }
        else if r % 50 == 0 { 2.5 }
        else if r % 25 == 0 { 2.0 }
        else if r % 20 == 0 { 1.8 }
        else if r % 10 == 0 { 1.5 }
        else if r % 5 == 0 { 0.8 }
        else { 0.0 };
    score -= reusable;

    // Reward exact fits strongly.
    if r == 0 { score -= 40.0; }

    // Penalize tiny dead space that nothing (min size 1..100) can use well:
    // leftovers in [1..=9] are nearly useless.
    if r > 0 && r < 10 { score += 12.0; }

    // Harmonic pairing: if the NEXT item fits exactly into the post-residual,
    // this is a perfect two-item chain.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if r >= next_item_size {
            // next item still fits, mild reward scaled by leftover after it
            let r2 = r - next_item_size;
            score -= 5.0 + (r2 % 10 == 0) as i32 as f64 * 3.0;
        } else {
            // next item won't fit here; penalize more if this bin would be
            // left with awkward small residue
            score += 3.0 + if r < next_item_size / 2 { 4.0 } else { 0.0 };
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Opening a
    // new bin is only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Neutral baseline; add penalty proportional to open bins so we
        // prefer consolidating into existing bins unless the fit is bad.
        score += 8.0 + open_bins_count as f64 * 0.5;
        // But if the item is large relative to mean residual, new bin is fine
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 { score -= 10.0; }
    }

    // Tight fit reward: item filling most of the bin is good.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    // Slight preference for bins with below-mean residual (compact them first).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Early in the stream, be more willing to open bins (diversity); later,
    // consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    } else {
        score -= 4.0 * progress;
    }

    // Integer-division threshold: residue classes floor(r/10) — small bucket
    // counts (1..=2 tens left) are hard to fill; penalize mildly.
    let tens = r / 10;
    if tens == 1 { score += 2.0; }
    if tens == 2 { score += 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space zone: gaps too small for the smallest plausible item are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless residual is large.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins tighter than average (good fit relative to fleet).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if next item fits the post residual, reward; if it nearly fits, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 5 {
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            // Perfect chain: this placement leaves exactly room for the next item.
            score -= 60.0;
        } else if post > nxt {
            // Next item still fits: reward, stronger the tighter the leftover gap.
            let gap = (post - nxt) / bin_capacity as f64;
            score -= 18.0 * (1.0 - gap);
        } else {
            // Next item won't fit: penalize dead space proportional to the miss.
            score += 0.35 * (nxt - post);
        }
    }

    // ---- last-chance bonus: only this bin can take the item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // ---- tightness relative to mean residual (best-fit flavor) ----
    let diff = mean_residual - post_residual;
    if diff > 0.0 {
        score -= 0.15 * diff.min(40.0);
    }

    // ---- new-bin candidate penalty: prefer reusing open bins ----
    if bin_residual == bin_capacity {
        score += 6.0 + 0.4 * open_bins_count as f64 + 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the next item.
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 10.0 * chain_fit;
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are poor fits relative to the item.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // If open bins are mostly full (low mean residual), a new bin is fine;
        // otherwise penalize it to force using existing capacity.
        score += 25.0 * avg_pressure;
        // Slight time-varying exploration: later in the stream, be more
        // conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * (1.0 - progress);
    }

    // Encourage consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins whose residual deviates favorably from the mean
    // (pick bins that are more full than average).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth cubic interaction: late in the stream, small residuals become costlier.
    score += 40.0 * progress * norm_pr * norm_pr;

    // Reward tight fits: subtract when item fills a large fraction of the residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill * fill * (1.0 + progress);

    // Penalize leaving a residual that no plausible next item can use (dead space coupling).
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (nx - pr).max(0.0) as f64 / cap;
        score += 30.0 * gap * gap;
        // Reward leaving room for the lookahead item.
        let slack = (pr - nx).max(0.0) as f64 / cap;
        score -= 12.0 * slack * (1.0 - slack);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many open bins vs. consolidating near mean residual.
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Slight early-stream bias toward opening new bins to enable better packing later.
    score += 5.0 * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: perfect fits (0), small dead space, half-class, large space.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let pr = post_residual as f64;
        // modulo arithmetic on post_residual: classify dead-space quality
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if post_residual <= 10 {
            score += 25.0; // unusable sliver (items >= 10... but sizes can be 1..100)
            if post_residual < 5 { score += 15.0; }
        } else if post_residual <= quarter {
            score += 5.0; // moderately tight
        } else if post_residual == half as u32 {
            score -= 10.0; // half-class residual is highly reusable
        } else if post_residual > half {
            score -= 8.0; // roomy bin
        }
        // integer division thresholds: post_residual / 10 class
        let class = post_residual / 10;
        score -= (class as f64) * 1.5;

        // modulo-10 harmonic bonus: residuals divisible by 10 align with typical sizes
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // guaranteed perfect follow-up
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when fit is bad and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (item_size as f64 / cap);
        score = 55.0 + fit_quality * 30.0 - progress * 20.0;
        if post_residual >= half { score -= 10.0; } // empty bin is roomy for large items
    }

    // Tie-break: slight preference for bins below mean residual (tighter bins)
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps < 10 are likely trash).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits; residual after that matters
            let r2 = post_residual - next_item_size;
            if r2 < 10 && r2 > 0 {
                score += 4.0; // mild penalty for chaining into a dead gap
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; large post residual wasted for lookahead
            score += post_residual as f64 * 0.15;
        }
    }

    // Pressure on number of open bins: encourage filling existing bins
    // when many are open, but allow new bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    score += bin_pressure * 0.5;

    // Prefer bins with residual below mean (consolidate small gaps).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Last chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.2 + bin_pressure * 0.3;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open a new bin when an existing bin is a last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
