    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly fills the post
    // residual, this placement creates a perfect two-item chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits too: reward tighter combined packing.
            let two_step_waste = post_residual - next_item_size;
            score -= 400.0 - 4.0 * two_step_waste as f64;
        } else {
            // Next item would NOT fit here: penalize leaving residuals that
            // are just barely too small for the next item (dead space trap).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 150.0 + 10.0 * gap as f64;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already tight relative
    // to the fleet average (compact the packing).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid).min(50.0);
    } else {
        score += (resid - mean_residual).min(50.0) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But a new bin is fine if the stream is early and next item is large.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 200.0;
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Mild penalty for fragmenting across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize wasted space
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * (open_bins_count as f64).sqrt();
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if mean_residual > item_size as f64 {
        score -= 8.0;
    }
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time horizon: early stream, keep bins flexible (moderate residual); late, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * fit_ratio * -1.0 + 5.0 * (1.0 - progress) * fit_ratio;

    // Prefer bins whose residual is close to item size (exact packing).
    let waste = (bin_residual - item_size) as f64;
    score += 0.05 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post residual), scaled by capacity.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild preference for tightness; late: strong tightening pressure.
    let w = 0.5 + 1.5 * progress * progress;
    score -= w * (cap - post) * (post / cap);

    // Penalize dead space that grows quadratically when residual is small but not zero.
    let x = post / cap;
    score += 12.0 * x * x * (1.0 - x);

    // Perfect fit reward (post_residual near zero).
    if post == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 8.0 * gap * (1.0 - gap);
        } else {
            // Post residual can't hold next item: penalize proportionally.
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Prefer filling bins with larger residuals relative to mean (balance avoidance of fragmentation).
    score += 0.05 * (post - mean_residual);

    // New-bin candidate handling: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small-residue classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Class by residue size: tiny residues are dead space.
        let cls = pr / 10; // integer division threshold classes: 0..9
        score += cls as f64 * 8.0;
        // Penalize residues that no item (min size 1..100) can plausibly fill:
        // residue < 10 is near-dead.
        if pr < 10 {
            score += 60.0;
        }
    }

    // Lookahead: reward if next item fits into the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 120.0 - (slack as f64).min(120.0);
        } else {
            // next item cannot fit here; slight penalty
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer bins with small residuals relative to mean (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Slight preference for reusing existing bins over opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, post_residual large).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
    }

    // Progression coupling: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small for the minimum item size are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Pressure against proliferating open bins: prefer tighter bins when many are open.
    score += (open_bins_count as f64) * 0.35 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual fullness (keep residuals balanced).
    score += 0.10 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this is a last-chance situation and residual is large).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 1 {
            score -= 10.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that close exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that matches the next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 200.0; // exact match: next item closes this bin
        } else if post_residual as f64 > next {
            // next item fits but leaves another residual; mild penalty proportional to leftover
            score -= 40.0 - diff.min(40.0);
        } else {
            // next item cannot use the residual: penalize dead space growth
            score += (next - post_residual as f64) * 0.5;
        }

        // Bonus if next item could combine into a near-closed bin
        if post_residual as f64 >= next && (post_residual as f64 - next) <= 10.0 {
            score -= 15.0;
        }
    }

    // Penalize residuals far above the mean residual (wasteful large holes).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize unless item is big (little dead space risk elsewhere)
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        let poor_fit_everywhere = fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 30);
        if large_item || poor_fit_everywhere {
            score -= 30.0;
        } else {
            score += 60.0;
        }
    }

    // Late in the stream: prefer tighter packing (closing bins) to reduce total count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - pr / bin_capacity as f64);

    // Slight preference for bins with larger current residual when many bins open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are wasted capacity
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        score -= 1.5 * (1.0 - next_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize leaving a residual that strands the next item
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Perfect-fill bonus: exact fit is ideal.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Prefer fuller bins relative to the fleet average residual.
    if (bin_residual as f64) >= mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
        // If next item is large and this item is small, fresh bin may pair better.
        if next_item_size > item_size * 2 {
            score -= 4.0;
        }
    }

    // Mild penalty for proliferating open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), with non-linear emphasis.
    let mut score = post * (1.0 + 0.8 * (post / cap) * (post / cap));

    // Reward near-perfect fits smoothly via quadratic coupling.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize opening a new bin when open bins exist and could fit,
    // especially early/mid stream; smooth in progress.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let waste = if open > 0.0 { mean_residual / open } else { 0.0 };
        score += 18.0 * (1.0 - 0.5 * progress) + 0.15 * open;
        // New bin is attractive if existing residuals are badly fragmented
        // (high mean residual relative to item) — smooth non-linear term.
        score -= 0.10 * waste * (waste / cap) * (1.0 + progress);
    }

    // Lookahead (k=2): if the next item fits exactly in the post-residual,
    // reward this placement; if next item would be stranded by a large
    // leftover, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
        if nxt > post && post > 0.0 {
            score += 6.0 * (1.0 - progress) * (post / cap);
        }
    }

    // Mild fragmentation penalty for leaving awkward mid-range residuals,
    // coupled non-linearly with stream progress.
    let mid = (post / cap - 0.35).abs();
    score += 8.0 * (1.0 - mid * mid) * (0.3 + 0.7 * progress) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality via integer division
    let pr = post_residual as u32;
    let class = pr / 10; // 0..=10 harmonic class
    // Small classes (near-perfect fit) are heavily rewarded
    score -= (10 - class.min(10)) as f64 * 6.0;
    // Extra hard reward for exact / tiny leftovers
    if pr == 0 { score -= 60.0; }
    else if pr <= 5 { score -= 25.0; }
    else if pr <= 10 { score -= 10.0; }

    // Penalize residuals that no typical item (1..=100) can use well:
    // dead space in (0, 10) is worst; (10,20) moderate.
    if pr > 0 && pr < 10 { score += 15.0; }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        // Reward proportionally to how well next item uses leftover
        let waste_after_next = pr - next_item_size;
        score -= 20.0 - (waste_after_next as f64) * 0.5;
        // Harmonic coupling: next item also lands in a good class
        let next_class = (pr - next_item_size) / 10;
        score -= (3 - next_class.min(3)) as f64 * 4.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty
        score += 8.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.55;
        // Cheaper to open a new bin early in the stream (more items to come)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If many open bins can fit the item, opening new bin is wasteful
        score += (fitting_bins_count as f64) * 12.0;
        // Opening a new bin is good if the item would leave bad dead space elsewhere
        // (compare: would this item create a tiny unusable residual in any open bin?)
        if pr >= 0 && item_size >= 60 { score -= 15.0; }
        // Mean residual high => open bins have room; discourage new bin
        score += (mean_residual - cap * 0.3).max(0.0) * 0.3;
    }

    // Mild preference for filling fuller bins (best-fit flavor)
    score -= (bin_residual as f64 / cap) * 5.0;

    // Tie-break noise-free harmonic jitter via class parity
    if class % 2 == 1 { score += 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave gaps still usable by typical items (>=10).
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If post-residual is small but nonzero and next item can't use it, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when existing bins are very full/tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 30.0 * (0.25 - pressure);
        } else {
            score += 25.0 + 50.0 * pressure;
        }
    }

    // Progression: early on, be slightly conservative; later, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: only attractive when open bins are crowded
    // or the item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let crowding = if open_bins_count > 0 { 1.0 } else { 0.0 };
        // Prefer keeping current bins unless they are nearly full on average
        // and the current item is large.
        let large_item = (item_size as f64 / bin_capacity as f64).powi(2) * 40.0;
        score = bin_capacity as f64 * 0.9
            + large_item
            - pressure * 30.0
            - crowding * 10.0 * (1.0 - pressure);
        // If no open bin fits (last chance is this new bin), strongly favor it.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        return score;
    }

    // Exact-ish fit reward: quadratic decay of dead-space penalty.
    let dead = post_residual as f64;
    score += (dead * dead) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual can host
    // the next item snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = (post_residual - next_item_size) as f64;
            // reward tight continuation
            score -= 25.0 * (1.0 - snug / bin_capacity as f64).powi(2);
        } else {
            // next item cannot fit here: penalize proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // Last item: pure tightness packing.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable;
    // dumping into them wastes scarce space, so penalize slightly.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - dead / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that is too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Slight penalty if next item cannot chain here.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Encourage filling bins that are already relatively empty of alternatives:
    // prefer bins with residual close to item size (perfect packing).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * waste;

    // Global state coupling: when many bins are open, prefer consolidation
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score -= 6.0 * progress;
    }

    // Mean residual coupling: if this bin is below mean residual (already fuller),
    // favor it slightly to balance toward closing bins out.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh-bin call mildly.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        // If the item is large relative to capacity, opening fresh is less bad.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
        // If next item is large too, a fresh bin allows pairing big items.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity
            && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear penalty on tiny wastes
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // later in stream -> value tight fits more, penalize large residuals more
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_poly * pr * 0.8;

    // Early stream: mild bonus for keeping bins flexible (larger residuals OK)
    score -= (1.0 - prog_poly) * (bin_residual as f64 - pr) * 0.1;

    // Dead-space penalty: residual too small to fit typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + prog_poly);
        } else {
            // reward residuals that can still host the lookahead item
            score -= 2.0 * prog_poly;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * prog_poly;
    }

    // Spread-awareness: if this bin is far from mean residual, slight penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (0.5 + prog_poly);

    // New-bin candidate: make empty bin moderately attractive only when
    // current fit is terrible (large post residual relative to capacity)
    if bin_residual == bin_capacity {
        score = 8.0 + 60.0 * norm_pr * (1.0 - prog_poly) + 20.0 * norm_pr * prog_poly;
        if fitting_bins_count == 1 {
            score += 30.0; // never open new bin when it's the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible by small denominators (e.g. 10, 20, 25, 50) are more
    // likely to be exactly filled by future items -> reward (subtract).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Odd / prime-ish leftovers are dead space -> penalize.
        if pr % 2 == 1 { score += 3.0; }
        if pr % 5 != 0 && pr % 10 != 0 { score += 2.0; }
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 30.0;
    }

    // Small post-residuals below the minimum item size are dead space.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    let pr_quarter = pr / 25; // 0..=4 class
    score += match pr_quarter {
        0 => -2.0,          // very tight leftover, good packing
        1 => 0.0,
        2 => 1.0,
        3 => 2.5,
        _ => 4.0,           // nearly-empty bin left behind: wasteful
    };

    // Lookahead: does the next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni == pr {
            score -= 20.0; // chain fit
        } else if ni <= pr {
            let slack = pr - ni;
            // Harmonic-class of the slack after the lookahead item.
            if slack % 10 == 0 { score -= 8.0; }
            score += (slack as f64) * 0.15;
        } else {
            // Next item cannot use this bin's leftover; leftover likely stranded.
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (large mean residual mismatch with item) or late in the stream with
    // many open bins already.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap - item_size as f64; // baseline: fresh bin leaves cap - item
        score -= 10.0 * progress;       // slightly prefer fresh bins late
        if mean_gap < 8.0 {
            score += 8.0;               // existing bins fit well; don't open
        }
        if open_bins_count > 4 {
            score += 2.0 * (open_bins_count as f64 - 4.0).min(6.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps super-linearly.
    // A residual gap is "dead" if it's too small to hold even the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0; // harsh penalty for tiny waste
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Fit tightness: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: with many open bins, discourage spreading; favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item could still fit here afterwards
        score -= 3.0;
    } else if next_item_size > post_residual && post_residual < next_item_size {
        // next item won't fit in leftover: leftover likely becomes dead space
        score += 4.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that competes fairly.
    if bin_residual == bin_capacity {
        // opening a new bin is acceptable when open bins have poor mean fit quality
        let poor_fit = mean_residual < item_size as f64;
        let bias = if poor_fit { 5.0 } else { 30.0 + open_bins_count as f64 * 2.0 };
        score += bias;
        // late in stream, prefer reusing existing bins to avoid trailing waste
        score += progress * 10.0;
    }

    // Deviation from mean residual: prefer bins whose residual deviates less (keeps residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect 2-step matches: post_residual == next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // two items perfectly fill the bin
        } else if post_residual > next_item_size {
            // next item fits here afterwards: encourage tight packing
            let slack = pr - nxt;
            score -= 25.0 - slack.min(40.0) * 0.4;
        } else {
            // next item won't fit after this placement: penalize dead space growth
            let gap = nxt - pr;
            score += gap * 0.6;
        }
    }

    // Penalize leaving residuals that are hard to reuse (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no tight fit exists / late in stream
    if bin_residual == bin_capacity {
        score += 15.0; // default penalty: prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual - item_size as f64;
        if waste > 0.0 && next_item_size > item_size {
            // opening a fresh bin can be better when existing bins are wasteful
            score -= (waste * 0.5).min(30.0) + progress * 5.0;
        }
    }

    // Mild preference for bins tighter than the current mean residual
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small waste relative to capacity).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range, min item 1).
    // Small but nonzero post_residual is wasted; zero post_residual is perfect.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // The smaller the dead space relative to the mean residual, the worse (fragmentation).
        score += 12.0 * (1.0 - dead / (mean_residual.max(1.0) + dead));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; if this bin
    // could have fit the next item but the post-residual cannot, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin should be moderately costly,
    // but attractive when existing residuals are badly fragmented or many bins
    // are already open and mean residual is large (poor utilization).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0;
        // As the stream progresses, be more willing to open fresh bins to keep
        // large residual buffers for large future items.
        new_bin_score -= 25.0 * progress;
        // If mean residual across open bins is high, fragmentation is low; keep using them.
        new_bin_score += (mean_residual - 20.0).max(0.0) * 0.6;
        // If open bins are numerous but residuals small, a fresh bin helps.
        if open_bins_count > 3 && mean_residual < 15.0 {
            new_bin_score -= 15.0;
        }
        // Never open a new bin when a near-perfect fit exists elsewhere is handled
        // by the tightness reward of other bins; keep new-bin score positive-ish.
        score = new_bin_score + (post_residual as f64);
    }

    // Mild penalty for using a very full bin when many other bins could fit the item
    // (keep flexibility), unless the fit is tight.
    if fitting_bins_count > 2 && post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic penalty on wasted residual, scaled by progress
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness;

    // Smooth stream-progress coupling: penalize residual more as stream advances
    score += 15.0 * norm_pr * progress * progress;

    // Lookahead: bonus if next item fits in post_residual
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if nxs <= pr {
            score -= 20.0 * (1.0 - (pr - nxs) / cap);
        } else {
            score += 10.0 * (nxs - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // prefer bins with less residual among many fitting bins
        score += 5.0 * norm_pr;
    }

    // Mean-residual coupling: penalize bins far above mean residual (fragmentation)
    score += 8.0 * (pr - mean_residual).abs() / cap;

    // Open-bin pressure: with many open bins, avoid spreading
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: fine-grained classes near zero.
    let pr = post_residual;
    let class = if pr == 0 { 0.0 }
        else if pr <= 5 { 1.0 }
        else if pr <= 10 { 2.0 }
        else if pr <= 20 { 3.0 }
        else if pr <= 30 { 4.0 }
        else { 5.0 };
    score += class * 4.0;

    // Modulo-10 harmonic of post residual: exact-decade leftovers are reusable.
    let dec = (pr % 10) as f64;
    score -= (10.0 - dec) * 0.6;

    // Reward tight fits strongly.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 25.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize moderately so we prefer decent existing fits,
    // but allow opening when existing fits are poor (large residual class).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Progress pressure: late in the stream, consolidate into fewer bins.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64).abs() * 0.2 * prog;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps (< 10, minimum item size)
    // are unusable dead space -> heavy penalty proportional to wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderately small gaps that next_item_size could still use are fine;
    // if next item cannot fit in the gap, penalize the stranded space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap reusable by lookahead: reward keeping it
        score -= 3.0;
    }

    // Reward filling large bins (big residual consumed is good).
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Open-bins pressure: with many open bins, prefer packing into existing ones;
    // new bin (residual == capacity) gets penalized proportionally to open count.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 6.0;
    } else {
        score -= open_bins_count as f64 * 0.8;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, be extra conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strong reward, scaled by tightness of that fit.
            let next_leftover = (post_residual as f64 - next_item_size as f64).abs();
            score -= 60.0 * (1.0 - next_leftover / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize wasted space a bit.
            score += 15.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Penalize large dead space relative to mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Mildly prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual - item_size) as f64 / bin_capacity as f64;

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If lookahead shows next item could pair with this item in a fresh bin, soften.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 8.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins when
    // open bins have large residuals, but encourage when residuals are small.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / (bin_capacity as f64)) * (open_bins_count as f64).sqrt();
        score += 35.0 * pressure;
        if post_residual as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Time horizon: early in stream, be conservative with bins (penalize fills);
    // late in stream, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / (bin_capacity as f64));

    // Prefer bins with residual close to the mean (balanced packing) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 5.0 * dev / (bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    score += 12.0 * (pr / 100.0) * (pr / 100.0) * (1.0 + t);
    // Penalize dead space that next item cannot use
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 * (1.0 - t);
    }
    // Reward tight fits
    score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * (0.5 + t);
    // Bias toward opening fresh bins late when mean residual is high
    if bin_residual == bin_capacity {
        score -= 5.0 + 10.0 * t * (mean_residual / 100.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that fall into "usable" classes.
    // Class A: post_residual is a multiple of 10 (aligns with typical item sizes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class B: post_residual >= 50 (half bin) is a large usable class.
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    }
    // Class C: dead space — very small residuals are nearly unusable (items >= 1... but typical sizes 10..80).
    if post_residual < 10 {
        score += 15.0;
    }
    // Modulo coupling: post_residual mod 10 close to 0 is better than mid-class.
    let m = post_residual % 10;
    score += (5 - m.min(10 - m)) as f64 * 0.4;

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        if post_residual - next_item_size < 10 {
            score -= 4.0; // near-perfect two-item packing
        }
    }
    // If next item does NOT fit here, penalize mildly, scaled by how much it misses.
    if next_item_size > post_residual {
        score += ((next_item_size - post_residual) as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is huge and would leave awkward residue, opening fresh is fine.
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
        // Late in stream, prefer closing out open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.85 {
            score -= 6.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.8 {
        score -= 3.0 * (fill - 0.8);
    }

    // Prefer bins with below-mean residual (consolidate waste into few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Integer-division threshold: residual in [20, 30) or [40, 50) are decent classes.
    let q = post_residual / 20;
    if q == 1 || q == 2 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // are wasted capacity; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into yet another bin,
    // encourage filling existing ones (unless it's the fresh-bin candidate).
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 0.3;
    } else {
        // New-bin candidate: penalize when open bins are still relatively empty,
        // so we only open a new bin when existing residuals are large.
        score += mean_residual * 0.4 + (open_bins_count as f64) * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward leaving that gap; if it clearly cannot use it, penalize dead space more.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits into post_residual with small slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally.
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow.min(50.0);
    }

    // Compare post_residual against mean residual: keep bin residuals balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer tight fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Slight preference for reusing bins over opening new ones late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it offers an exact 2-step match.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 5.0;
        } else {
            score += 15.0 + 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residuals below the smallest item (assume ~1..10 range)
    // are unusable; penalize small but nonzero post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: favor leaving space for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin good for pairing large items
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling them.
    if mean_residual > 20.0 && open_bins_count > 2 {
        score -= 0.05 * mean_residual;
    }

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, penalize residual more
    score += 30.0 * norm_pr * norm_pr * progress;

    // Penalize waste relative to mean residual (dead-space coupling)
    score += 0.5 * (pr - mean_residual).abs();

    // Reward tight fits: smooth bonus when post_residual is small
    score -= 40.0 * (1.0 - norm_pr).powi(6);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 8.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Many open bins: slight penalty to discourage bin proliferation
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize leftovers in "dead zone" classes (too small for typical items).
    if post > 0 {
        if post < 10 {
            score += 40.0; // unusable dead space
        } else if post < 20 {
            score += 18.0;
        } else if post < 35 {
            score += 6.0;
        } else if post < 50 {
            score -= 2.0;
        } else {
            score -= 5.0; // roomy leftover, keep flexibility
        }
    }

    // Perfect-fit harmonic classes: modulo arithmetic on post_residual.
    let m10 = post_residual % 10;
    if post_residual > 0 {
        if m10 == 0 {
            score -= 8.0; // aligned to decade grid, easy to fill later
        } else {
            score += (m10 as f64) * 0.8; // off-grid remainder penalty
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nf = next_item_size as f64 / cap;
            // reward when leftover fraction is close to next item fraction
            score -= 12.0 * (1.0 - (frac - nf).abs());
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Progress-based bias: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - (bin_residual as f64));

    // New-bin candidate: make it mildly unattractive unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (sizes >= 1, but conservatively < 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.5 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill is gold
    }

    // Reward tight fits relative to the item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor filling existing bins over opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Exception: huge item with no good home — allow a fresh bin.
        if item_size >= 70 {
            score -= 55.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0; // dead space for the known next item
        }
    }

    // Late in the stream, tighten up: prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild attraction toward bins with below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (next_item_size as f64) * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // dead space relative to next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Tight fit reward: fraction of bin used
    score -= 2.0 * (item_size as f64 / bin_residual as f64) * 100.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive if current bin would leave large dead space
    if bin_residual == bin_capacity {
        score += 250.0;
        if post_residual > 40 {
            score += 100.0;
        }
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 150.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Slight preference for older bins as stream progresses
    score -= 0.1 * (step_index as f64 / total_items.max(1) as f64) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
