pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on: prefer larger post_residual (keep bins flexible).
    // Late: prefer tight fits (small post_residual) to close bins out.
    let tightness = 1.0 - norm_pr;
    let base = 2.0 * norm_pr * norm_pr
        + norm_pr * (0.5 + 2.0 * progress)
        - 1.5 * tightness * tightness * (1.0 - progress);

    // Reward a post_residual that exactly accommodates the lookahead item
    // (smooth quadratic gap, only meaningful when a next item exists).
    let next_gap = if next_item_size > 0 && next_item_size <= post_residual {
        let g = (pr - norm_next * cap) / cap;
        -1.2 * (1.0 - g * g)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (scaled smoothly by scarcity).
    let scarcity = 1.0 / (fitting_bins_count as f64);
    let last_chance = if fitting_bins_count == 1 { -2.5 * scarcity * (1.0 + progress) } else { 0.0 };

    // Mild penalty for deviating far from the mean residual across open bins,
    // encouraging balanced residual distribution.
    let balance = 0.3 * (norm_pr - mean_residual / cap) * (norm_pr - mean_residual / cap);

    // New-bin candidate (empty bin): penalize mildly so it is only chosen when
    // open bins fit poorly; penalty grows with progress (consolidate late).
    let new_bin_penalty = if bin_residual == bin_capacity {
        1.0 + 1.5 * progress + 0.5 * norm_item
    } else {
        0.0
    };

    let mut score = base + next_gap + last_chance + balance + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual is good, but a tiny unusable
    // sliver (1..10) is worse than a moderate gap that later items can fill.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 18.0 - (pr as f64) * 0.9; // sliver trap
    }

    // Perfect / near-perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Harmonic class of post_residual: residues that commonly recombine with
    // typical item sizes get a bonus. Items 1..100, so residual classes
    // divisible by common small sizes (10, 20, 25, 50) are reusable.
    let reusable = pr % 10 == 0 || pr % 25 == 0;
    if reusable && pr > 0 {
        score -= 8.0 + (pr as f64) * 0.05;
    }
    // Odd prime-ish residues tend to strand; mild penalty.
    if pr > 0 && pr % 2 == 1 && pr % 5 != 0 && pr < 30 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; residual must hold future stream.
            score += 3.0;
        }
        // Harmonic pairing: next item plus post_residual sums to a capacity
        // fraction threshold, indicating a clean two-item closure.
        if next_item_size + pr <= bin_capacity && (next_item_size + pr) % 50 == 0 {
            score -= 10.0;
        }
    }

    // Last chance: only this bin can fit the item -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins offer poor fits (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall (best-fit flavor with mean coupling).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

