        score += 15.0;
    }

    // Stream progression: early on, prefer consolidation; later, allow slight slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty on waste.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let slack = post_residual as f64 - next;
            // Perfect chain fit (next item fills bin exactly) is heavily rewarded.
            score -= 22.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leftover after the chain that is likely dead space.
            score += 0.25 * slack;
        } else {
            // Next item cannot chain here; penalize proportionally to the miss.
            score += 0.9 * (next - post_residual as f64).min(30.0);
        }
    }

    // Relative-to-mean coupling: bins below mean residual are already "tight",
    // prefer filling them further; bins far above mean are wasteful targets.
    let dev = mean_residual - post_residual as f64;
    score += 0.45 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual <= 8 {
            score -= 10.0; // near-perfect single fit
        }
    }

    // New-bin candidate handling: empty bin should only win when the current
    // fit is poor (large post_residual) or lookahead demands fresh space.
    if bin_residual == bin_capacity {
        let good_fit = post_residual as f64 <= 15.0;
        let chain = next_item_size > 0 && post_residual as f64 >= next_item_size as f64
            && (post_residual as f64 - next_item_size as f64) <= 10.0;
        if good_fit || chain {
            score += 60.0; // keep item in an open bin
        } else {
            score -= 6.0; // allow opening a fresh bin for poor fits
        }
        // Slight bias against hoarding open bins early in the stream.
        score -= 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}
